(window.MUSEUM_READ_T = window.MUSEUM_READ_T || {})["de"] = {"ui":{"lead":"Wie wurden Spiele gefunden, vergessen, entschlüsselt und verändert? Lies {n} Geschichten und beantworte alle Fragen des Quiz am Ende richtig, um einen Stempel zu bekommen.","card":"Stempelkarte","cardN":"{n} von {of} gesammelt","cardAll":"Alle gesammelt!","no":"Geschichte {n}","mins":"{n} Min.","stamped":"Gestempelt","back":"Alle Geschichten","quiz":"Kurzes Quiz","links":"Ansehen und spielen","game":"Spiel","exhibit":"Sammlung","art":"Kunstwerk","room":"Saal","room_chance":"Zufall","qn":"Frage {n} von {of}","right":"Richtig!","wrong":"Leider nicht – die richtige Antwort ist markiert.","got":"Gestempelt!","again":"Alles richtig!","gotSub":"Er steht auf deiner Stempelkarte.","missed":"{n} falsch","retrySub":"Nur wer alle Fragen richtig beantwortet, bekommt den Stempel. Lies die Geschichte noch einmal und versuch es erneut.","retry":"Noch einmal","room_paint":"In der Kunst","room_map":"Karte","kfH":"Das Wichtigste","tlH":"Zeitleiste","refH":"Quellen und Literatur","picLink":"öffnet die Seite des Museums"},"ex":{"ur":"Spielbrett des Königlichen Spiels von Ur","liubo":"Liubo-Brett und Figuren","pyrgus":"Römischer Würfelturm","sugoroku":"Sugoroku-Brett des Shōsōin","nishapur":"Schachspiel aus Nischapur","lewis":"Lewis-Schachfiguren","senet":"Tutanchamuns Senet-Kasten","ballinderry":"Spielbrett von Ballinderry","goose":"Schach- und Gänsespielbrett","kofukuji":"Shogi-Figuren aus dem Kōfuku-ji","shosoin":"Go-Brett des Shōsōin"},"paint":{"liubo":"Zwei Liubo-Spieler (Grabfiguren)","sugoroku":"Zwei Mädchen beim Sugoroku","shahnama":"Buzurgmihr ergründet das Schach","nefertari":"Königin Nefertari beim Senet","chaupar":"Shiva und Parvati beim Chaupar","shogi":"Junges Paar beim Shogi","hydria":"Achill und Aias beim Brettspiel (Hydria)","eakins":"Die Schachspieler","weiqi":"Schale mit Unsterblichen beim Weiqi","webb":"Die Backgammonspieler (Schrank)","liberale":"Die Schachspieler","mirror":"Spiegelkapsel mit Schach spielendem Paar","morris":"Ein Spielbrett (Mühle)","leifeng":"Brettspiel der Leifeng-Pagode","teniers":"Die Backgammonpartie","imari":"Schale mit zwei Go-Spielern","shoei":"Die vier Künste","tutinama":"Der Affe beißt den Prinzen, seinen Schachpartner (Mogul, um 1560)","ingram":"Das chinesische Schachspiel","umaya":"Stallschirm (Go und Shogi auf der Veranda)","kiyohiro":"Sugoroku-Spielerinnen","vuillard":"Die Damepartie (aus Landschaften und Interieurs)","kangra":"Paar beim Chaupar auf einer Terrasse","posada":"Das Gänsespiel","jintile":"Fliese mit Frauen beim Brettspiel","pvl":"Würfelspielende Männer"},"ur":{"title":"Wie ein 4500 Jahre altes Spiel seine Regeln zurückbekam","lead":"Das Brett aus den Königsgräbern von Ur kam ohne Anleitung. Den Schlüssel lieferte eine Tontafel, zweitausend Jahre später geschrieben.","s":["In den 1920er-Jahren grub Leonard Woolley die Königsgräber von Ur im Südirak aus und fand ein Brett mit zwanzig Feldern, eingelegt mit Muschel und Lapislazuli, aus der Zeit um 2600–2400 v. Chr. Ähnliche Bretter tauchten im ganzen Nahen Osten auf – das Spiel war also weit verbreitet und lange beliebt.","Doch nichts, was die Spielweise erklärte, wurde mit ihnen gefunden. Brett, Figuren und Würfel – aber keine Regeln: ein vertrautes Problem bei alten Spielen.","Der Schlüssel lag im Magazin des British Museum: eine Keilschrifttafel, die der babylonische Schreiber Itti-Marduk-balāṭu 177/176 v. Chr. von einer Tafel eines gewissen Iddin-Bēl abschrieb. Sie entstand mehr als zweitausend Jahre nach dem Brett.","Anfang der 1980er-Jahre erkannte Irving Finkel vom British Museum, dass die Tafel dasselbe Zwanzig-Felder-Spiel beschreibt. Ihre Rückseite zeigt das Brett mit Vorzeichen für die Felder, auf denen man landet. Aus der Tafel und dem Brett selbst rekonstruierte Finkel ein Wettlaufspiel für zwei.","Seine Rekonstruktion wird heute in aller Welt gespielt. Ob man in Ur genau so spielte, kann niemand sagen. Doch im südindischen Kochi wurde ein ähnliches Spiel noch bis in die 1950er-Jahre gespielt – ein Zeichen für das lange Leben dieses Spiels."],"quiz":[["Wann wurde die Tafel geschrieben, die die Regeln lieferte?","Im 2. Jh. v. Chr., über 2000 Jahre nach dem Brett","Um 2600 v. Chr., wie das Brett","Im Mittelalter (12. Jh.)","Im 19. Jahrhundert"],["Wer entschlüsselte die Tafel und rekonstruierte die Regeln?","Irving Finkel","Howard Carter","Jean-François Champollion","Arthur Evans"],["Was sagt die Tafel über das Landen auf den Feldern?","Vorzeichen – Glück oder Unglück","Namen von Königen","Steuerbeträge","Nur Sternnamen"]],"kf":["Die Bretter stammen aus der Zeit um 2600–2400 v. Chr., aus den Königsgräbern von Ur im Südirak","Die Regeln wurden nach einer über 2000 Jahre jüngeren Tontafel rekonstruiert","20 Felder, sieben Steine je Seite, vierseitige Würfel"],"more":[{"h":"Königsgräber und ein „königliches Spiel“","p":["Woolley fand auf dem Königsfriedhof von Ur nicht ein, sondern mehrere Zwanzig-Felder-Bretter. Das bekannteste, heute im British Museum, ist aus Holz mit Einlagen aus Muschel, rotem Kalkstein und Lapislazuli – daher der Name „Königliches Spiel von Ur“.","Doch es war kein Spiel nur für Könige. Gleiche Bretter fanden sich von Mesopotamien bis Ägypten und im östlichen Mittelmeer, und in einem assyrischen Palast wurde sogar eines in den Sockel eines großen geflügelten Stiers mit Menschenkopf geritzt, der ein Tor bewachte – offenbar von den Wachen."],"cap":["Das Königliche Spiel von Ur im British Museum – im Raum „Sammlung“ in 3D drehbar"]},{"h":"Wie das Brett funktioniert","p":["Die zwanzig Felder bestehen aus einem Block von zwölf (3×4) und einem von sechs (3×2), verbunden durch eine schmale „Brücke“ aus zwei Feldern. Fünf Felder tragen eine Rosette; in den rekonstruierten Regeln bringt ein solches Feld einen weiteren Wurf und Schutz vor dem Schlagen.","Die Würfel sind Tetraeder, bei denen zwei der vier Spitzen markiert sind. Man wirft vier und zieht so viele Felder, wie markierte Spitzen oben liegen: 0 bis 4. Am häufigsten ist 2 (6-mal von 16); 0 und 4 kommen nur einmal von 16. Im Museumsraum „Zufall“ kannst du sie selbst werfen."],"cap":["Die zwanzig Felder und die fünf Rosetten. Die grünen Zahlen zeigen den Weg eines Spielers Feld für Feld (rekonstruierte Regeln)","Wie vier Tetraeder-Würfel fallen (von 16 gleich wahrscheinlichen Fällen)"]},{"h":"Was die Tontafel sagt","p":["Die Vorderseite erklärt das Spiel, die Rückseite zeigt das Brett mit Tierkreiszeichen in den Feldern. Die Sprüche zu den Feldern klingen wie Orakel – „du wirst einen Freund finden“, „du wirst gutes Bier trinken“ –, das Spiel war also mit Glück und Vorzeichen verbunden.","Die Tafel ist allerdings teilweise zerbrochen, nicht jede Regel ist lesbar. Finkels Rekonstruktion setzt aus den lesbaren Zeilen und der Brettform das stimmigste Spiel zusammen; andere Forscher haben andere Fassungen vorgeschlagen."]},{"h":"Die letzten Spieler, in Indien","p":["Finkel erfuhr später, dass die jüdische Gemeinde von Kochi (Cochin) in Südindien bis vor Kurzem ein Zwanzig-Felder-Spiel auf einem sehr ähnlichen Brett gespielt hatte.","Es wurde in den Familien weitergegeben, bis sie in den 1950er-Jahren nach Israel zogen. Vielleicht gelangte das Spiel über alte Handelswege nach Indien und lebte über viertausend Jahre fort."]}],"tl":[["um 2600–2400 v. Chr.","Zwanzig-Felder-Bretter kommen in die Königsgräber von Ur"],["8. Jh. v. Chr.","Ein Brett wird in den Sockel eines Torwächters eines assyrischen Palasts geritzt"],["177/176 v. Chr.","Ein babylonischer Schreiber kopiert die Regeltafel"],["1922–1934","Woolley gräbt Ur aus und findet die Bretter"],["Anfang der 1980er","Finkel liest die Tafel und rekonstruiert die Regeln"],["Bis in die 1950er","In Kochi in Südindien wird ein sehr ähnliches Spiel gespielt"]]},"liubo":{"title":"Warum verschwand Liubo?","lead":"Unter den Han spielten es alle, vom Kaiser bis zum Volk. Nach wenigen Jahrhunderten waren sogar die Regeln vergessen.","s":["Liubo war die große Leidenschaft im China der Han-Zeit (206 v. Chr. – 220 n. Chr.). Es erscheint auf Grabfiguren, Steinreliefs und sogar als Muster auf Spiegeln, und oft werden Unsterbliche beim Spiel gezeigt.","Nach dem Ende der Han verfiel Liubo rasch; in der Tang-Zeit waren seine Regeln offenbar schon verloren. Warum, ist unklar – eine Ansicht lautet, dass sich die Spieler anderen Spielen wie Weiqi (Go) zuwandten.","Erhalten blieben Bretter und Geräte. Die Bretter tragen ein typisches Muster aus T-, L- und V-Formen, und die Züge wurden vermutlich durch das Werfen dünner Stäbchen bestimmt. Dasselbe Muster ziert die sogenannten TLV-Spiegel.","Auch schriftliche Hinweise kommen allmählich zusammen. 1993 fand man in einem Han-Grab in Yinwan (Jiangsu) einen Wahrsagetext, der das Brettdiagramm verwendet. Das in den 2010er-Jahren ausgegrabene Grab des Liu He, Markgraf von Haihun, lieferte über tausend Bambusstreifen zum Liubo, die noch erforscht werden.","Das Liubo im Atlas ist eine Rekonstruktion auf Grundlage solcher Hinweise. Fachleute rekonstruieren es etwas unterschiedlich, und die echten Regeln sind noch nicht vollständig bekannt – neue Funde könnten das Spiel noch verändern."],"quiz":[["In welcher Dynastie war Liubo sehr beliebt?","Han","Ming","Qing","Song"],["Wo fand man über tausend Bambusstreifen zum Liubo?","Im Grab des Liu He, Markgraf von Haihun","Im Mausoleum des Ersten Kaisers","In den Höhlen von Dunhuang","In der Verbotenen Stadt"],["Was wurde beim Liubo vermutlich geworfen, um die Züge zu bestimmen?","Dünne Stäbchen","Ein zwanzigseitiger Würfel","Ein Kreisel","Bildkarten"]],"kf":["In China von den Streitenden Reichen bis zur Han-Zeit (5. Jh. v. Chr. – 3. Jh. n. Chr.) sehr beliebt","Ein Brett mit T-, L- und V-förmigen Linien; geworfen wurden dünne Stäbchen","Nach dem Ende der Han verschwand es rasch; die Regeln sind bis heute nicht ganz bekannt"],"more":[{"h":"Das TLV-Brett","p":["Ein Liubo-Brett ist quadratisch, mit einem Quadrat in der Mitte, einem T in der Mitte jeder Seite, L-Formen darum und V-Formen in den Ecken. Die Steine zogen vermutlich auf und zwischen diesen Linien.","Dieselben Linien finden sich auf Spiegelrückseiten („TLV-Spiegel“) und auf Sonnenuhren. Manche Forscher lesen das Brett als Weltkarte – Himmel, Erde und die vier Richtungen –, ein Hinweis, dass Liubo mehr als Zeitvertreib war."],"cap":["Die Linien eines Liubo-Bretts (TLV-Muster): ein Quadrat in der Mitte, ein T an jeder Seite, L- und V-Formen zu den Ecken"]},{"h":"Wie man spielte","p":["Die meisten Forscher meinen, dass jeder Spieler sechs Steine hatte und dünne Bambusstäbchen warf, um den Zug zu bestimmen. Die „Sechs“ (liu) im Namen soll von diesen sechs Stäbchen oder Steinen kommen.","Ein vorgerückter Stein wurde offenbar zur mächtigen „Eule“ (xiao). Ein Gedicht aus etwa dem 3. Jh. v. Chr., „Die Seele zurückrufen“ in den Liedern von Chu, sagt: „zur Eule geworden, drängt man vor und ruft ‚fünf Weiße!‘“. Texte beschreiben auch eine Spielweise, bei der man im „Wasser“ in der Brettmitte „Fische“ fing."],"cap":["Zwei Liubo-Spieler, für ein Han-Grab gefertigt (Metropolitan Museum of Art)"]},{"h":"Spiele aus den Gräbern","p":["Grab 3 von Mawangdui in Changsha (Hunan), um 168 v. Chr., enthielt einen vollständigen Satz – Brett, Steine und Stäbchen – in einem Lackkasten, damit der Tote im Jenseits spielen konnte.","Reliefs an Grabwänden zeigen oft Unsterbliche, die auf Berggipfeln Liubo spielen. Das Spiel war mit der Welt der Unsterblichen und dem langen Leben verbunden."],"cap":["Das Liubo-Brett des Museums – im Raum „Sammlung“ in 3D zu sehen"]}],"tl":[["5.–3. Jh. v. Chr. (Streitende Reiche)","Liubo-Bretter werden in Gräber gelegt"],["um das 3. Jh. v. Chr.","„Die Seele zurückrufen“ beschreibt eine Liubo-Partie"],["um 168 v. Chr.","Ein vollständiger Satz kommt in Grab 3 von Mawangdui"],["206 v. Chr. – 220 n. Chr. (Han)","Von Kaisern bis zum einfachen Volk gespielt; auf Reliefs und Spiegeln"],["Tang (7.–10. Jh.)","Die Regeln waren vermutlich schon vergessen"],["1993","Aus den Han-Gräbern von Yinwan kommt ein Orakeltext mit dem Brett"],["2010er","Bambusleisten zum Liubo im Grab des Markgrafen von Haihun, Liu He"]]},"zeno":{"title":"Kaiser Zenons Pechwurf","lead":"Vor fünfzehnhundert Jahren warf ein Kaiser die Würfel – und das Ergebnis ist in einem Gedicht erhalten.","s":["Die Römer liebten Tabula, ein Würfel-Wettlaufspiel auf einem Brett mit 24 Zungen – den Vorfahren des Backgammon. Um gezinkte Würfe zu verhindern, nutzten sie sogar Würfeltürme, in denen die Würfel hinabkollerten.","Um 480 spielte der oströmische Kaiser Zenon Tabula. Seine drei Würfel zeigten 2, 5 und 6. Er musste ziehen, wie es die Regeln verlangten, und auf seinem Brett standen danach acht Steine allein und ungeschützt.","Festgehalten hat die Partie Agathias, ein Historiker und Dichter des 6. Jahrhunderts, der einige Jahrzehnte nach Zenon lebte. Sein kurzes Gedicht (ein Epigramm) nennt die Stellung der Steine – ein seltenes Zeugnis einer antiken Partie.","Im 19. Jahrhundert erschloss der französische Gelehrte Becq de Fouquières aus dem Gedicht Stellung und Regeln: fünfzehn Steine pro Spieler und drei Würfel. Alle Steine beginnen außerhalb des Bretts, und beide Spieler ziehen in dieselbe Richtung.","Anders als das heutige Backgammon nutzte Tabula drei Würfel, begann ohne Steine auf dem Brett und kannte keinen Dopplerwürfel. Dank dem Pech eines Kaisers wissen wir, wie Tabula aussah."],"quiz":[["Was würfelte Zenon?","2, 5 und 6","6, 6 und 6","1, 1 und 1","3, 4 und 5"],["Wer hielt die Partie in einem Gedicht fest?","Agathias","Homer","Plinius","Cicero"],["Was unterscheidet Tabula vom heutigen Backgammon?","Tabula nutzte drei Würfel","Dreißig Steine pro Spieler","Ein Brett mit 12 Zungen","Die Steine ziehen rückwärts"]],"kf":["Tabula wurde mit 24 Zungen und drei Würfeln gespielt – ein Vorfahr des Backgammon","Kaiser Zenons Partie um 480 ist samt Stellung in einem Gedicht erhalten","Die Römer bauten sogar „Würfeltürme“ gegen Betrug"],"more":[{"h":"Das Tabula-Brett","p":["Das Tabula-Brett hat wie das heutige Backgammon 24 Zungen in zwei Reihen zu 12. Jeder Spieler hatte fünfzehn Steine, die anfangs alle außerhalb lagen; nach drei Würfeln wurden sie eingesetzt, liefen herum und wurden ausgewürfelt.","Der große Unterschied zum Backgammon: Beide Spieler ziehen in dieselbe Richtung. Ein einzeln stehender Stein konnte geschlagen werden, wenn der Gegner auf seine Zunge kam, und musste neu einsetzen. Zenons acht waren genau solche verwundbaren Steine."],"cap":["Ein Tabula-Brett: 24 Zungen in zwei Reihen zu 12; die Steine beider Spieler laufen in dieselbe Richtung (Pfeil)"]},{"h":"Ein Gerät gegen Betrug","p":["Die Römer liebten das Würfeln. Glücksspiel war verboten und angeblich nur während der Saturnalien im Winter erlaubt – doch gewettet wurde immer, und auch mit flinken Fingern betrogen.","Daher der Würfelturm: Oben eingeworfene Würfel prallen an inneren Brettchen ab und rollen unten heraus. Ein Turm des 4. Jahrhunderts aus einer Villa in Deutschland trägt durchbrochen die Worte „Die Pikten besiegt, der Feind vernichtet – spielt unbesorgt“."],"cap":["Der Würfelturm von Vettweiß-Froitzheim (4. Jh.) – im Raum „Sammlung“ in 3D zu sehen"]},{"h":"Kaiser und Würfel","p":["Zenon war nicht der Einzige. Nach dem Historiker Sueton liebte Kaiser Claudius im 1. Jahrhundert das Würfeln so sehr, dass er ein Buch über diese Kunst schrieb und seinen Wagen so einrichten ließ, dass das Brett beim Spielen nicht verrutschte.","Römische Fundorte liefern auch viele Bretter mit 36 Buchstaben in Wörtern zu sechs; jeder Buchstabe diente als Feld, und manche tragen Spott wie „Steh auf, du kannst nicht spielen – mach Platz für einen Spieler“."],"cap":["Tables und Würfel erfreuten Kaiser wie Soldaten (würfle mit Sechsflächnern im Raum „Zufall“)"]}],"tl":[["1. Jh.","Kaiser Claudius schreibt ein Buch über das Würfelspiel"],["4. Jh.","In einer Villa in Deutschland wird ein Würfelturm benutzt"],["um 480","Kaiser Zenons unglückliche Partie"],["6. Jh.","Agathias fasst die Partie in Verse"],["um das 10. Jh.","Das Gedicht kommt in die Griechische Anthologie"],["1869","Becq de Fouquières erschließt Stellung und Regeln"],["1934","R. G. Austin prüft Zenons Partie eingehend neu"]]},"sugoroku":{"title":"Das verbotene Sugoroku","lead":"Die Herrscher verboten es, das Volk spielte weiter. Die Geschichte des Brett-Sugoroku in Japan, von der Antike bis zur Edo-Zeit.","s":["Das Schatzhaus Shōsōin bewahrt ein Sugoroku-Brett, das der Überlieferung nach Kaiser Shōmu besonders schätzte. Gemeint ist nicht das Sugoroku aus bedrucktem Papier, sondern Ban-Sugoroku, bei dem weiße und schwarze Steine auf einem Brett gezogen werden – ein Verwandter des Backgammon.","Sugoroku war früh mit Glücksspiel verbunden. Laut dem Nihon Shoki verbot Kaiserin Jitō es im Jahr 689.","Auch der ab 757 geltende Yōrō-Kodex untersagte Mönchen und Nonnen das Sugoroku. Die Verbote wurden immer wieder erneuert – ein Zeichen, dass sie nicht befolgt wurden.","In der Heian-Zeit blieb Sugoroku beliebt und taucht im Kopfkissenbuch und in der Geschichte vom Prinzen Genji auf. Das Heike Monogatari erzählt, der abgedankte Kaiser Shirakawa habe drei Dinge genannt, die er nicht beherrschen könne: das Wasser des Kamo-Flusses, die Würfel des Sugoroku und die Kriegermönche vom Berg Hiei.","Holzschnitte der Edo-Zeit zeigen noch junge Frauen beim Ban-Sugoroku im Haus. Doch bis zur Meiji-Zeit war das Brettspiel fast verschwunden, und „Sugoroku“ bezeichnete fortan das Papier-Bilderspiel."],"quiz":[["Mit welchem Spiel ist Ban-Sugoroku wie das Shōsōin-Brett verwandt?","Backgammon","Shogi","Go","Spielkarten"],["Wer verbot Sugoroku laut dem Nihon Shoki im Jahr 689?","Kaiserin Jitō","Kaiser Shōmu","Kaiser Kanmu","Kaiser Meiji"],["Shirakawa beherrschte weder den Kamo-Fluss noch die Kriegermönche – und was noch nicht?","Die Würfel des Sugoroku","Shogi-Figuren","Go-Steine","Einen Kemari-Ball"]],"kf":["Ban-Sugoroku ist ein Verwandter des Backgammon und wurde in Japan schon im 7. Jahrhundert gespielt","Wegen des Glücksspiels wurde es immer wieder verboten, zuerst 689 von Kaiserin Jitō","In der Meiji-Zeit war es fast vergessen; „Sugoroku“ meinte nun das Bilderspiel auf Papier"],"more":[{"h":"Das Brett im Shōsōin","p":["Das Brett im Shōsōin ist aus Palisander mit feinen Einlagen aus Elfenbein und gefärbten Hölzern. Es hat 24 Felder, zwölf auf jeder Seite, mit Blumen auf dem Mittelsteg.","Im Shōsōin liegen auch viele Sugoroku-Steine aus Glas und Stein. Ban-Sugoroku wird mit fünfzehn weißen und fünfzehn schwarzen Steinen und zwei Würfeln gespielt – fast dieselbe Ausstattung wie Backgammon. Es kam vermutlich vom persischen Nard über China."],"cap":["Das Sugoroku-Brett des Shōsōin aus eingelegtem Palisander – im Raum „Sammlung“ spielbar"]},{"h":"Wie man spielt","p":["Jeder stellt fünfzehn Steine nach festem Muster auf und zieht nach zwei Würfeln. Weiß und Schwarz laufen in entgegengesetzte Richtungen; wer zuerst alle Steine in den letzten sechs Feldern sammelt, gewinnt.","Ein einzelner Stein kann geschlagen und zum Start zurückgeschickt werden. Ein Feld mit zwei oder mehr Steinen ist für den Gegner gesperrt – die Kunst ist es, Blockaden zu bauen. Im Raum „Sammlung“ kannst du so auf dem Shōsōin-Brett spielen."],"cap":["Ein Ban-Sugoroku-Brett (Schema): die 24 Felder, Weiß und Schwarz laufen gegeneinander"]},{"h":"Verbote und Moden","p":["Nach Jitō wurde Sugoroku noch oft verboten, denn immer wieder verspielten Leute ihr ganzes Vermögen. Auch das Kamakura-Shogunat erließ Gesetze gegen Wetten beim Sugoroku.","Zugleich war es eine Fertigkeit des Adels. Ein schönes Brett gehörte zur Aussteuer der Braut, und in der Edo-Zeit entstanden prächtige Lackbretter. Gehasst als Glücksspielgerät, geliebt als Schatz – Ban-Sugoroku hatte beide Gesichter."],"cap":["Ban-Sugoroku auf einem Bild der Edo-Zeit (Raum „Gemalte Spiele“)"]}],"tl":[["7. Jh.","Ban-Sugoroku kommt aus China"],["689","Kaiserin Jitō verbietet Sugoroku (Nihon shoki)"],["8. Jh.","Das eingelegte Brett kommt ins Shōsōin"],["757","Der Yōrō-Kodex verbietet es Mönchen und Nonnen"],["Heian-Zeit","Sugoroku im Kopfkissenbuch und im Genji monogatari"],["12. Jh.","Shirakawas Klage über „die Würfel des Sugoroku“ (Heike monogatari)"],["Edo-Zeit","Prächtige Bretter für die Aussteuer"],["Meiji-Zeit","Ban-Sugoroku wird kaum noch gespielt"]]},"queen":{"title":"Wie die Dame zur stärksten Schachfigur wurde","lead":"Die mächtigste Figur von heute war anfangs ein Ratgeber, der nur ein Feld diagonal ziehen durfte.","s":["Das Schach wanderte von Indien nach Persien und in die arabische Welt. Im persischen Epos Schahname löst der Weise Buzurgmihr das aus Indien gesandte Rätsel des Schachs. Auf diesen Brettern stand neben dem König der Fers, der Ratgeber.","Der Fers zog nur ein Feld diagonal – eine sehr schwache Figur. Im Schachspiel des 12. Jahrhunderts aus Nischapur im Iran ist er ein kleiner Thron, kleiner als der des Königs.","In Europa wurde aus dem Ratgeber eine Königin; unter den Lewis-Schachfiguren des 12. Jahrhunderts gibt es Königinnen. Doch der neue Name änderte die Gangart nicht: Sie blieb schwach.","Die große Wende kam Ende des 15. Jahrhunderts in Spanien. Scachs d’amor („Schach der Liebe“), ein um 1475 in Valencia verfasstes Gedicht, gilt als ältestes Zeugnis der modernen Dame, die beliebig weit auf Reihen, Linien und Diagonalen zieht. Die Bücher von Lucena (1497) und Damiano (1512) verbreiteten die neue Regel dann in ganz Europa.","Warum die Dame so stark wurde, ist nicht sicher. Manche meinen, man wollte schnellere Partien; andere verweisen auf den Einfluss mächtiger Königinnen wie Isabella I. Jedenfalls brachte die Änderung das Schach dem heutigen Spiel sehr nahe."],"quiz":[["Welche Figur stand im persischen und arabischen Schach an der Stelle der Dame?","Der Fers (Ratgeber)","Der Elefant","Der Streitwagen","Der Springer"],["Wie zog der ursprüngliche Fers?","Ein Feld diagonal","Beliebig weit geradeaus","Er sprang zwei Felder","Er konnte nicht ziehen"],["Wo entstand das Gedicht mit dem ältesten Zeugnis der modernen Dame?","In Valencia, 15. Jh.","In Indien, 6. Jh.","Auf Lewis, 12. Jh.","In London, 19. Jh."]],"kf":["Die Dame begann als persischer und arabischer „Fers“ (Ratgeber), der nur ein Feld diagonal ziehen konnte","Die starke moderne Dame erscheint um 1475 in Spanien zum ersten Mal schriftlich","Gedruckte Bücher verbreiteten die neuen Regeln in wenigen Jahrzehnten in ganz Europa"],"more":[{"h":"Der schwache Ratgeber","p":["Der Fers konnte nur ein Feld diagonal ziehen – ganz anders als die heutige Dame, die von einem Rand zum anderen jagt. Schach war damals langsam, eine Partie konnte Stunden dauern.","Der Elefant (der heutige Läufer) sprang nur zwei Felder diagonal. Ein Bauer auf der letzten Reihe wurde umgewandelt – aber nur in diesen schwachen Fers."],"cap":["Wie weit der Fers (links) und die heutige Dame (rechts) ziehen können"]},{"h":"„Damenschach“ und „wütendes Schach“","p":["Mit der neuen Dame nannte man das Spiel in Spanien „Damenschach“ (ajedrez de la dama) und in Italien wegen seiner Wucht „scacchi alla rabbiosa“, wütendes Schach. Etwa zur gleichen Zeit durfte auch der Läufer beliebig weit diagonal ziehen.","Mit stärkeren Figuren wurde das Spiel schnell und heftig. Es erschienen Bücher über Fallen, die in wenigen Zügen gewinnen, und über feste Eröffnungsfolgen – Schach wurde zum Spiel, das man studiert."],"cap":["Liberale da Verona, Die Schachspieler (um 1475) – gemalt, gerade als die neue Dame entstand"]},{"h":"Warum eine Dame?","p":["Warum der Ratgeber zur Dame wurde, ist nicht sicher. Die Figur neben dem König als seine Gemahlin zu sehen, lag vielleicht nahe. Im Lateinischen wurde „Fers“ zu „fercia“, später hieß die Figur „regina“, Königin.","Auch warum sie stark wurde, ist umstritten: um das Spiel zu beschleunigen, oder weil es eine Zeit mächtiger Königinnen wie Isabella I. von Kastilien war. Die Historikerin Marilyn Yalom verband den Wandel mit der Stellung der Frau im Mittelalter."],"cap":["Die Dame aus den Lewis-Schachfiguren (12. Jh.) – noch mit dem alten, schwachen Zug"]}],"tl":[["um das 6. Jh.","In Indien entsteht Chaturanga, der Vorfahr des Schachs"],["7.–9. Jh.","Gespielt in Persien und der arabischen Welt, neben dem König der Fers"],["um das 10. Jh.","Schach erreicht Europa"],["12. Jh.","Unter den Lewis-Figuren gibt es Damen (noch schwach)"],["um 1475","Das valencianische Gedicht Scachs d’amor beschreibt den neuen Zug"],["1497","Lucenas Schachbuch wird in Spanien gedruckt"],["1512","Damianos Buch erscheint in Italien und verbreitet die Regeln"]]},"senet":{"title":"Wie Senet zur Reise ins Jenseits wurde","lead":"Ein Spiel, das in Ägypten fast dreitausend Jahre lang gespielt wurde, stand schließlich für die Reise der Seele nach dem Tod.","s":["Senet ist ein altägyptisches Spiel, bei dem Figuren über ein Brett mit drei Reihen zu je zehn Feldern ziehen. In Gräbern der 1. Dynastie um 3100 v. Chr. fand man Bruchstücke möglicher Senet-Bretter. Könige spielten auf prächtigen Kästen, einfache Leute auf in Stein geritzten Brettern.","Der Name bedeutet „Vorübergehen“. Seit dem Neuen Reich (ab etwa 1550 v. Chr.) wurde Senet mit der Reise der Seele des Toten durch das Jenseits verbunden.","Kapitel 17 des Totenbuchs zeigt den Verstorbenen beim Senet gegen einen unsichtbaren Gegner. An der Wand im Grab der Nefertari, der Gemahlin Ramses’ II., sitzt die Königin vor einem Senet-Brett.","Tutanchamuns Grab enthielt mindestens fünf Spielkästen. Einer davon, ein großer Kasten aus Ebenholz und Elfenbein, trägt oben das Senet und auf der anderen Seite ein anderes Spiel mit zwanzig Feldern.","Ein Text, der die Regeln vollständig erklärt, wurde jedoch nie gefunden. Im 20. Jahrhundert rekonstruierten unter anderen Jéquier, Bell und Kendall (1978) jeweils eine Spielweise aus Brettern, Bildern und Textbruchstücken. Das Senet im Atlas ist eine solche auf Forschung beruhende Spielweise."],"quiz":[["Was bedeutet der Name „Senet“?","Vorübergehen","Spiel des Königs","Dreißig Häuser","Den Fluss überqueren"],["Womit wurde Senet im Neuen Reich verbunden?","Mit der Reise der Seele durch das Jenseits","Mit Regenritualen","Mit Schlachtplänen","Mit Ernteorakeln"],["Wie viele Spielkästen enthielt Tutanchamuns Grab mindestens?","Fünf","Einen","Zwei","Hundert"]],"kf":["Eines der ältesten Brettspiele: Steine laufen über ein Brett aus 3 × 10 Feldern","Der Name bedeutet „Vorübergehen“; im Neuen Reich wurde es zur Reise der Seele durchs Jenseits","Regeln sind nicht überliefert; heutige Spielweisen sind Rekonstruktionen des 20. Jahrhunderts"],"more":[{"h":"Dreißig Felder und die besonderen","p":["Das Senet-Brett hat drei Reihen zu zehn, dreißig Felder. Die Steine liefen vermutlich in der ersten Reihe von links nach rechts, in der zweiten von rechts nach links und in der dritten wieder von links nach rechts – ein S.","Die letzten fünf Felder trugen oft besondere Zeichen. Feld 26 ist das „schöne Haus“, 27 das „Wasser“, und in den meisten Rekonstruktionen muss ein Stein, der ins Wasser fällt, zurück. Auf 28 bis 30 standen Zahlen oder Götter des Jenseits."],"cap":["Ein Senet-Brett. Die Steine laufen in einem S; die letzten fünf Felder (26–30) tragen Zeichen"]},{"h":"Ziehen mit Wurfstäben","p":["Statt Würfeln warf man vier Stäbe, flach auf einer und rund auf der anderen Seite, oder Tierknöchel. Viele Forscher meinen, man zog so viele Felder, wie flache Seiten oben lagen, und keine zählte fünf.","Genau so zählt man auch die Yut-Stäbe im fernen Korea. Wirf sie im Museumsraum „Zufall“ und sieh, wie viel öfter manche Zahlen kommen als andere."],"cap":["Ägyptische Wurfstäbe (wirf sie im Raum „Zufall“)"]},{"h":"Tutanchamuns Spielkästen","p":["Das Grab Tutanchamuns, 1922 von Howard Carter geöffnet, enthielt mindestens fünf Spielkästen. Der größte ist aus Ebenholz und Elfenbein, mit einer Schublade für Steine und Stäbe.","Kästen mit Brettern auf beiden Seiten waren damals üblich: Senet auf der einen, auf der anderen dasselbe Zwanzig-Felder-Spiel wie das Königliche Spiel von Ur. Der König sollte im Jenseits beide spielen können."],"cap":["Tutanchamuns Senet-Kasten – im Raum „Sammlung“ in 3D anzusehen und zu bespielen"]}],"tl":[["um 3100 v. Chr.","Bruchstücke eines Senet-artigen Bretts in einem Grab der 1. Dynastie"],["um 2600 v. Chr.","Grabmalereien des Alten Reichs zeigen Spieler"],["ab um 1550 v. Chr.","Neues Reich: Senet wird mit der Jenseitsreise verbunden"],["um 1323 v. Chr.","Fünf Spielkästen im Grab Tutanchamuns"],["um 1250 v. Chr.","Nefertari wird vor einem Senet-Brett gemalt"],["1922","Carter öffnet das Grab Tutanchamuns"],["1978","Kendall veröffentlicht eine Regelrekonstruktion"]]},"lewis":{"title":"Die Schachfiguren aus dem Sand","lead":"Mittelalterliche Figuren, 1831 auf einer schottischen Insel gefunden – und eine aus derselben Werkstatt, die 188 Jahre später in einer Schublade auftauchte.","s":["1831 fand man auf der Insel Lewis vor Nordwestschottland einen Schatz von Figuren, meist aus Walrosselfenbein geschnitzt: 78 Schachfiguren, 14 Spielsteine für Brettspiele und eine Schnalle, insgesamt 93 Stücke.","Wo und wie genau sie gefunden wurden, ist unklar. Meist wird die Bucht von Uig an der Westküste genannt, doch es gibt andere Vorschläge. Wer sie dort vergrub und warum, weiß niemand.","Man nimmt an, dass sie im späten 12. Jahrhundert in der Gegend von Trondheim in Norwegen entstanden: Könige, nachdenkliche Königinnen, Bischöfe, Ritter auf gedrungenen Pferdchen und Krieger, die in den Rand ihres Schildes beißen – wohl die Berserker der nordischen Sagas.","Heute liegen 82 Figuren im British Museum und 11 im National Museum of Scotland. Seit Langem heißt es, dass zu vollständigen Sätzen einige Figuren fehlen.","2019 wurde ein Krieger, den ein Antiquitätenhändler aus Edinburgh 1964 für nur 5 Pfund gekauft und den die Familie in einer Schublade aufbewahrt hatte, als Werk der Lewis-Werkstatt erkannt. Er wurde bei Sotheby’s für 735.000 Pfund versteigert."],"quiz":[["In welchem Jahr wurden die Figuren auf Lewis gefunden?","1831","1066","1931","1700"],["Woraus sind die Figuren meist geschnitzt?","Aus Walrosselfenbein","Aus Marmor","Aus Gold","Aus Glas"],["Wann wurde der 2019 versteigerte Krieger für 5 Pfund gekauft?","1964","1831","1990","2018"]],"kf":["93 Figuren und Spielsteine, 1831 auf der Isle of Lewis (Schottland) gefunden","Im späten 12. Jahrhundert in Norwegen meist aus Walrosszahn geschnitzt","Heute zwischen dem British Museum und den National Museums Scotland aufgeteilt"],"more":[{"h":"Die 78 Schachfiguren","p":["Die 78 Figuren sind 8 Könige, 8 Damen, 16 Bischöfe, 15 Ritter, 12 Wächter und 19 Bauern – Teile von mindestens vier Spielen.","Die Bischöfe tragen Mitra. Dass aus dem „Elefanten“ ein Bischof (unser Läufer) wurde, geschah in Europa, und die Lewis-Figuren gehören zu den frühesten Beispielen. Manche Wächter beißen in ihren Schild – man sieht in ihnen Berserker, Krieger im Kampfrausch."],"cap":["Die Lewis-Schachfiguren (im Raum „Sammlung“ in 3D)","Die 78 Schachfiguren nach Art"]},{"h":"Walrosszahn und die nördlichen Meere","p":["Die meisten sind aus Walrosszahn, einige aus Walzahn. Walrosselfenbein war ein Schatz der Nordmeere, aus Grönland und Nordnorwegen herangeschafft.","Lewis gehörte damals zu den Inseln des norwegischen Königs; durch den Vertrag von Perth 1266 kam es an Schottland. Nahe dem Dom von Trondheim fand man gleich geschnitzte Bruchstücke – ein Hinweis auf den Herstellungsort."],"cap":[]},{"h":"Die Legende des Funds und der Ruhm heute","p":["Es gibt viele Geschichten: eine Kuh, die sie aus dem Sand scharrte, oder ein Einheimischer, Malcolm MacLeod. Der Finder verkaufte sie bald, und über Edinburgh kaufte das British Museum die meisten.","Mit ihren mürrisch-komischen Gesichtern sind sie heute sehr beliebt, Nachbildungen werden weltweit verkauft. Das Zauberschach im Film Harry Potter und der Stein der Weisen (2001) nutzte Figuren nach dem Vorbild der Lewis-Figuren."],"cap":[]}],"tl":[["spätes 12. Jh.","Die Figuren entstehen in Norwegen (um Trondheim)"],["1266","Der Vertrag von Perth gibt die Inseln samt Lewis an Schottland"],["1831","Die 93 Stücke werden zusammen auf Lewis gefunden"],["1831–32","Das British Museum kauft 82"],["1888","Das schottische Nationalmuseum erwirbt 11"],["2001","Sie erscheinen im Zauberschach von Harry Potter"],["2019","Ein für 5 £ gekaufter Wächter bringt 735.000 £"]]},"tafl":{"title":"Die Flucht des Königs und eine falsche Übersetzung","lead":"Die Regeln des Brettspiels der Wikinger wurden aus einem Reisetagebuch aus Lappland aus dem 18. Jahrhundert erschlossen.","s":["Im Nordeuropa der Wikingerzeit spielte man Brettspiele namens Tafl. Ein König in der Mitte und seine wenigen Verteidiger kämpfen gegen ein größeres Heer, das sie umzingelt – ein Spiel zweier ungleicher Seiten.","Ein Holzbrett aus dem 10. Jahrhundert, 1932 in Ballinderry (Irland) gefunden, hat 7×7 Löcher; die Mitte und die vier Ecken sind markiert – wohl der Platz des Königs und seine Zufluchtsorte.","Doch kaum eine mittelalterliche Beschreibung der Regeln ist erhalten. Ein wichtiger Hinweis ist das Tagebuch des 25-jährigen Naturforschers Linné von seiner Reise durch Lappland (Nordschweden) 1732. Dort notierte er, wie die Samen ein Spiel namens Tablut spielten.","Das Tagebuch erschien 1811 in englischer Übersetzung, doch die Übersetzung enthielt Fehler. Murrays darauf beruhende Rekonstruktion (1913) wurde für viele Jahre zur Standardregel des Tafl.","Spieler und Forscher korrigierten den Fehler später, und heute werden viele Regelversionen gespielt. Das Tafl im Atlas ist eine davon."],"quiz":[["Welches Spiel notierte Linné in Lappland?","Tablut","Senet","Mancala","Schach"],["Welche Figur wollen die Verteidiger in eine Ecke bringen?","Den König","Die Königin","Eine Fahne","Ein Schiff"],["Wann erschien die fehlerhafte englische Übersetzung?","1811","1732","1932","1066"]],"kf":["Ein König und wenige Verteidiger in der Mitte, umringt von einem größeren Heer – ein Spiel zweier ungleicher Parteien","Gespielt im Nordeuropa der Wikingerzeit, auf Brettern von 7×7 bis 19×19","Die Regeln kennen wir aus Linnés Reisetagebuch von 1732 – und seiner fehlerhaften englischen Übersetzung"],"more":[{"h":"Das Brett von Ballinderry","p":["Das Brett von Ballinderry stammt aus einer Seesiedlung (Crannog) in Mittelirland und ist aus Eibenholz. In seinen 49 Löchern im 7×7-Raster steckten wohl Steine mit einem Zapfen am Boden.","Am Rahmen sitzt ein Griff in Form eines Menschenkopfes – ein Brett zum Mitnehmen. Irische Quellen nennen ein 7×7-Tafl namens Brandubh („schwarzer Rabe“), das darauf gespielt worden sein könnte."],"cap":["Das Brett von Ballinderry (7×7) mit der Anfangsstellung des irischen Brandubh. Die goldenen Ringe markieren Mitte und Ecken"]},{"h":"Linnés Tablut","p":["Linnés Tablut wird auf 9×9 Feldern gespielt. Der König steht auf dem Thron in der Mitte; seine 8 „Schweden“ kämpfen gegen 16 „Moskowiter“.","Alle Steine ziehen wie ein Turm beliebig weit geradeaus und werden geschlagen, wenn zwei Gegner sie einklemmen. Die Verteidiger gewinnen, wenn der König den Rand erreicht; die Angreifer, wenn sie ihn von allen vier Seiten einschließen. Linné schrieb in einer Mischung aus Latein und Schwedisch, und in der englischen Übersetzung verschoben sich mehrere Punkte."],"cap":["Tablut, wie Linné es aufschrieb (9×9): der König auf dem Thron in der Mitte, 8 Verteidiger, 16 Angreifer. Erreicht der König ein grünes Randfeld, gewinnen die Verteidiger"]},{"h":"Wachsende Bretter, ein verschwindendes Spiel","p":["Neben 7×7 gab es Bretter mit 9×9, das walisische 11×11 und sogar 19×19. Das größte, Alea Evangelii, ist in einer Handschrift des 12. Jahrhunderts gezeichnet, die es auf den Hof des englischen Königs Æthelstan im 10. Jahrhundert zurückführt.","Als sich das Schach im 12. und 13. Jahrhundert in Nordeuropa verbreitete, geriet Tafl allmählich in Vergessenheit. Nur im fernen Lappland überlebte Tablut – und Linné schrieb es zufällig auf. Heute gibt es internationale Turniere auf 11×11-Brettern, und das Spiel gewinnt neue Anhänger."],"cap":["Der Fund von Lewis (12. Jahrhundert): neben den Schachfiguren lagen 14 Spielsteine für ein Brettspiel"]}],"tl":[["10. Jh.","In Irland entsteht das Brett von Ballinderry"],["924–939","Am Hof Æthelstans soll Alea Evangelii gespielt worden sein"],["12. Jh.","Alea Evangelii wird in einer Handschrift gezeichnet"],["12.–13. Jh.","Schach verbreitet sich in Nordeuropa, Tafl verschwindet"],["1732","Linné schreibt in Lappland Tablut auf"],["1811","Lachesis Lapponica, die englische Übersetzung seines Tagebuchs, erscheint"],["1913","Murray rekonstruiert Tafl in A History of Chess"],["1932","Das Brett von Ballinderry wird gefunden"]]},"goose":{"title":"Das Gänsespiel, ein Geschenk für einen König","lead":"Ein Würfelwettlauf über eine Spirale aus 63 Feldern wurde einem König geschenkt – und dann in ganz Europa gespielt.","s":["Das Gänsespiel ist ein Wettlaufspiel: Man würfelt und zieht über eine Spirale aus 63 Feldern zum Ziel in der Mitte. Wer auf einer Gans landet, zieht um dieselbe Zahl noch einmal weiter. Brunnen, Gefängnis und Tod halten einen auf oder schicken einen zurück zum Start.","Es entstand wohl im Italien des 16. Jahrhunderts. Francesco I. de’ Medici, Großherzog der Toskana, soll das Spiel zwischen 1574 und 1587 König Philipp II. von Spanien geschenkt haben.","In England ließ der Londoner Drucker John Wolfe 1597 „das neue und überaus vergnügliche Gänsespiel“ eintragen. Im 17. und 18. Jahrhundert war es in ganz Europa ungeheuer beliebt.","Auf Papier gedruckt verbreitete es sich in unzähligen Fassungen mit neuen Bildern: Bretter zum Erdkundelernen, Bretter mit Geschichten und Fabeln, sogar Werbebretter. Es gilt als Vorbild vieler späterer Wettlaufspiele.","Ein doppelseitiges Brett im Metropolitan Museum of Art zeigt auf der einen Seite das Gänsespiel, auf der anderen Schach. Wohl im späten 16. Jahrhundert von Handwerkern in Gujarat (Indien) gefertigt, könnte es das älteste erhaltene Gänsespielbrett sein."],"quiz":[["Wie viele Felder hat das Gänsespiel?","63","64","100","30"],["Wer soll das Spiel dem König von Spanien geschenkt haben?","Francesco I. de’ Medici","Napoleon","Elisabeth I.","Ludwig XIV."],["Was passiert, wenn man auf einer Gans landet?","Man zieht um dieselbe Zahl weiter","Man muss zurück zum Start","Man setzt eine Runde aus","Man tauscht den Platz mit einem Gegner"]],"kf":["Ein Wettlauf über eine Spirale aus 63 Feldern zum Ziel in der Mitte, nach dem Wurf der Würfel","Im Italien des 16. Jahrhunderts entstanden und, so heißt es, von den Medici dem König von Spanien geschenkt","Als gedruckte Bögen verbreitet, in unzähligen Fassungen mit neuen Bildern und Themen"],"more":[{"h":"Eine Spirale aus 63 Feldern","p":["In der bekanntesten Fassung gibt es neben den Gänsen einige besondere Felder. Die Brücke auf 6 bringt einen auf 12; im Wirtshaus auf 19 setzt man eine Runde aus; im Brunnen auf 31 und im Gefängnis auf 52 sitzt man fest, bis ein anderer Spieler kommt und einen befreit.","Das Labyrinth auf 42 schickt zurück auf 30, der Tod auf 58 zurück zum Start. Auf 63 muss man genau landen – überzählige Augen geht man zurück. Der letzte Schritt ist der schwerste."],"cap":["Die 63 Felder als Spirale von außen nach innen. Grün: Gänse; blau: die Brücke; gelb: Aufenthalte (Wirtshaus, Brunnen, Gefängnis); rot: Rückschläge (Labyrinth, Tod); gold: das Ziel"]},{"h":"Das Rätsel der Neun","p":["Die Gänse stehen auf 5, 9, 14, 18 … in abwechselnden Abständen von 4 und 5. Jedes Vielfache von 9 hat eine Gans – eine 9, die auf der 9 landet, trüge einen weiter auf 18, 27 … und geradewegs auf 63.","Darum gibt es bei Fassungen mit zwei Würfeln eine Sonderregel: Ein erster Wurf von 6 und 3 führt auf 26, einer von 5 und 4 auf 53. Die 63 ist 7×9 und wurde mit dem 63. Lebensjahr in Verbindung gebracht, das damals als das gefährlichste galt."],"cap":["Die Gänse stehen abwechselnd alle 4 und 5 Felder, darum steht auf jedem Vielfachen von 9 eine Gans. Eine 9 im ersten Wurf hüpfte von Gans zu Gans bis 63"]},{"h":"Verbreitet durch den Druck","p":["Die Spielpläne wurden von Kupferplatten und Holzstöcken gedruckt und wurden billig. In Frankreich hieß es jeu de l’oie, in Spanien juego de la oca, wo ein Reim vom Hüpfen „von Gans zu Gans“ bis heute eine Redensart ist.","Immer neue Fassungen mit neuen Bildern erschienen: Pläne zum Lernen von Erdkunde und Geschichte, über die Französische Revolution oder Napoleon, sogar Werbung für Waren. Auf derselben Bahn aus 63 Feldern zeichnete jede Zeit ihre eigenen Themen."],"cap":[]}],"tl":[["16. Jh.","Entsteht vermutlich in Italien"],["1574–87","Francesco I. de’ Medici soll es Philipp II. von Spanien geschenkt haben"],["spätes 16. Jh.","In Gujarat (Indien) entsteht ein doppelseitiges Brett: Gänsespiel auf der einen, Schach auf der anderen Seite"],["1597","John Wolfe lässt es in London zum Druck eintragen"],["17.–18. Jh.","Eine Mode in ganz Europa, mit immer mehr Themenfassungen"],["1790er","Pläne über die Französische Revolution entstehen"],["19. Jh.","In vielen Ländern massenhaft als Kinderspiel gedruckt"]]},"shogi":{"title":"Wann entstanden die „Handfiguren“ des Shogi?","lead":"In der ganzen Schachfamilie darf man nur im Shogi geschlagene Figuren als eigene wieder einsetzen. Wann – und warum – kam diese Regel auf?","s":["Der indische Vorfahr des Schachs verbreitete sich nach Osten und Westen; in Japan wurde daraus Shogi. Die ältesten Shogi-Figuren Japans sind 16 Stück, die Anfang der 1990er-Jahre auf dem alten Gelände des Kōfuku-ji in Nara ausgegraben wurden. Mit ihnen fand man ein Etikett mit dem Datum 1058 (Tenki 6); die Figuren gelten daher als etwa gleich alt.","Auch Schriften jener Zeit erwähnen Shogi. Das Shin Sarugaku-ki aus der Mitte des 11. Jahrhunderts nennt es, und das Nichūreki, das Aufzeichnungen vom Ende der Heian-Zeit sammelt, beschreibt ein „Heian-Shogi“ mit Königen, Gold- und Silbergenerälen, Springern, Lanzen und Bauern.","In der Kamakura- und Muromachi-Zeit entstanden viele größere Formen mit mehr Figuren. Das „kleine Shogi“, Vorläufer des heutigen Spiels, fügte Turm und Läufer hinzu – und eine Figur, die es nicht mehr gibt: den betrunkenen Elefanten.","Die Regel zum Wiedereinsetzen kam vermutlich im 16. Jahrhundert auf. Der Überlieferung nach ließ Kaiser Go-Nara den betrunkenen Elefanten aus dem kleinen Shogi entfernen; etwa zur selben Zeit sollen die Handfiguren begonnen haben.","Warum, ist unklar. Eine Erklärung: Die Figuren beider Seiten haben dieselbe Farbe und unterscheiden sich nur durch ihre Richtung, sodass eine geschlagene Figur leicht wiederzuverwenden ist. Dadurch leert sich das Brett nicht, und Remis sind selten."],"quiz":[["Welches Datum stand auf dem Etikett bei den Kōfuku-ji-Figuren?","1058 (Tenki 6)","701 (Taihō 1)","1582 (Tenshō 10)","1868 (Meiji 1)"],["Wann kam die Regel der Handfiguren vermutlich auf?","Etwa im 16. Jahrhundert","Etwa im 8. Jahrhundert","Etwa im 19. Jahrhundert","Im 20. Jahrhundert"],["Welcher Grund wird dafür genannt, dass sich Figuren leicht wiederverwenden ließen?","Beide Seiten haben gleichfarbige Figuren, unterschieden durch die Richtung","Die Figuren waren aus Gold","Das Brett hatte wenige Felder","Figuren wurden ausgewürfelt"]],"kf":["Ein in Indien geborener Verwandter des Schachs, der in Japan heranwuchs – gespielt auf 9×9 Feldern","Die ältesten Steine stammen vom alten Gelände des Kōfuku-ji, gefunden mit einem Holztäfelchen von 1058","Die „Steine in der Hand“ – geschlagene Steine als eigene einsetzen – entstanden wohl um das 16. Jahrhundert"],"more":[{"h":"Eine Farbe, die Richtung entscheidet","p":["Schachfiguren sind weiß und schwarz bemalt, Shogi-Steine dagegen haben alle die Farbe des Holzes: Wem ein Stein gehört, zeigt die Richtung der Spitze des fünfeckigen Steins. Genau diese Form erlaubt es, einen geschlagenen Stein einfach umzudrehen und wieder einzusetzen.","Auf jedem Stein steht sein Name, und im gegnerischen Lager kann er umgedreht und „befördert“ werden. Der Bauer wird zum と auf seiner Rückseite und zieht wie ein Goldgeneral. Flache, beschriftete Steine statt geschnitzter Figuren – das teilt Shogi mit seinen ostasiatischen Verwandten, dem chinesischen Xiangqi und dem koreanischen Janggi."],"cap":["Shogi-Steine haben für beide Seiten dieselbe Farbe; man unterscheidet sie an der Richtung der Spitze. Rechts: ein umgedrehter, „beförderter“ Bauer (Tokin)"]},{"h":"Die Zeit der Riesen-Shogi","p":["Von der Kamakura- und Muromachi-Zeit bis in die Edo-Zeit entstanden immer größere Shogi-Formen mit immer mehr Steinarten. Das 12×12-Chū-Shogi wurde die ganze Edo-Zeit hindurch viel gespielt und hat bis heute Liebhaber.","Die Quellen gehen noch weiter: Dai-Shogi auf 15×15, Tai-Shogi auf 25×25 und Taikyoku-Shogi mit 804 Steinen auf 36×36 Feldern. Das Alltagsspiel aber war das Shō-Shogi auf 9×9 – es bekam die Steine in der Hand und wurde zum heutigen Shogi."],"cap":["Brettgrößen im Vergleich, von einer Ecke aus gezeichnet: 9×9 ist das heutige Shogi (40 Steine), 12×12 Chū-Shogi (92), 15×15 Dai-Shogi (130), 25×25 Tai-Shogi (354), 36×36 Taikyoku-Shogi (804)"]},{"h":"Shogi in Edo","p":["In der Edo-Zeit entstanden vom Shogunat besoldete Shogi-Häuser; Ōhashi Sōkei gilt als erster Meister. Jedes Jahr spielten die Besten vor dem Shōgun die „Burgpartien“, die später auf den 17. November gelegt wurden – daher der heutige Shogi-Tag.","Shogi war auch ein Vergnügen der Stadtleute: Harunobus Holzschnitt zeigt ein junges Paar beim Spiel neben einem Moskitonetz. Zudem erschienen Sammlungen von Tsume-Shogi-Aufgaben, die wie Kunstwerke wirken, etwa Itō Kanjus Shōgi Zukō (1755)."],"cap":["Farbholzschnitt von Suzuki Harunobu (um 1767–69): eine junge Frau und ein junger Mann spielen Shogi neben einem Moskitonetz"]}],"tl":[["1058","Steine vom alten Gelände des Kōfuku-ji (gefunden mit einem Täfelchen aus dem Jahr Tengi 6)"],["Mitte 11. Jh.","Das Shinsarugakuki nennt Shogi"],["frühe Kamakura-Zeit","Das Nichūreki zählt die Steine des Heian-Shogi auf"],["um 16. Jh.","Die Steine in der Hand kommen vermutlich auf"],["1612","Ōhashi Sōkei und andere sollen Bezüge vom Shogunat erhalten"],["1716","Die Burgpartien werden auf den 17. November gelegt"],["1755","Itō Kanjus Shōgi Zukō"],["1975","Der 17. November wird zum Shogi-Tag"]]},"pachisi":{"title":"Wie Pachisi zu Ludo wurde","lead":"Ein kreuzförmiges Brettspiel indischer Höfe wechselte den Namen und erreichte Kinderzimmer in aller Welt.","s":["In Indien gibt es Chaupar und Pachisi: Vier Spieler ziehen Figuren um ein kreuzförmiges Brett. Beim Chaupar wirft man lange Würfel (Pasa), beim Pachisi Kaurimuscheln. Der Name Pachisi bedeutet „fünfundzwanzig“ – der höchste Wurf der Muscheln.","Sogar die Götter spielten. Ein Gemälde vom Ende des 17. Jahrhunderts zeigt den Gott Shiva und seine Frau Parvati an einem Chaupar-Brett auf einem Tigerfell.","In Fatehpur Sikri, der Stadt des Mogulkaisers Akbar (16. Jahrhundert), zeigt ein Hof noch heute ein riesiges kreuzförmiges Brett im Boden. Akbar soll mit farbig gekleideten Menschen als Figuren gespielt haben.","Im 19. Jahrhundert reiste das Spiel über die Meere. In Amerika wurde es als Parcheesi verkauft und 1874 als Marke eingetragen. In Großbritannien kam es in den 1890er-Jahren als Ludo – lateinisch „ich spiele“ – auf den Markt und wurde zum Familienklassiker.","Ludo ist einfacher: ein Würfel, und mit einer 6 kommt eine Figur heraus. Verwandte unter anderen Namen gibt es weltweit, etwa Parchís in Spanien oder Mensch ärgere Dich nicht in Deutschland."],"quiz":[["Was bedeutet der Name „Pachisi“?","Fünfundzwanzig","Weg des Königs","Kreuz","Kaurimuschel"],["Welche Stadt Akbars hat noch einen Hof mit riesigem Spielbrett?","Fatehpur Sikri","Der Qutb Minar in Delhi","Das Taj Mahal","Ellora"],["Was bedeutet „ludo“ auf Lateinisch?","Ich spiele","Ich gewinne","Ich laufe","Ich werfe"]],"kf":["Ein Wettlaufspiel auf einem kreuzförmigen indischen Brett: vier Spieler in zwei Teams bringen ihre Figuren einmal herum","Der Name bedeutet „25“ – der höchste Wurf der Kaurischnecken","Im 19. Jahrhundert reiste es übers Meer und verbreitete sich als Parcheesi, Ludo und mehr weltweit"],"more":[{"h":"Das Kreuz und der Weg","p":["Das Pachisi-Brett ist ein Kreuz, dessen vier Arme vom mittleren Charkoni ausgehen. Jeder Arm hat 3 × 8 Felder, zusammen 96. Oft war das Brett auf Stoff gestickt, sodass man es zusammenrollen und wegräumen konnte.","Die Figuren verlassen die Mitte, ziehen die mittlere Spalte ihres eigenen Arms hinab, umrunden das Brett einmal gegen den Uhrzeigersinn und kehren über die mittlere Spalte ins Zentrum zurück. Gegenübersitzende sind Partner; ein Team gewinnt, wenn beide alle vier Figuren heimgebracht haben."],"cap":["Ein kreuzförmiges Brett (jeder Arm 3 × 8 Felder). Die blaue Linie ist der Weg eines Spielers: in der Mitte des eigenen Arms hinunter, einmal gegen den Uhrzeigersinn herum und über die Mitte zurück ins Zentrum"]},{"h":"Kauris zählen","p":["Beim Pachisi wirft man sechs Kaurischnecken; wie viele mit der Öffnung nach oben liegen, bestimmt den Zug. Bei zwei bis sechs zieht man so viele Felder; bei einer aber 10, und bei keiner 25.","Mit einer Chance von 1 zu 64 ist die 25 der seltenste und höchste Wurf – und gab dem Spiel seinen Namen. Eine 6, 10 oder 25 bringt einen weiteren Wurf. Chaupar dagegen spielt man mit drei langen Stabwürfeln mit den Augen 1, 2, 5 und 6."],"cap":["Von sechs Kauris: wie viele mit der Öffnung nach oben fallen (obere Reihe) und wie weit man dann zieht (untere Reihe). Die Balkenhöhe zeigt die Häufigkeit, wenn jede Schnecke gleich oft auf jede Seite fällt"]},{"h":"Neue Namen, neue Länder","p":["Über die Briten in Indien gelangte das Spiel im 19. Jahrhundert nach Europa und Amerika. In den USA wurde es zur Marke Parcheesi; in Großbritannien wurde Ludo 1896 patentiert, mit einfacheren Regeln und einem einzigen Würfel statt der Kauris.","Deutschland bekam 1914 „Mensch ärgere dich nicht“, in Spanien spielt man Parchís. Namen und Einzelheiten wechseln von Land zu Land, doch das Gerüst bleibt: einmal ums Kreuz und wieder nach Hause."],"cap":[]}],"tl":[["16. Jh.","In Akbars Fatehpur Sikri entsteht ein Hof mit einem riesigen Kreuzbrett"],["17.–18. Jh.","Indische Miniaturen zeigen oft Menschen beim Chaupar"],["1694–95","Devidasa malt Shiva und Parvati beim Chaupar"],["1874","Parcheesi wird in den USA zur Marke"],["1896","Ludo wird in Großbritannien patentiert"],["1914","„Mensch ärgere dich nicht“ kommt in Deutschland auf den Markt"]]},"go":{"title":"Was ein 1300 Jahre altes Go-Brett erzählt","lead":"Das Go-Brett im Shōsōin hat 19 Linien wie heute – und 17 Blumenzeichen, anders als heute.","s":["Go entstand im alten China. Der Legende nach erfand der weise König Yao es, um seinen Sohn zu unterrichten. Das Buch Mengzi aus vorchristlicher Zeit nennt einen Meisterspieler, Yi Qiu.","Die Größe des Bretts hat sich vermutlich gewandelt: In früher Zeit wurden auch Bretter mit 17 Linien benutzt, später setzte sich das heutige 19er-Brett durch.","Wann Go nach Japan kam, ist unklar, doch in der Nara-Zeit wurde es schon gespielt. Die Regeln für Mönche und Nonnen verboten Musik und Glücksspiel, erlaubten aber Go und Koto – ganz anders als beim Sugoroku.","Das Go-Brett mit Intarsien im Shōsōin wurde als Schatz Kaiser Shōmus überliefert. Es hat 19 Linien wie heute, aber 17 Blumenzeichen, wo das heutige Brett 9 Sternpunkte hat. Seine zwei Schubladen sind gekoppelt: Zieht man eine heraus, kommt auch die andere. Im Shōsōin liegen außerdem Go-Steine aus rot und dunkelblau gefärbtem Elfenbein mit eingravierten Vögeln.","In der Heian-Zeit zeigt die Geschichte vom Prinzen Genji Go-Partien. In der Edo-Zeit dienten Häuser wie die Hon’inbō dem Shogunat, und Go wurde zu einer Kunst, in der Berufsspieler ihr Können maßen."],"quiz":[["Wie viele Linien hat das Go-Brett im Shōsōin?","19","17","13","9"],["Was erlaubten die Regeln Mönchen und Nonnen?","Go und Koto","Sugoroku","Glücksspiele","Kemari"],["Wie viele Blumenzeichen hat das Shōsōin-Brett statt Sternpunkten?","17","9","4","25"]],"kf":["Schwarze und weiße Steine auf den Kreuzungspunkten der Linien, um das größere Gebiet einzuschließen – ein Spiel aus dem alten China","Auf Bretter mit 17 Linien folgten 19; im Shōsōin liegt ein 19-Linien-Brett aus dem 8. Jahrhundert","Im Edo-Japan dienten Go-Häuser dem Shogunat; im 21. Jahrhundert schlug eine KI den besten Spieler der Welt"],"more":[{"h":"Umzingeln, schlagen, Gebiet gewinnen","p":["Beim Go setzen Schwarz und Weiß abwechselnd Steine auf die Kreuzungspunkte der Linien. Ein gesetzter Stein bewegt sich nicht mehr. Sind alle freien Nachbarpunkte eines Steins (oder einer Gruppe) vom Gegner besetzt, wird er geschlagen und vom Brett genommen.","Am Ende entscheiden eingeschlossenes Gebiet und geschlagene Steine. Die Regeln sind wenige, das Brett aber ist weit: Für ein 19-Linien-Brett wurde die Zahl möglicher Stellungen auf etwa 10 hoch 170 berechnet."],"cap":["So wird geschlagen. Links: Der schwarze Stein hat vier freie Punkte neben sich (rot). Mitte: Weiß schließt ihn von drei Seiten ein, einer bleibt. Rechts: Auch der letzte wird besetzt – der schwarze Stein ist geschlagen"]},{"h":"Von 17 Linien zu 19","p":["In einem Grab der Östlichen Han-Dynastie in Wangdu (Hebei, China) fand man ein steinernes Go-Brett mit 17 Linien. Der Go-Klassiker von Dunhuang, um das 6. Jahrhundert datiert, beschreibt 361 Punkte – ein 19-Linien-Brett. Dazwischen ist das Brett offenbar gewachsen.","Das Brett im Shōsōin hat 19 Linien, trägt aber statt der heutigen neun Sternpunkte an 17 Stellen Blütenzeichen. Allein der Schritt von 289 auf 361 Punkte machte das Spiel viel tiefer."],"cap":["Bretter mit 17 und 19 Linien im Vergleich der Schnittpunkte. Die neun schwarzen Punkte des heutigen Bretts sind die „Sternpunkte“"]},{"h":"Go der Unsterblichen, Go der Meister","p":["Eine chinesische Erzählung handelt von einem Holzfäller, der im Gebirge Unsterblichen beim Go zusah – und merkte, dass so viele Jahre vergangen waren, dass sein Axtstiel verrottet war. Go als Zeitvertreib der Unsterblichen war ein beliebtes Motiv auf Schalen und Bildern.","Im Edo-Japan erhielten Go-Häuser wie die Hon’inbō Bezüge vom Shogunat, und Go wurde zur Kunst verfeinert. Hon’inbō Shūsais Abschiedspartie von 1938 wurde zu Kawabata Yasunaris Roman „Meijin“. 2016 besiegte die KI AlphaGo den weltbesten Spieler Lee Sedol mit vier zu eins und verblüffte die Welt."],"cap":["Schnitzlackschale mit Go spielenden Unsterblichen (Ming-Dynastie, Xuande-Zeit, 1425–36)"]}],"tl":[["um 4. Jh. v. Chr.","Menzius nennt den Go-Meister Yi Qiu"],["Östliche Han","Ein steinernes 17-Linien-Brett kommt in ein Grab in Wangdu"],["um 6. Jh.","Der Go-Klassiker von Dunhuang beschreibt 19 Linien und 361 Punkte"],["8. Jh.","Das Sandelholz-Go-Brett mit Intarsien im Shōsōin"],["1612","Hon’inbō Sansa und andere sollen Bezüge vom Shogunat erhalten"],["1938","Hon’inbō Shūsais Abschiedspartie, später Kawabatas „Meijin“"],["2016","AlphaGo schlägt Lee Sedol mit vier zu eins"]]},"draughts":{"title":"Wie das Damespiel entstand","lead":"Ein arabisches Brettspiel, das Schachbrett und die Schachdame: Aus der Begegnung der drei entstand vermutlich das Damespiel.","s":["Als Vorfahr des Damespiels gilt Alquerque, gespielt auf einem Gitter aus 5×5 durch Linien verbundenen Punkten. Auf Arabisch hieß es Qirq und wird im Buch der Lieder des 10. Jahrhunderts genannt. Die Mauren brachten es nach Spanien; seine Regeln stehen im Buch der Spiele, das König Alfons X. von Kastilien im 13. Jahrhundert anfertigen ließ.","Um das 12. Jahrhundert, wohl in Südfrankreich, begann man, die Alquerque-Steine auf einem Schachbrett zu ziehen. So entstand Fierges. Die Steine trugen den Namen der damaligen Schachdame, des Fers.","Die Umwandlung — ein Stein, der die gegnerische Grundreihe erreicht, wird stärker — ist schon in einer Chronik aus der Mitte des 13. Jahrhunderts erwähnt. Vielleicht wurde sie vom Schachbauern übernommen, der zur Dame wird.","Die große Wende kam um 1535 in Frankreich: Der Schlagzwang kam hinzu — wer schlagen kann, muss schlagen —, und das Spiel hieß „jeu forcé“, „erzwungenes Spiel“. Das englische Draughts und das amerikanische Checkers stammen davon ab.","Das alte Spiel ohne Schlagzwang lebte als „sanftes Damenspiel“ weiter und führte später zum internationalen Spiel auf 10×10. Aus einem Vorfahren gingen viele „Damespiele“ hervor."],"quiz":[["Welches Spiel gilt als Vorfahr des Damespiels?","Alquerque","Senet","Liubo","Mancala"],["Wann und wo kam der Schlagzwang hinzu?","Um 1535 in Frankreich","Im 10. Jahrhundert in Bagdad","1900 in Amerika","Im 8. Jahrhundert in Japan"],["Wonach wurden die Steine des Fierges benannt?","Nach der Schachdame (Fers)","Nach dem Schachkönig","Nach den Würfeln","Nach dem Springer"]],"kf":["Entstanden, als die Steine des arabischen Alquerque auf ein Schachbrett wanderten","Die Steine ziehen schräg und schlagen durch Überspringen; in der letzten Reihe werden sie zur Dame","Um 1535 kam der Schlagzwang hinzu, 2007 wurde das Spiel (8 × 8) gelöst"],"more":[{"h":"Von Punkten und Linien zum Schachbrett","p":["Ein Alquerque-Brett besteht aus 25 Punkten im 5 × 5-Raster, durch Linien verbunden. Jede Seite stellt 12 Steine auf, und das Spiel beginnt vom einzigen freien Punkt in der Mitte aus. Die Steine ziehen entlang der Linien und schlagen durch Überspringen eines benachbarten Gegners.","Als die Steine aufs Schachbrett wanderten, nutzte man nur noch die Felder einer Farbe. Ein 8 × 8-Brett hat 32 dunkle Felder; füllt man auf jeder Seite die ersten drei Reihen, hat jeder 12 Steine – genau wie beim Alquerque."],"cap":["Das Alquerque-Brett mit Anfangsstellung: 5 × 5 Punkte, verbunden durch gerade und schräge Linien, je 12 Steine, nur die Mitte frei"]},{"h":"Springen, schlagen, Dame werden","p":["Die Steine ziehen ein Feld schräg vorwärts und schlagen, indem sie einen benachbarten Gegner überspringen, wenn das Feld dahinter frei ist. Ist danach ein weiterer Schlag möglich, springen sie weiter. Im heutigen Spiel gilt: Wer schlagen kann, muss schlagen.","Ein Stein, der die letzte Reihe erreicht, wird zur Dame – ein zweiter Stein kommt obendrauf – und darf dann auch rückwärts ziehen. Im internationalen Spiel auf 10 × 10 Feldern zieht die Dame beliebig weit schräg, was das Endspiel völlig verändert."],"cap":["Schlagen und Damewerden. Der rote Stein überspringt zwei weiße hintereinander (×), erreicht später die letzte Reihe und wird zur Dame – zwei Steine übereinander"]},{"h":"Ein gelöstes Spiel und eine wachsende Familie","p":["In Kanada entwickelten Jonathan Schaeffer und sein Team das Programm Chinook. 1992 spielte es gegen Marion Tinsley, der in über 40 Jahren kaum eine Partie verloren hatte – und Tinsley gewann. Das Team rechnete weiter und bewies 2007, dass das Spiel (8 × 8) bei perfektem Spiel beider Seiten remis endet.","Unterdessen lebt die Familie desselben Vorfahren überall weiter: internationale Dame auf 10 × 10, russische Schaschki, türkische Dama mit geraden Zügen, kanadische Dame auf 12 × 12 – mit Turnieren in jedem Land."],"cap":[]}],"tl":[["10. Jh.","Das Buch der Lieder nennt Qirq (Alquerque)"],["um 12. Jh.","Fierges entsteht, wohl in Südfrankreich"],["1283","Alfons’ X. Buch der Spiele beschreibt Alquerque"],["um 1535","In Frankreich kommt der Schlagzwang hinzu"],["1547","Torquemada veröffentlicht in Spanien das erste Buch über Dame"],["18. Jh.","Das 10 × 10-Brett verbreitet sich in Frankreich und den Niederlanden"],["1992","Tinsley besiegt das Programm Chinook"],["2007","Beweis: Das Spiel (8 × 8) ist bei perfektem Spiel remis"]]},"reversi":{"title":"Reversi und Othello: Wer hat sie erfunden?","lead":"Ein Spiel, bei dem man schwarze und weiße Steine einschließt und umdreht — und zwei Männer im England des 19. Jahrhunderts, die darüber stritten.","s":["Im London der 1880er-Jahre behaupteten zwei Engländer, Lewis Waterman und John W. Mollett, jeweils, der Erfinder des Spiels zu sein, und nannten den anderen einen Schwindler.","Molletts Spiel „Annexation“ wurde auf einem kreuzförmigen Brett gespielt. Watermans „Reversi“ nutzte ein gewöhnliches 8×8-Brett, und seine Form ist es, die überlebt hat. Der Streit um den Namen ging sogar vor Gericht.","Reversi verbreitete sich in Europa; 1893 brachte die deutsche Firma Ravensburger es als eines ihrer ersten Produkte heraus. In Japan wurde es in Büchern der Meiji-Zeit beschrieben und auch Genpei-go genannt.","Die Beliebtheit hielt nicht an. 1971 brachte Goro Hasegawa „Othello“ heraus, mit fester Eröffnung — die ersten vier Steine überkreuz in der Mitte —, und es wurde in Japan zum Renner.","Der Name soll aus Shakespeares Drama stammen: der schwarze Feldherr Othello und seine weiße Frau Desdemona spiegeln die schwarzen und weißen Steine. Die heutigen Turnierregeln sind die von Othello."],"quiz":[["Wann und wo lebten die beiden Männer, die um Reversi stritten?","England, 19. Jahrhundert","Frankreich, 18. Jahrhundert","Japan, 20. Jahrhundert","Italien, 16. Jahrhundert"],["Welche Form hatte das Brett von Molletts Annexation?","Ein Kreuz","Ein Kreis","Ein Dreieck","Ein 8×8-Quadrat"],["Wer brachte Othello 1971 heraus?","Goro Hasegawa","Hon’inbō Shūsaku","Lewis Waterman","Ravensburger"]],"kf":["Gegnerische Steine zwischen eigenen einschließen und umdrehen; am Ende gewinnt, wer mehr hat","Im London der 1880er stritten zwei Engländer darum, wer es erfunden hatte","In den 1970ern wurde es in Japan als Othello zum Renner; 2023 zeigte sich: bei perfektem Spiel remis"],"more":[{"h":"Einschließen und umdrehen","p":["Man darf einen Stein nur dort setzen, wo er eine Reihe gegnerischer Steine zwischen sich und einem eigenen einschließt. Die Reihen laufen in acht Richtungen – waagerecht, senkrecht und schräg –, und ein Zug kann mehrere zugleich einschließen. Alle eingeschlossenen Steine werden auf die eigene Farbe gedreht.","Wer nicht ziehen kann, setzt aus; das Spiel endet, wenn keiner mehr ziehen kann. Ecksteine können nie eingeschlossen werden, deshalb ist eine Ecke ein großer Vorteil. Starke Spieler achten weniger auf die momentane Steinzahl als darauf, die Zugmöglichkeiten des Gegners zu verringern."],"cap":["So wird umgedreht. Ein schwarzer Stein auf dem rot umringten Feld schließt Weiß in drei Richtungen ein – waagerecht, senkrecht und schräg –, und alle sieben golden umrandeten Steine werden schwarz"]},{"h":"Die ersten vier Steine","p":["Beim frühen Reversi setzten die beiden Spieler die ersten vier Steine abwechselnd auf die vier Mittelfelder, sodass die Eröffnung nebeneinander oder gekreuzt ausfallen konnte.","Othello legte den gekreuzten Start fest. Von Anfang an lassen sich beide Farben leicht einschließen, und der Kampf beginnt sofort. Weltmeisterschaften beginnen heute aus dieser Stellung."],"cap":["Die ersten vier Steine. Links: ein möglicher Beginn des frühen Reversi, gleiche Farben nebeneinander. Rechts: der von Othello festgelegte gekreuzte Start"]},{"h":"Mensch und Computer","p":["Othello verbreitete sich von Japan aus in die Welt; die erste Othello-Weltmeisterschaft fand 1977 in Tokio statt. Die Regeln sind einfach, also entscheidet die Rechentiefe: Spitzenspieler sehen Dutzende Züge voraus.","1997 spielte das Programm Logistello sechs Partien gegen Weltmeister Takeshi Murakami und gewann alle. 2023 zeigten Berechnungen, dass 8 × 8-Othello bei perfektem Spiel beider Seiten remis endet."],"cap":[]}],"tl":[["1880er","Waterman und Mollett streiten in London um die Erfindung"],["1893","Ravensburger bringt Reversi heraus"],["Meiji-Zeit","Japanische Bücher stellen es als Genpei-go vor"],["1973","In Japan kommen Othello-Spiele in den Handel"],["1977","Erste Othello-Weltmeisterschaft in Tokio"],["1997","Logistello schlägt Weltmeister Takeshi Murakami 6:0"],["2023","8 × 8-Othello erweist sich bei perfektem Spiel als remis"]]},"mancala":{"title":"Wo entstand Mancala?","lead":"Ein Spiel, bei dem man Steine von Mulde zu Mulde sät, gespielt in Afrika und Asien unter Hunderten Namen.","s":["Mancala ist der Sammelname für Spiele, bei denen man Steine oder Samen aus einer Mulde nimmt und einzeln in die folgenden sät. Das Wort soll vom arabischen naqala, „bewegen“, kommen.","Namen und Regeln wechseln von Ort zu Ort — Oware in Westafrika, Bao in Ostafrika, Mangala in der Türkei, Congkak in Südostasien und Hunderte mehr —, mit zwei oder vier Reihen und beliebig vielen Mulden.","Oft heißt es, es sei uralt, doch die sicheren Belege sind jünger, als man denkt. Die ältesten sicher datierten Bretter sind bisher Keramik- und Steinbretter aus dem 6.–7. Jahrhundert etwa, gefunden an Stätten des antiken Reichs Aksum in Matara und Yeha (Eritrea und Äthiopien).","Ältere Beispiele wurden vorgeschlagen, doch ob jene Lochreihen wirklich für Mancala dienten, ist unsicher, und die Forschung ist uneins. Eine führende Ansicht lautet, dass sich das Spiel von Aksum nach Arabien und ins Innere Afrikas ausbreitete.","Vollständige Beschreibungen der Spielweise erscheinen erst um das 17. Jahrhundert. Im Atlas kannst du Mancala nach acht Regeln spielen, darunter Oware und Mangala."],"quiz":[["Was bedeutet das arabische Wort hinter „Mancala“?","Bewegen","Samen","Mulde","König"],["Wo fand man die ältesten sicher datierten Mancala-Bretter?","An Stätten des antiken Reichs Aksum (Äthiopien und Eritrea)","Im Kolosseum in Rom","An der Chinesischen Mauer","In Stonehenge"],["Welches Mancala wird in Westafrika gespielt?","Oware","Liubo","Tafl","Pachisi"]],"kf":["Eine Familie von „Säspielen“: Man nimmt die Samen aus einer Mulde und legt sie einzeln in die folgenden","Die ältesten sicher datierten Bretter stammen aus dem alten Reich Aksum, etwa aus dem 6.–7. Jahrhundert","Zwei Reihen oder vier, mit oder ohne Speicher – Brett und Regeln wechseln von Region zu Region"],"more":[{"h":"Säen","p":["Beim Mancala wählt man eine Mulde auf der eigenen Seite, nimmt alle Samen heraus und legt sie einzeln in die folgenden Mulden. Diese Bewegung, wie das Ausstreuen von Saat auf einem Feld, heißt Säen.","Oware aus Westafrika beginnt mit 48 Samen, je vier in 12 Mulden. Macht der letzte Same zwei oder drei in einer gegnerischen Mulde, schlägt man sie. Zu wissen, wo eine Saat endet – vorauszuzählen –, ist alles. Oware überquerte den Atlantik und wird auch in der Karibik gespielt."],"cap":["Säen beim Oware. Die drei Samen der gold umringten Mulde wandern einzeln gegen den Uhrzeigersinn; der letzte macht genau 3 in einer gegnerischen Mulde, die geschlagen werden (roter Ring)"]},{"h":"Zwei Reihen und vier","p":["Mancala-Bretter teilen sich grob in zwei- und vierreihige. Zweireihige sind in Westafrika und Asien verbreitet, vierreihige reichen von Ostafrika bis ins südliche Afrika. Das tansanische Bao hat 4 Reihen zu 8 Mulden; sein Name heißt auf Swahili einfach „Brett“.","Manche, wie Congkak und Sungka in Südostasien, haben an jedem Ende eine große Mulde – einen Speicher – für geschlagene Samen. Kalah, im 20. Jahrhundert in den USA entstanden, ist ein zweireihiges Spiel mit Speichern; 2000 zeigte eine Berechnung, dass Kalah mit sechs Mulden und je vier Samen vom Anziehenden gewonnen wird."],"cap":["Beispiele für Mancala-Bretter: 2 Reihen zu 6 (Oware u. a.), 2 Reihen zu 7 mit je einem Speicher an den Enden (Congkak in Südostasien u. a.), 4 Reihen zu 8 (Bao in Ostafrika u. a.)"]},{"h":"Die es aufschrieben","p":["Als erster europäischer Gelehrter, der Mancala genau beschrieb, gilt meist der Engländer Thomas Hyde. In De Ludis Orientalibus (1694) nannte er den arabischen Namen und die Spielweise.","1836 hielt Edward W. Lane in seiner Schilderung des Alltags in Kairo das „Mankalah“ fest, das in Kaffeehäusern gespielt wurde. Heute haben Forscher Spiele aus aller Welt gesammelt; die aufgezeichneten Regelvarianten gehen in die Hunderte."],"cap":[]}],"tl":[["6.–7. Jh.","Die ältesten sicher datierten Bretter, aus Fundstätten von Aksum"],["1694","Thomas Hyde beschreibt Mancala in De Ludis Orientalibus"],["18.–19. Jh.","Oware und andere gelangen über den Atlantik in die Karibik"],["1836","E. W. Lane hält das Mankalah von Kairo fest"],["Mitte 20. Jh.","Kalah, zweireihig mit Speichern, kommt in den USA in den Handel"],["2000","Berechnung: Kalah mit sechs Mulden und vier Samen gewinnt der Anziehende"]]},"morris":{"title":"Mühle gibt es überall","lead":"Ein Tempeldach, ein Wikingerschiff, eine Steinbank im Dom: Ihre Linien wurden überall eingeritzt, wo Menschen beisammensaßen.","s":["Bei der Mühle setzt jeder neun Steine auf die 24 Punkte dreier ineinanderliegender Quadrate; drei in einer Reihe, eine „Mühle“, schlagen einen gegnerischen Stein. Der englische Name „morris“ hat nichts mit dem Tanz zu tun: Er soll vom lateinischen merellus kommen, Spielmarke.","Ein in eine Dachplatte des Tempels von Kurna in Ägypten geritztes Brett gilt oft als das älteste, um 1400 v. Chr. Der Forscher Friedrich Berger fand aber koptische Kreuze unter denselben Ritzungen und schloss, dass sie sich nicht datieren lassen. Sicher datierte Bretter beginnen in römischer Zeit.","Auf dem Gokstad-Schiff aus Norwegen, um 900, ist ein Brett in eine Decksplanke geschnitten. In England finden sich Bretter auf den Steinbänken der Kreuzgänge von Kathedralen wie Canterbury und Salisbury.","Das Buch der Spiele Alfons’ X. von 1283 zeigt es sogar mit Würfeln gespielt. Bei Shakespeare, im Sommernachtstraum, hat der Regen „das Mühlespiel“ mit Schlamm gefüllt – ein in den Dorfanger gegrabenes Brett.","1996 ließ der Deutsche Ralph Gasser einen Computer alle Stellungen durchsuchen und bewies: Spielen beide perfekt, endet die Partie remis. Zwischen zwei Menschen ist es trotzdem ein sehr gutes Spiel."],"quiz":[["Woher soll der Name „morris“ kommen?","Vom lateinischen Wort für Spielmarke","Von einem englischen Tanz","Von einem Personennamen","Von einem Schiffsnamen"],["Was stellten Forscher zu den Brettern von Kurna fest?","Sie lassen sich nicht datieren","Sie sind aus Gold","Sie kamen aus China","Sie gehörten einem Kaiser"],["Was bewies ein Computer 1996?","Bei perfektem Spiel remis","Der Anziehende gewinnt immer","Der Nachziehende gewinnt immer","Acht Steine genügen"]],"kf":["Je neun Steine auf den 24 Punkten dreier ineinanderliegender Quadrate; drei in einer Reihe schlagen einen gegnerischen Stein","Seit der Römerzeit wurde das Brett überall eingeritzt, wo Menschen zusammenkamen – auf Schiffsdecks, Domsitzbänken","1996 wurden alle Stellungen per Computer untersucht: Bei perfektem Spiel endet Mühle remis"],"more":[{"h":"Setzen, ziehen, springen","p":["Das Spiel hat drei Phasen. Zuerst setzen die Spieler abwechselnd ihre neun Steine auf freie Punkte. Sind alle gesetzt, zieht man je einen Stein entlang einer Linie auf einen benachbarten freien Punkt.","Drei eigene Steine in einer Reihe bilden eine „Mühle“, und man nimmt dem Gegner einen Stein vom Brett. Nach einer verbreiteten Regel darf, wer nur noch drei Steine hat, auf jeden freien Punkt „springen“. Verloren hat, wer nur noch zwei Steine hat oder nicht mehr ziehen kann."],"cap":["Ein Mühlebrett. Weiß hat an der äußeren Kante eine Mühle geschlossen (gold) und darf einen schwarzen Stein nehmen (rotes Kreuz)"]},{"h":"Von drei Steinen bis zwölf","p":["Die Familie wird nach der Zahl der Steine benannt. Die Dreiermühle mit drei Steinen je Spieler ist ein kleines Brett, nahe am Tic-Tac-Toe. Die Sechsermühle nutzt ein Brett aus zwei ineinanderliegenden Quadraten.","Die Zwölfermühle ergänzt das Brett der Neunermühle um Diagonalen. In Südafrika heißt sie Morabaraba; Hirtenjungen sollen sie in den Boden geritzt haben, und heute gibt es eigene Turniere."],"cap":["Bretter im Vergleich. Die Zahl nennt die Steine je Spieler: Dreier-, Sechser-, Neuner- und Zwölfermühle"]},{"h":"Ein Schachweltmeister und ein Computer","p":["Auch Schachweltmeister Emanuel Lasker war von dem Spiel begeistert. In seinem Buch Brettspiele der Völker (1931) schlug er eine Fassung mit je zehn Steinen vor, bei der man schon ziehen darf, bevor alle Steine gesetzt sind.","1996 verband der Schweizer Ralph Gasser vollständige Endspieltabellen mit einer Suche von der Eröffnung aus und zeigte: Bei perfektem Spiel beider Seiten endet Mühle remis. Das Brett hat nur 24 Punkte, doch die Stellungen gehen in die Milliarden."],"cap":[]}],"tl":[["Römerzeit","Bretter werden überall im Reich in Stein geritzt (erste sichere Beispiele)"],["um 900","Ein Brett wird in eine Deckplanke des Gokstad-Schiffs (Norwegen) geritzt"],["1283","Das Buch der Spiele Alfons’ X. bildet Mühle ab"],["Mittelalter","Bretter auf Kreuzgangbänken englischer Kathedralen"],["1590er","Shakespeares Ein Sommernachtstraum erwähnt ein mit Schlamm gefülltes Brett"],["1931","Lasker schlägt in Brettspiele der Völker eine neue Fassung vor"],["1996","Gasser beweist: bei perfektem Spiel remis"]]},"patolli":{"title":"Patolli, das Bohnenrennen der Azteken","lead":"Ein kreuzförmiges Brett und Bohnen als Würfel: ein Spiel mit so hitzigen Wetten, dass die Spanier es verboten.","s":["Patolli war ein Wettlaufspiel der Azteken Mexikos. Der Name bedeutet Bohnen: Man warf fünf rote, auf einer Seite markierte oder durchbohrte Bohnen und zog um die Zahl der sichtbaren Zeichen, auf einer kreuzförmigen Bahn, die auf eine Matte oder den Boden gemalt war.","Diego Durán, der die Gegend im 16. Jahrhundert beschrieb, berichtet, dass die Spieler vor dem Wurf Weihrauch verbrannten, zu den Bohnen beteten und Macuilxochitl, den Gott der Spiele, um den Sieg baten.","Adlige setzten Schmuck, Mäntel, ja sich selbst; manche Verlierer wurden Sklaven. Erzählt wird auch, dass Kaiser Moctezuma seinen Adligen beim Spiel zusah.","Spanische Mönche lehnten das Wetten und die Gebete an die alten Götter ab, verboten Patolli, zerbrachen die Matten und verbrannten die Bohnen; daher sind kaum Spiele erhalten. Doch in Steinböden und Felsen geritzte Bretter fand man in Teotihuacan und an Maya-Stätten, 1977 auch unter Felsbildern in Jalisco.","Ein kreuzförmiges Brett, um das die Steine laufen, erinnert stark an das indische Pachisi. 1878 vertrat der Engländer E. B. Tylor einen asiatischen Ursprung; heute meint man meist, dass beide unabhängig entstanden."],"quiz":[["Was warf man beim Patolli statt Würfeln?","Markierte Bohnen","Tierknochen","Muscheln","Holzstäbe"],["Warum wurde Patolli laut den Quellen verboten?","Wetten und Gebete an die alten Götter","Das Brett war zu groß","Bohnen waren zu teuer","Der König verlor"],["Welchem Spiel ähnelt das Patolli-Brett sehr?","Pachisi","Go","Dame","Mancala"]],"kf":["Ein aztekisches Wettlaufspiel: Man wirft fünf markierte Bohnen und zieht Figuren über ein kreuzförmiges Brett","Weil es mit Wetten und Gebeten an die Götter verbunden war, verboten es die spanischen Mönche","Es gleicht dem indischen Pachisi verblüffend, doch beide sind wohl unabhängig voneinander entstanden"],"more":[{"h":"Ein Kreuzweg aus 52 Feldern","p":["Das Patolli-Brett ist ein kreuzförmiger Weg, gemalt auf Tuch, eine Matte oder einen Steinboden. Rekonstruktionen geben jedem der vier Arme meist zwei Bahnen von Feldern, die mit den vier Mittelfeldern 52 ergeben.","Zweiundfünfzig ist auch die Zahl der Jahre im aztekischen Kalenderzyklus, und manche Forscher sehen im Brett ein Bild des Kalenders oder der verrinnenden Zeit. Man führte seine Figuren einmal ganz herum; wer zuerst heimkam, gewann."],"cap":["Ein Patolli-Brett, wie es oft rekonstruiert wird: vier Arme mit zwei Bahnen zu je sechs Feldern und vier Mittelfeldern, zusammen 52. Die roten Felder an den Armenden gelten als besondere"]},{"h":"Fünf Bohnen","p":["Statt Würfeln warf man fünf Bohnen, die auf einer Seite ein Loch oder Zeichen trugen, und zog so viele Felder, wie Zeichen oben lagen. Alle fünf Zeichen kommen nur einmal in 32 Würfen.","Vor dem Wurf soll man zu den Bohnen gesprochen und Macuilxochitl, den Gott der Spiele, angerufen haben. Der Codex Magliabechiano aus dem 16. Jahrhundert zeigt Menschen um ein Patolli-Brett unter den Augen des Gottes."],"cap":["Von fünf Bohnen: wie viele mit der markierten Seite nach oben fallen (0–5) und wie oft (von 32), wenn jede gleich oft auf jede Seite fällt"]},{"h":"Der Doppelgänger des Pachisi","p":["Figuren, die um ein kreuzförmiges Brett laufen, Züge nach der Zahl der geworfenen Lose mit der Vorderseite oben: Patolli und das indische Pachisi oder Chaupar sind sich erstaunlich ähnlich. 1878 erklärte der britische Anthropologe Tylor, das sei kein Zufall, sondern ein Zeichen, dass das Spiel aus Asien kam.","Doch ein Beweis für eine solche Überquerung der Ozeane wurde nie gefunden. Heute nimmt man meist an, dass Menschen an verschiedenen Orten unabhängig auf dieselben Ideen kamen: einen Weg, der herumführt, und Dinge zum Werfen."],"cap":["Ein Bild des Chaupar in Indien (1694–95): Figuren, die ein kreuzförmiges Brett umrunden – wie beim Patolli"]}],"tl":[["Teotihuacan-Zeit","Kreuzförmige Bretter werden in Steinböden geritzt"],["1519–21","Spanien erobert das Aztekenreich"],["16. Jh.","Der Codex Magliabechiano zeigt Patolli und Macuilxochitl"],["um 1577","Sahagún hält Patolli im Florentiner Codex fest"],["um 1581","Durán beschreibt Gebete und Wetten"],["1878","Tylor vertritt einen asiatischen Ursprung"],["1977","In Jalisco wird ein Brett unter Felsbildern gefunden"]]},"xiangqi":{"title":"Fluss und Kanone im Xiangqi","lead":"Ein „Fluss“ in der Mitte und eine Kanone, die zum Schlagen springt: Wann bekam das chinesische Schach seine heutige Form?","s":["Xiangqi ist chinesisches Schach, gespielt auf den Punkten eines 9×10-Gitters. Die Steine sind runde Scheiben mit Schriftzeichen und ziehen auf den Linien, nicht in Feldern wie beim Schach.","Ein früher Hinweis ist das Xuanguai lu, eine Sammlung seltsamer Geschichten des Tang-Ministers Niu Sengru (779–847). Der Traum eines Mannes von einem winzigen Heer nennt ein Himmelspferd, einen General, Wagen und Fußsoldaten, dazu Andeutungen eines Katapults. Brett und Züge sind aber noch nicht die heutigen.","Die heutige Form – 9×10-Brett, Fluss und Kanone – erscheint in Quellen der Song-Dynastie (960–1279). In einem Grab der Nördlichen Song in Luoyang fand man einen vollständigen Satz Steine.","Auf dem Fluss steht oft „Chu-Fluss, Han-Grenze“, nach der Linie zwischen Xiang Yus Chu und Liu Bangs Han in ihrem Krieg im 3. Jahrhundert v. Chr. Der General darf seinen Palast nicht verlassen, und die beiden Generäle dürfen sich nie ohne etwas dazwischen gegenüberstehen.","Die Kanone schlägt nur, indem sie genau einen Stein überspringt. In Vietnam ist Xiangqi als cờ tướng beliebt, in Korea wurde daraus der enge Verwandte Janggi. Im Atlas kannst du beide spielen."],"quiz":[["Wo ziehen die Xiangqi-Steine?","Auf den Punkten der Linien","In Feldern","Um einen Kreis","Auf Sechsecken"],["In welcher Dynastie erscheint das heutige Xiangqi in den Quellen?","Song","Han","Ming","Qing"],["Wie schlägt die Kanone?","Indem sie einen Stein überspringt","Einen Schritt geradeaus","Zwei Schritte diagonal","Erst nach dem Fluss"]],"kf":["Chinesisches Schach: runde, beschriftete Steine kämpfen auf den Punkten eines Gitters aus 9 × 10 Linien","Ein „Fluss“ quert die Mitte, und jede Seite hat einen „Palast“ für ihren General; jeder Stein hat sein Gebiet","In der Song-Zeit erhielt es seine heutige Form und wird noch immer von zig Millionen in China und Vietnam gespielt"],"more":[{"h":"Ein Brett mit Fluss und Palästen","p":["Jede Seite hat 16 Steine: einen General, 2 Berater, 2 Elefanten, 2 Pferde, 2 Wagen, 2 Kanonen und 5 Soldaten. Rot und Schwarz schreiben manche gleichrangigen Steine mit leicht verschiedenen Zeichen.","General und Berater dürfen den Palast nicht verlassen, Elefanten den Fluss nicht überqueren. Soldaten ziehen bis zum Fluss nur vorwärts, danach auch seitwärts. Ein Pferd kann nicht springen, wenn direkt neben ihm in Zugrichtung ein Stein steht. Das Brett selbst bestimmt, was jeder Stein kann."],"cap":["Die Anfangsstellung im Xiangqi. Schwarz oben, Rot unten. Die Zeichen 楚河 漢界 markieren den Fluss; die 3 × 3-Felder mit Diagonalen sind die Paläste"]},{"h":"Die springende Kanone","p":["Die Kanone zieht sonst wie ein Wagen beliebig weit entlang einer Linie. Um zu schlagen, muss sie aber genau einen Stein dazwischen überspringen – gleich welcher Farbe –, den sogenannten Schirm.","Das Spiel mit Schirmen erzeugt eine Taktik, die es sonst nirgends gibt. Die Kanone zu Beginn auf die Mittellinie zu ziehen, die „Mittelkanone“, ist bis heute eine der beliebtesten Eröffnungen."],"cap":["So schlägt die Kanone: Die rote Kanone überspringt genau einen Stein dazwischen – das schwarze Pferd – und schlägt den schwarzen Wagen dahinter"]},{"h":"Partiensammlungen und Meister","p":["In der Ming-Zeit entstanden viele Bücher mit schönen Partien und Aufgaben. Shiqing yaqu (1570) und Juzhong mi (1632) sind Klassiker, die noch heute studiert werden.","Im 20. Jahrhundert gewann Hu Ronghua zehnmal in Folge die chinesische Landesmeisterschaft, und 1993 wurde der Weltverband für Xiangqi gegründet, mit internationalen Turnieren. In Parks in China und Vietnam bilden sich jeden Tag Kreise von Zuschauern um das Brett."],"cap":[]}],"tl":[["9. Jh.","Niu Sengrus Xuanguai lu nennt General, Wagen und Pferd"],["Song (960–1279)","Die heutige Form mit 9 × 10-Brett, Fluss und Kanone erscheint in den Quellen"],["Nördliche Song","Ein vollständiger Steinsatz wird in ein Grab in Luoyang gelegt"],["1570","Die Partiensammlung Shiqing yaqu"],["1632","Die Partiensammlung Juzhong mi"],["1960er–70er","Hu Ronghua gewinnt zehn Landesmeistertitel in Folge"],["1993","Gründung des Weltverbands für Xiangqi"]]},"backgammon":{"title":"Ist Backgammon 5000 Jahre alt?","lead":"Das Brett, das „ältestes Backgammon“ heißt, und die wahren Vorfahren des Spiels – vom persischen Hof bis in die Klubs von New York.","s":["Die „Verbrannte Stadt“ Shahr-e Sukhteh im Iran lieferte ein etwa 5000 Jahre altes Brett mit 60 Steinen und Würfeln, oft das älteste Backgammon genannt. Seine Felder bilden aber die Windungen einer geschnitzten Schlange, etwa zwanzig – eine andere Form als das heutige Spiel.","Der wahrscheinliche direkte Vorfahr des Backgammon ist das persische Nard, das zwischen dem 3. und 6. Jahrhundert aufkam. Eine mittelpersische Erzählung aus dem 7. bis 9. Jahrhundert berichtet, der Minister Bozorgmehr habe das Rätsel des aus Indien geschickten Schachs gelöst und als Antwort Nard erfunden.","Rom hatte ein eigenes Brettspiel mit drei Würfeln, die Tabula – Kaiser Zenons unglückliche Partie aus Geschichte 3. Diese Familie der „Tables“ verbreitete sich über ganz Europa und brachte viele Verwandte hervor, etwa das französische Tricktrack.","Der Name „Backgammon“ taucht im England des 17. Jahrhunderts auf, und 1743 veröffentlichte Edmond Hoyle Regeln und Strategie.","Die letzte große Erfindung, der Verdopplungswürfel, soll in den 1920er-Jahren in New Yorker Klubs entstanden sein. Weil man damit mitten im Spiel den Einsatz verdoppeln kann, wurde Backgammon zu einem tiefen Spiel des richtigen Zeitpunkts."],"quiz":[["Welche Form hat das Brett von Shahr-e Sukhteh?","Felder aus den Windungen einer Schlange","Wie das heutige Backgammon","Eine runde Scheibe","Ein Kreuz"],["Wer erfand laut der Erzählung das Nard?","Der Minister Bozorgmehr","Kaiser Zenon","Edmond Hoyle","Alfons X."],["Was soll in den 1920ern in New York entstanden sein?","Der Verdopplungswürfel","Die zwei Würfel","Die 24 Zungen","Die fünfzehn Steine"]],"kf":["Je fünfzehn Steine laufen nach zwei Würfeln über 24 Zungen; wer zuerst alle abgetragen hat, gewinnt","Direkte Vorfahren sind das persische Nard und die römische Tabula aus der Familie der „Tables“","Der Doppelwürfel und Computer verliehen ihm im 20. Jahrhundert neue Tiefe"],"more":[{"h":"Fünfzehn Steine und 24 Zungen","p":["Das Brett hat 24 lange Dreiecke, die Zungen, und jeder Spieler 15 Steine. Man würfelt mit zwei Würfeln und zieht je einen Stein um jede Augenzahl oder einen Stein um beide. Bei einem Pasch darf man die Zahl viermal nutzen.","Zieht man auf einen einzelnen gegnerischen Stein, wird er geschlagen und auf die Bar in der Mitte gesetzt; er muss über das Heimfeld des Gegners wieder hereinkommen. Sind alle fünfzehn eigenen Steine im Heimfeld, trägt man sie ab, und wer zuerst fertig ist, gewinnt."],"cap":["Die Anfangsstellung im Backgammon. Weiß zieht von 24 nach 1 (gegen den Uhrzeigersinn); die Zungen 1–6 unten rechts sind sein Heimfeld. Schwarz zieht andersherum"]},{"h":"Je näher, desto leichter getroffen","p":["Ob man einen einzelnen Stein treffen kann, hängt stark vom Abstand ab. Bei sechs Zungen treffen 17 der 36 Würfe, bei sieben nur noch 6.","Wer diese Zahlen kennt, sieht, wo ein Stein gefährdet ist. Zu Beginn braucht jeder Spieler 167 Augen, um alle Steine heim- und abzutragen; starke Spieler zählen diesen „Pip Count“, um die Lage einzuschätzen."],"cap":["Wie viele der 36 Würfe mit zwei Würfeln einen einzelnen Stein in 1 bis 12 Zungen Abstand treffen können (ohne Hindernis)"]},{"h":"Vom Club zur Weltmeisterschaft","p":["1743 veröffentlichte Edmond Hoyle in England ein Buch über Regeln und Strategie. Im Großbritannien des 19. Jahrhunderts war das Spiel so beliebt, dass man es auf Möbel malte, und in New Yorker Clubs der 1920er entstand der Doppelwürfel.","1964 fand auf den Bahamas eine Weltmeisterschaft statt, in den 1970ern erlebte das Spiel einen Boom. 1979 schlug Hans Berliners Programm Weltmeister Luigi Villa, und um 1992 erreichte TD-Gammon, das durch Spiele gegen sich selbst lernte, beinahe die Stärke der besten Menschen."],"cap":["Ein Schrank, bemalt mit zwei Backgammonspielern (London, 1861), ein frühes Stück von Morris, Marshall, Faulkner & Co."]}],"tl":[["um 3000 v. Chr.","In Shahr-e Sukhteh werden ein Schlangenbrett, Steine und Würfel bestattet"],["um 3.–6. Jh.","In Persien erscheint Nard"],["1743","Hoyle veröffentlicht sein Backgammon-Buch"],["1920er","In New York entsteht der Doppelwürfel"],["1964","Weltmeisterschaft auf den Bahamas"],["1979","Berliners Programm schlägt den Weltmeister"],["um 1992","TD-Gammon, das durch Spiel gegen sich selbst lernt, erscheint"]]},"hex":{"title":"Hex, zweimal erfunden","lead":"Ein dänischer Dichter und ein junges amerikanisches Genie erdachten dasselbe Spiel, ohne voneinander zu wissen.","s":["Bei Hex setzen die Spieler abwechselnd Steine auf eine Raute aus Sechsecken; wer seine beiden gegenüberliegenden Seiten verbindet, gewinnt. Das ist alles.","Als Erster dachte es sich der dänische Mathematiker und Dichter Piet Hein aus. 1942 stellte er es im Niels-Bohr-Institut in Kopenhagen vor; am 26. Dezember jenes Jahres druckte die Zeitung Politiken es als „Polygon“, verkauft wurde es als Block mit 50 Blättern.","1943 musste Hein Dänemark verlassen, und das Spiel verschwand. Einige Jahre später, 1948/49, erfand John Nash, Doktorand in Princeton, ganz unabhängig dasselbe Spiel; seine Mitspieler sollen es „Nash“ genannt haben.","1952 brachte Parker Brothers es als „Hex“ heraus, und 1957 stellte Martin Gardner es in seiner Kolumne im Scientific American vor und machte es weltweit bekannt.","Hex kann nie unentschieden enden. Und Nash bewies, dass der Anziehende immer eine Gewinnstrategie hat – ohne sie anzugeben. Auf großen Brettern ist dieser Gewinnweg bis heute unbekannt."],"quiz":[["Wie gewinnt man bei Hex?","Die eigenen zwei Seiten verbinden","Alle Steine schlagen","Den König umzingeln","Fünf in einer Reihe"],["Wie hieß Heins Spiel in der dänischen Zeitung?","Polygon","Nash","Con-tac-tix","Othello"],["Was bewies Nash?","Der Anziehende kann immer gewinnen","Der Nachziehende gewinnt immer","Es endet immer remis","Die genauen Gewinnzüge"]],"kf":["Abwechselnd setzt man Steine auf sechseckige Felder; wer seine beiden gegenüberliegenden Ränder verbindet, gewinnt","Unabhängig erfunden von Piet Hein in Dänemark (1942) und John Nash in den USA (1948–49)","Es gibt kein Remis, und der Anziehende gewinnt nachweislich – doch auf großen Brettern weiß niemand, wie"],"more":[{"h":"Ein Spiel des Verbindens","p":["Das Brett ist eine Raute aus sechseckigen Feldern; die Standardgröße ist 11 × 11. Rot gehören oberer und unterer Rand, Blau der linke und rechte, und abwechselnd wird je ein Stein gesetzt. Steine ziehen nie und werden nie geschlagen.","Ist das Brett voll, ist immer eine Seite verbunden. Sechsecke berühren sich nie nur an einer Ecke, man kann also nicht durch die gegnerische Linie schlüpfen. 1979 zeigte der Mathematiker David Gale, dass diese „Kein-Remis“-Eigenschaft einem berühmten Satz der Mathematik gleichwertig ist: dem Brouwerschen Fixpunktsatz."],"cap":["Ein 7 × 7-Hex-Brett. Rot gewinnt, wenn es oben und unten verbindet, Blau links und rechts. Die gold umrandeten roten Steine haben oben und unten verbunden"]},{"h":"Brücken und Leitern","p":["Ein Lieblingswerkzeug starker Spieler ist die Brücke. Setzt man einen Stein nicht direkt neben den vorigen, sondern ein Feld weiter, teilen sich beide zwei freie Nachbarfelder. Blockiert der Gegner eines, nimmt man das andere – praktisch sind sie schon verbunden.","An den Rändern kennt man viele feste Formen, etwa „Leitern“ aus Steinen, die am Rand entlang bis zur Seite laufen. Weil der Anziehende zu stark im Vorteil ist, gilt meist die Tauschregel: Nach dem ersten Zug darf der Nachziehende diesen Stein als seinen übernehmen."],"cap":["Die „Brücke“. Die beiden roten Steine lassen sich über jedes der zwei freien Felder dazwischen verbinden (gestrichelte Kreise). Setzt Blau auf eines, nimmt Rot das andere"]},{"h":"Ein Spiel für Mathematiker","p":["Nash bewies mit einem „Strategieklau“-Argument, dass der Anziehende gewinnt: Hätte der Nachziehende eine Gewinnstrategie, könnte der Anziehende sie übernehmen – ein Widerspruch. Ein seltsamer Beweis, der keinen einzigen Gewinnzug zeigt.","In den 1950ern baute Claude Shannon, der Vater der Informationstheorie, eine Maschine, die mit einem elektrischen Schaltkreis Hex spielte. In den 2010ern lösten Computer alle Bretter bis 9 × 9, doch das offizielle 11 × 11-Brett ist bis heute ungelöst."],"cap":[]}],"tl":[["1942","Hein veröffentlicht „Polygon“ in einer dänischen Zeitung"],["1948–49","Nash in Princeton erfindet dasselbe Spiel"],["1952","Parker Brothers verkauft es als „Hex“"],["1950er","Shannon baut eine elektrische Hex-Maschine"],["1957","Gardner stellt es in seiner Kolumne vor"],["1979","Gale zeigt die Verbindung zum Fixpunktsatz"],["2010er","Bretter bis 9 × 9 werden per Computer gelöst"]]},"foxgeese":{"title":"Der Fuchs, die Gänse und die Silberfiguren des Königs","lead":"Ein Fuchs, viele Gänse: die lange Geschichte eines „Jagdspiels“, in dem die beiden Seiten nicht gleich sind.","s":["Bei Fuchs und Gänse springt ein einzelner Fuchs über die Gänse, um sie zu fressen, während die Gänse ihn einzusperren versuchen, damit er sich nicht mehr bewegen kann. Beide Seiten spielen nach eigenen Regeln, auf einem kreuzförmigen Brett aus 33 durch Linien verbundenen Punkten.","Ein früher Hinweis ist das „Halatafl“ in der isländischen Grettis saga, entstanden um das 14. Jahrhundert. Es bedeutet „Schwanzbrett“, gemeint ist wohl der Fuchsschwanz. Vermutlich war es ein Ableger der nordischen Tafl-Spiele.","In England verzeichnen die Rechnungen König Eduards IV. aus dem 15. Jahrhundert den Kauf von „zwei Füchsen und 26 Hunden aus vergoldetem Silber“ – Figuren für zwei Spiele, damals offenbar „Fuchs und Hunde“ genannt.","Mit den ursprünglichen 13 Gänsen war der Fuchs zu stark, deshalb verbreiteten sich Spielweisen mit mehr Gänsen. Im 19. Jahrhundert soll Königin Victoria das Spiel gemocht haben.","Dasselbe Kreuzbrett dient dem Solitär, einem Spiel für eine Person. Jagdspiele, in denen ein Tiger oder Wolf seine Beute verfolgt, wie das nepalesische Bagh-Chal, gibt es überall auf der Welt. Im Atlas kannst du Fuchs und Gänse und Solitär spielen."],"quiz":[["Was bedeutet „hala“ in Halatafl?","Schwanz","Fuchs","König","Schnee"],["Welche Figuren stehen in Eduards IV. Rechnungen?","Füchse und Hunde aus Silber","Goldene Gänse","Ein Elfenbeinkönig","Holzwürfel"],["Welches Einpersonenspiel nutzt dasselbe Kreuzbrett?","Solitär (Steckspiel)","Sudoku","Patience (Karten)","Tangram"]],"kf":["Ein Fuchs gegen 13 (später 17) Gänse auf einem kreuzförmigen Brett mit 33 Punkten","Der Fuchs schlägt durch Überspringen; die Gänse gewinnen, wenn sie ihn einkesseln, bis er nicht mehr ziehen kann","Dasselbe Brett dient für Solitär, und solche Jagdspiele gibt es auf der ganzen Welt"],"more":[{"h":"Einer gegen dreizehn","p":["Der Fuchs zieht einen Schritt entlang der Linien und schlägt, indem er eine benachbarte Gans überspringt, wenn der Punkt dahinter frei ist; wie bei Dame darf er mehrmals hintereinander springen. Die Gänse schlagen nicht und dürfen in vielen Varianten nicht rückwärts.","Die Gänse wollen lückenlos aufrücken, den Fuchs in die Enge treiben und ihm jeden Zug nehmen. Mit dreizehn Gänsen gilt der Fuchs als zu stark; mit siebzehn Gänsen, die nicht zurück dürfen, sollen die Gänse bei gutem Spiel gewinnen."],"cap":["Ein Brett für Fuchs und Gänse: 33 Punkte als Kreuz, durch Linien verbunden. Dreizehn Gänse stehen oben; der Fuchs (orange) kann die Gans direkt vor ihm (×) schlagen, indem er auf den freien Punkt dahinter springt"]},{"h":"Die Familie der Jagdspiele","p":["Wenige starke Steine jagen viele schwache: Solche Jagdspiele gibt es überall. Beim nepalesischen Bagh-Chal jagen vier Tiger zwanzig Ziegen auf einem 5 × 5-Brett; 2004 zeigte eine Berechnung, dass es bei perfektem Spiel remis endet.","Asalto, im Deutschland des 19. Jahrhunderts beliebt, nutzt dasselbe Kreuzbrett: zwei Offiziere gegen vierundzwanzig Soldaten. Hier verteidigen die Offiziere eine Festung, die die Soldaten stürmen wollen."],"cap":["Jagdspiele in Zahlen: links die Jäger (orange), rechts die Gejagten (weiß). Von oben: Fuchs und Gänse (1:13), die Fassung mit mehr Gänsen (1:17), Bagh-Chal aus Nepal (4:20) und Asalto (2:24)"]},{"h":"Von königlichen Figuren zum Solitär","p":["Die Rechnungen Eduards IV. von England (reg. 1461–83) verzeichnen den Kauf vergoldeter Silberfiguren für ein Spiel von Fuchs und Hunden. Es war auch ein Zeitvertreib von Königen und Adligen.","Dasselbe Kreuzbrett mit 33 Löchern dient dem Solitär, das man allein spielt. Ein französischer Stich von 1697 zeigt eine vornehme Dame bei diesem Spiel – eines der ältesten Zeugnisse des Solitärs."],"cap":[]}],"tl":[["um 14. Jh.","In der isländischen Grettis saga erscheint das „Hala-tafl“"],["spätes 15. Jh.","Eduard IV. kauft Silberfiguren für Fuchs und Hunde"],["1697","Ein französischer Stich zeigt eine Dame beim Solitär"],["19. Jh.","Königin Victoria soll das Spiel gemocht haben"],["19. Jh.","Asalto auf demselben Brett wird in Deutschland beliebt"],["2004","Bagh-Chal aus Nepal erweist sich bei perfektem Spiel als remis"]]},"latrunculi":{"title":"Das Brett der römischen Soldaten","lead":"Ein Spiel, das die Römer begeisterte, benannt nach Söldnern. Kein Regelbuch ist erhalten – nur Gedichte, Anekdoten und Bretter aus dem Boden.","s":["Ludus latrunculorum war ein Kampfspiel für zwei im alten Rom. Latrunculi bedeutete ursprünglich Söldner oder Räuber, und die Steine standen für Soldaten.","Die Steine zogen auf einem Gitter, und ein Stein zwischen zwei gegnerischen war geschlagen. Ein Gedicht des 1. Jahrhunderts, die Laus Pisonis, schildert Steine, die vorrücken und zurückweichen, und einen eingeschlossenen Stein, der sich nicht mehr rühren kann.","Der Philosoph Seneca erzählt von Julius Canus, den Kaiser Caligula zum Tod verurteilt hatte. Als der Zenturio ihn holen kam, spielte Canus gerade Latrunculi; er zählte die Steine und sagte seinem Gegner, er solle nach seinem Tod nicht behaupten, gewonnen zu haben.","Bretter wurden im ganzen Reich gefunden. Die in Steine von Kastellen und Städten geritzten Gitter reichen von etwa 8 × 8 bis 12 × 12. Ein Grab des 1. Jahrhunderts in Stanway (England) enthielt Glassteine, noch auf ihrem Brett aufgestellt.","Ein ausführliches Regelbuch ist nicht erhalten; die heutigen Regeln sind Rekonstruktionen von Forschern. Das Latrunculi des Atlas beruht auf einer davon."],"quiz":[["Wie schlägt man bei Latrunculi einen Stein?","Indem man ihn zwischen zwei Steinen einschließt","Indem man ihn überspringt","Durch einen Würfelwurf","Indem man den König umzingelt"],["Wer spielte Latrunculi, als man ihn zur Hinrichtung abholte?","Julius Canus","Caesar","Nero","Cicero"],["Was lag im Grab von Stanway noch auf dem Brett?","Glassteine","Goldmünzen","Schachfiguren","Spielkarten"]],"kf":["Ein Kampfspiel für zwei im alten Rom, die Steine als Soldaten gedacht","Ein Stein zwischen zwei Gegnern ist geschlagen; auch zugunfähige Steine werden erwähnt","Ohne Regelbuch: rekonstruiert aus Gedichten, Anekdoten und ausgegrabenen Brettern"],"more":[{"h":"Einschließen und umzingeln","p":["Die reichste Quelle für Rekonstruktionen ist das Gedicht Laus Pisonis aus dem 1. Jahrhundert. Es schildert das Spiel wie ein Schlachtfeld: Ein Stein rückt vor, um den Feind zu locken, ein anderer deckt ihm den Rücken, und wer zwischen zwei Gegner gerät, ist verloren.","Das Gedicht spricht auch von einem eingeschlossenen, zugunfähigen Stein; viele Rekonstruktionen haben daher neben dem Schlagen durch Einschließen eine Regel für blockierte Steine. Die nordischen Tafl-Spiele kennen ein sehr ähnliches Schlagen."],"cap":["Schlagen bei Latrunculi (Rekonstruktion). Links: Zieht man wie der blaue Pfeil, sitzt der weiße Stein zwischen zwei schwarzen und ist geschlagen (×). Rechts: Ein von vier Seiten blockierter weißer Stein kann nicht ziehen"]},{"h":"Ein Brett mit zwei Seiten","p":["In einem Gedicht zu einem Geschenk beschreibt der Dichter Martial (1. Jahrhundert) ein Brett, auf dessen einer Seite die Steine nach den Würfeln ziehen, während auf der anderen Soldaten zweier Farben kämpfen – ein Glücks- und ein Denkspiel auf einem Brett.","Die Würfelseite gilt als das Laufspiel „zwölf Linien“, ein Vorläufer von Tabula und Backgammon. Der Würfelturm (Pyrgus) in der Sammlung des Museums ist ein weiteres Gerät der Römer."],"cap":["Martials doppelseitiges Brett, wie man es sich vorstellt: auf der einen Seite ein Wettlauf auf zwölf Linien mit Würfeln, auf der anderen das Gitter der Soldaten"]},{"h":"Bretter aus dem Boden","p":["Römische Soldaten ritzten Gitter in Steine und Böden ihrer Kastelle, um zu spielen. Eingeritzte Bretter fand man nahe dem Hadrianswall in Britannien sowie in Deutschland, Spanien und Nordafrika.","Im Grab von Stanway (Mitte des 1. Jahrhunderts) war das Holzbrett vermodert, doch die weißen und blauen Glassteine lagen noch an ihrem Platz, wie mitten in einer Partie. Ihr Besitzer war vielleicht Arzt: Mit ihnen wurden medizinische Instrumente begraben."],"cap":["Ein Würfelturm (Pyrgus). Die Römer warfen die Würfel durch solche Türme, um Betrug zu verhindern"]}],"tl":[["1. Jh. v. Chr.","Varro erwähnt die Latrunculi"],["spätes 1. Jh. v. Chr.","Ovid spielt in seiner Liebesdichtung auf das Spiel an"],["1. Jh.","Die Laus Pisonis beschreibt das Spiel in Versen"],["Mitte 1. Jh.","In Stanway wird ein Brett mit aufgestellten Steinen bestattet"],["1. Jh.","Seneca erzählt die Anekdote von Julius Canus"],["spätes 1. Jh.","Martial beschreibt ein doppelseitiges Brett"],["1994","Schädler veröffentlicht eine Rekonstruktion der Regeln"]]},"amazons":{"title":"Das Spiel, das sein eigenes Brett verbrennt","lead":"Das 1988 in Argentinien erfundene Amazonenspiel verbindet die Züge der Schachdame mit dem Gebietszählen des Go.","s":["Das Amazonenspiel ist ein Spiel für zwei auf einem 10 × 10-Brett, jede Seite mit vier „Amazonen“. Erfunden hat es 1988 der Argentinier Walter Zamkauskas.","Ein Zug besteht aus zwei Teilen. Zuerst zieht eine Amazone wie die Dame im Schach geradeaus waagerecht, senkrecht oder schräg; dann schießt sie von ihrem Zielfeld aus auf dieselbe Weise einen Pfeil. Das Feld, auf dem der Pfeil landet, darf nie wieder überquert werden.","Jeder Zug füllt ein weiteres Feld, und wer nicht mehr ziehen kann, verliert. Remis gibt es nicht.","Gegen Ende zerteilen die Pfeile das Brett in getrennte Räume. Dann gewinnt, wer mehr eigene freie Felder hat; man beurteilt die Stellung also durch Gebietszählen wie beim Go.","Es gibt über 2.000 mögliche erste Züge, was das Spiel selbst für Computer schwer macht. Mathematiker erforschen es, und es ist eine Disziplin bei Computerturnieren."],"quiz":[["In welchem Land entstand das Amazonenspiel?","Argentinien","Brasilien","Spanien","Mexiko"],["Was geschieht mit dem Feld, auf das ein Pfeil geschossen wird?","Niemand darf es mehr überqueren","Es verschwindet im nächsten Zug","Es wird zum gegnerischen Stein","Es bringt einen Punkt"],["Wer verliert beim Amazonenspiel?","Wer zuerst nicht mehr ziehen kann","Wer zuerst einen Stein verliert","Wer zuerst ein Gebiet bildet","Wer seine Zeit überschreitet"]],"kf":["Ein Spiel für zwei auf einem 10 × 10-Brett, 1988 in Argentinien erfunden","Die Amazone zieht wie eine Dame und schießt von ihrem Zielfeld einen Pfeil, der ein Feld verbrennt","Wer nicht ziehen kann, verliert; am Ende zählt man Gebiet wie beim Go"],"more":[{"h":"Ziehen, dann schießen","p":["Eine Amazone darf beliebig weit ziehen, solange sie keinen Stein und keinen Pfeil überspringt. Von ihrem Zielfeld aus schießt sie dann einen Pfeil, ebenfalls mit Damenzug – sogar zurück auf das Feld, das sie gerade verlassen hat.","Geschlagen wird nie. Stattdessen sperrt jeder Zug ein Feld des Bretts und verbaut dem Gegner Wege: Angriff und Verteidigung entscheiden sich mit demselben Pfeil."],"cap":["Ein Zug im Amazonenspiel. Die weiße Amazone zieht wie eine Dame (blau) und schießt von dort auf dieselbe Weise einen Pfeil (rot). Das Pfeilfeld ist für immer gesperrt"]},{"h":"Ein Brett in Räumen","p":["Im Lauf der Partie unterteilen die Pfeile das Brett in Räume. Stehen in einem Raum nur Amazonen eines Spielers, gehören dessen freie Felder ihm allein – eines pro Zug zu verbrauchen.","Dann wird die Partie zur Zählung: Wer mehr nutzbare Felder hat, kann länger ziehen. Das passt gut zur kombinatorischen Spieltheorie, und Elwyn Berlekamp und andere haben Amazonen-Endspiele gründlich erforscht."],"cap":["Eine Endstellung (Illustration). Mauern aus verbrannten Feldern teilen das Brett in vier Räume: die grünen kann nur Weiß nutzen, die blauen nur Schwarz. Wer mehr freie Felder hat, kann länger ziehen"]},{"h":"Aus einer Zeitschrift, von Computern gespielt","p":["Erstmals erschienen sein soll das Spiel in einer argentinischen Rätselzeitschrift. Die Regeln sind kurz, ein Schachbrett und ein paar Steine genügen – so verbreitete es sich über das Internet weltweit.","Bei über 2.000 möglichen ersten Zügen verlangt die Eröffnung ein Gespür für das ganze Brett, ähnlich wie Go. Seit den 2000ern ist es eine Disziplin bei Computerturnieren, wo Programme gegeneinander antreten."],"cap":[]}],"tl":[["1988","Walter Zamkauskas erfindet das Amazonenspiel"],["1990er","Verbreitung über das Internet in aller Welt"],["2000","Berlekamp veröffentlicht mathematische Arbeiten zu den Endspielen"],["2000er","Disziplin bei der Computer-Olympiade"]]},"loa":{"game":"Lines of Action","title":"Steine, die so weit ziehen, wie man zählt","lead":"Lines of Action kam 1969 in einem Buch von Sid Sackson in die Welt. Man gewinnt nicht durch Schlagen, sondern indem man alle eigenen Steine zu einer Gruppe verbindet.","s":["Lines of Action (LOA) ist ein Spiel für zwei auf einem 8 × 8-Brett mit je zwölf Steinen. Erfunden hat es Claude Soucie; bekannt wurde es 1969 durch A Gamut of Games, ein Buch des Spielesammlers Sid Sackson.","Ein Stein zieht geradeaus – waagerecht, senkrecht oder diagonal. Wie weit, ist genau die Zahl der Steine – eigene und gegnerische – auf dieser Linie. Jeder Zug ändert die Zahlen und damit die Entfernungen.","Eigene Steine darf man überspringen, gegnerische nie. Landet man auf einem gegnerischen Stein, wird er geschlagen.","Ziel ist es, alle eigenen Steine zu einer einzigen Gruppe zu verbinden, die sich waagerecht, senkrecht oder diagonal berühren. Schlagen verkleinert die gegnerische Armee – und kann ihr sogar helfen, sich zu verbinden: ein kurioser Dreh.","Die Regeln sind kurz, doch das Vorausrechnen ist schwer; deshalb wird das Spiel seit Langem in der Spiele-KI-Forschung genutzt. Programme der Universität Maastricht in den Niederlanden haben viele Computerturniere gewonnen."],"quiz":[["Was bestimmt, wie viele Felder ein Stein zieht?","Die Zahl der Steine auf dieser Linie","Ein Würfelwurf","Die Zahl der bisher geschlagenen Steine","Es sind immer drei Felder"],["Wie gewinnt man bei LOA?","Indem man alle eigenen Steine zu einer Gruppe verbindet","Indem man alle gegnerischen Steine schlägt","Indem man den gegenüberliegenden Rand erreicht","Indem man den gegnerischen König schlägt"],["Wer stellte LOA 1969 in einem Buch vor?","Sid Sackson","Martin Gardner","Edmond Hoyle","H. J. R. Murray"]],"kf":["Spiel für zwei auf einem 8 × 8-Brett mit je zwölf Steinen; erfunden von Claude Soucie, 1969 in einem Buch von Sid Sackson vorgestellt","Ein Stein zieht genau so viele Felder, wie Steine auf seiner Linie stehen; eigene darf er überspringen, gegnerische nie","Es gewinnt nicht, wer am meisten schlägt, sondern wer zuerst alle Steine zu einer Gruppe verbindet"],"more":[{"h":"Zählen, dann ziehen","p":["Stehen zum Beispiel drei Steine auf der Reihe durch einen Stein, zieht dieser genau drei Felder entlang dieser Reihe – nicht mehr und nicht weniger. Eigene Steine darf er unterwegs überspringen; steht aber ein gegnerischer dazwischen, ist diese Richtung gesperrt.","Jeder Stein liegt auf vier Linien – einer Reihe, einer senkrechten Linie und zwei Diagonalen –, jede mit eigener Zahl. Zieht ein Stein, ändern sich die Zahlen mehrerer Linien um ihn herum; die „Entfernungen“ auf dem Brett werden mit jedem Zug neu gemischt. Genau das macht LOA so schwer durchschaubar."],"cap":["Wohin der schwarze Stein, an dem die Pfeile beginnen ziehen kann. Auf der Reihe stehen 3 Steine, also zieht er 3 (den eigenen Stein zu überspringen ist erlaubt); auf der Linie 2, also zieht er 2 und schlägt einen weißen Stein. Auf der Diagonale stehen ebenfalls 3, aber ein weißer Stein versperrt den Weg (×)"]},{"h":"Eine Gruppe gewinnt","p":["Steine gelten als verbunden, wenn sie sich waagerecht, senkrecht oder diagonal berühren. Wer nur noch einen Stein hat, ist ebenfalls „verbunden“ – zu viel Schlagen kann dem Gegner also sogar den Sieg schenken.","Was gilt, wenn ein Zug beide Seiten zugleich verbindet, hängt von Ausgabe und Turnier ab. Die erste Ausgabe von Sacksons Buch wertete es als Remis, eine spätere als Sieg für den Ziehenden, und die meisten heutigen Turniere werten es als Remis. Im LOA dieses Atlas gewinnt, wer gezogen hat."],"cap":["Eine Gewinnstellung. Die weißen Steine (goldener Rand) berühren sich, Diagonalen eingeschlossen, und bilden eine Gruppe. Schwarz ist noch in drei Teile zerfallen (gestrichelt)"]},{"h":"Ein Spiel, um das Computer kämpfen","p":["Kleines Brett, kurze Regeln, tiefes Spiel: LOA wurde zum Prüfstand der Spiele-KI. MIA, das Programm von Mark Winands an der Universität Maastricht, gewann die Computer-Olympiade 2003, 2004, 2006 und 2009; seine Arbeit fasste er 2004 in seiner Doktorarbeit Informed Search in Complex Games zusammen.","2008 löste Winands LOA auf einem verkleinerten 6 × 6-Brett und zeigte, dass bei perfektem Spiel der Anziehende (Schwarz) gewinnt. Das volle 8 × 8-Spiel gilt als noch ungelöst. Auch menschliche Spieler treffen sich – bei einer Weltmeisterschaft, die jedes Jahr auf der Mind Sports Olympiad ausgetragen wird."],"cap":[]}],"tl":[["um 1960","Claude Soucie soll LOA erfunden haben"],["1969","Vorgestellt in Sid Sacksons A Gamut of Games"],["2003","Winands’ MIA gewinnt die Computer-Olympiade (erneut 2004, 2006 und 2009)"],["2004","Winands’ Doktorarbeit Informed Search in Complex Games"],["2008","6 × 6-LOA ist gelöst: Sieg für den Anziehenden"]]},"konane":{"title":"Das Spiel aus schwarzer Lava und weißer Koralle","lead":"Kōnane, das Spiel der Menschen auf Hawaiʻi, steht im Bericht über Cooks Reise – und im 20. Jahrhundert nahmen Mathematiker es mit der kombinatorischen Spieltheorie auseinander.","s":["Kōnane ist ein Spiel für zwei der Hawaiianer. Schwarze und weiße Steine füllen das Brett abwechselnd und lückenlos, und man schlägt, indem man über gegnerische Steine springt.","Früher waren die schwarzen Steine aus Lava und die weißen Korallenstücke. Das Brett, papamū genannt, war ein großer flacher Stein mit eingepickten Mulden. Das Spiel soll sogar im Kumulipo vorkommen, dem hawaiischen Schöpfungsgesang.","Zuerst nimmt Schwarz einen eigenen Stein heraus, dann Weiß einen benachbarten. Die zwei Löcher, die so entstehen, sind der Ausgangspunkt der Sprünge.","Jeder Zug ist ein Schlag. Ein Stein springt waagerecht oder senkrecht über einen benachbarten gegnerischen Stein und landet auf dem freien Feld dahinter. Solange er geradeaus geht, darf er weiterspringen.","Wer keinen Schlag mehr hat, verliert; Remis gibt es nicht. Dieser schlichte Aufbau weckte später das Interesse von Mathematikern."],"quiz":[["Woraus waren die alten weißen Steine des Kōnane?","Aus Koralle","Aus Elfenbein","Aus weißem Marmor","Aus Knochen"],["Wer verliert beim Kōnane?","Wer keinen Schlag mehr hat","Wer alle Steine verloren hat","Wer zuerst den Rand erreicht","Wer nur noch einen Stein hat"],["Was ist bei Kettensprüngen nicht erlaubt?","Unterwegs die Richtung ändern","Mehr als einen Stein pro Zug schlagen","Mittendrin aufhören","Neben einem eigenen Stein landen"]],"kf":["Ein Spiel für zwei der Hawaiianer, das mit abwechselnd über das ganze Brett verteilten schwarzen (Lava) und weißen (Koralle) Steinen beginnt","Jeder Zug springt waagerecht oder senkrecht über einen gegnerischen Stein und schlägt ihn; geradeaus darf man weiterspringen","Wer keinen Schlag mehr hat, verliert; Mathematiker untersuchten das Spiel mit kombinatorischer Spieltheorie"],"more":[{"h":"Springen und schlagen","p":["Gesprungen wird nur waagerecht oder senkrecht, nie diagonal. Ist das Feld hinter einem benachbarten gegnerischen Stein frei, springt der Stein darüber, landet dort, und der übersprungene Stein wird vom Brett genommen.","Kann er vom Landefeld aus erneut springen, darf er in derselben Richtung weitermachen. Unterwegs die Richtung zu ändern ist verboten, aufhören darf er jederzeit. Pro Zug bewegt sich nur ein Stein."],"cap":["Ein weißer Stein springt in einem Zug zweimal nach rechts und schlägt zwei schwarze Steine (blau 1 und 2). Vom Landefeld aus darf er nicht abbiegen und nach unten springen (×)"]},{"h":"Die ersten zwei Löcher","p":["Auf einem randvollen Brett kann niemand springen. Darum nimmt Schwarz, das beginnt, einen eigenen Stein aus den vier Mittelfeldern oder einer Ecke. Dann nimmt Weiß einen eigenen Stein, der dieses Loch waagerecht oder senkrecht berührt.","Die beiden nebeneinanderliegenden Löcher sind die ersten Landeplätze. Wo man sie öffnet, prägt die ganze Partie."],"cap":["Die zwei Arten zu beginnen. Schwarz nimmt einen eigenen Stein aus den vier Mittelfeldern (links) oder einer Ecke (rechts) (1), dann nimmt Weiß einen benachbarten Stein (2)"]},{"h":"Steinbretter und 238 Felder","p":["Der Bericht über James Cooks dritte Reise (Band III, erschienen 1784) beschreibt ein auf Hawaiʻi gesehenes Steinspiel als „unserem Damespiel sehr ähnlich“, aber verwickelter. Geschrieben hat es der Offizier James King; das Brett sei etwa zwei Fuß lang gewesen, mit 238 Feldern, vierzehn in einer Reihe.","Eine feste Größe gab es nicht: Bretter von 6 × 7, 9 × 13, 13 × 20 und mehr sind bekannt. Heute spielt man meist auf einem quadratischen Brett mit gerader Seitenzahl, und dieser Atlas bietet 6 × 6, 8 × 8 und 10 × 10. Im Puʻuhonua o Hōnaunau National Historical Park auf der Insel Hawaiʻi sind noch in Stein gehauene papamū zu sehen."],"cap":["Brettgrößen im Vergleich: das 14 × 17-Brett (238 Felder) aus dem Bericht über Cooks Reise und die 10 × 10-, 8 × 8- und 6 × 6-Bretter dieses Atlas"]},{"h":"Ein Spiel, das die Mathematiker fanden","p":["Beim Kōnane verliert, wer nicht mehr ziehen kann, und gegen Ende zerfällt das Brett in unabhängige Teile – wie gemacht für die kombinatorische Spieltheorie von Elwyn Berlekamp und seinen Kollegen. Michael Ernst schrieb 1993 mit Berlekamp einen kurzen Aufsatz über Kōnane und berechnete in einem Artikel von 1995 die Werte vieler Stellungen.","Weitere Arbeiten folgten: Alice Chan und Alice Tsai untersuchten einreihiges Kōnane (2002), und Bob Hearn zeigte, dass auf immer größeren Brettern die Frage nach dem Sieger extrem schwer wird (PSPACE-vollständig). Ein Spiel springender Steine war zum Thema der Komplexitätstheorie geworden."],"cap":[]}],"tl":[["1778","Cooks Schiffe erreichen Hawaiʻi"],["1784","Der Bericht über Cooks dritte Reise erscheint, mit Kings Beschreibung des Steinspiels"],["1993","Ernst und Berlekamp schreiben einen kurzen Aufsatz über Kōnane"],["1995","Ernsts Artikel „Playing Konane Mathematically“"],["2002","Chan und Tsai fassen ihre Ergebnisse zum einreihigen Kōnane zusammen"]]},"peg":{"title":"Das Sprungrätsel vom Königshof","lead":"Solitär wurde Ende des 17. Jahrhunderts am französischen Hof Ludwigs XIV. gespielt. Ein schlichtes Rätsel, bei dem man Stifte einen nach dem anderen wegnimmt – und das seither Mathematiker fesselt.","s":["Solitär ist ein Rätsel für eine Person. Stifte füllen die Löcher des Bretts, nur ein Loch bleibt frei.","Ein Stift springt waagerecht oder senkrecht über einen Nachbarn in das freie Loch dahinter. Der übersprungene Stift wird vom Brett genommen.","Ziel ist es, so lange zu springen, bis nur ein Stift übrig ist. Bleibt er genau in der Mitte, ist das die perfekte Lösung.","Die ersten sicheren Zeugnisse stammen aus dem Frankreich des späten 17. Jahrhunderts, vom Hof Ludwigs XIV. 1697 druckte die Zeitschrift Mercure galant Brett und Regeln, und ein Kupferstich zeigt eine vornehme Dame mit einem Brett neben sich.","Es sieht leicht aus, ist aber schwer. Auch der Mathematiker Leibniz interessierte sich dafür, und im 20. Jahrhundert erklärten Mathematiker mit eingefärbten Löchern, warum manche Aufgaben unlösbar sind."],"quiz":[["Was geschieht mit einem übersprungenen Stift?","Er wird vom Brett genommen","Er gehört nun dem Gegner","Er rutscht ins Nachbarloch","Er kommt im nächsten Zug zurück"],["Wie viele Löcher hat das englische Brett?","33","37","45","64"],["Woher stammen die ersten sicheren Zeugnisse des Solitär?","Vom französischen Hof Ludwigs XIV., spätes 17. Jahrhundert","Aus den Thermen des alten Rom","Aus einer Tempelschule im Japan der Edo-Zeit","Aus einem Saloon im Amerika des 19. Jahrhunderts"]],"kf":["Ein Sprungrätsel für eine Person: Man überspringt Stifte, um sie zu entfernen, und gewinnt mit einem einzigen Rest","Sichere Zeugnisse beginnen um 1697 am Hof Ludwigs XIV.; die klassischen Bretter haben 33 (englisch) und 37 (europäisch) Löcher","Färbt man die Löcher in drei Farben, erkennt man im Voraus, welche Aufgaben unlösbar sind"],"more":[{"h":"Springen und wegnehmen","p":["Gesprungen wird nur waagerecht oder senkrecht, nie diagonal (außer auf Brettern mit Diagonallinien wie dem Dreieck). Jeder Sprung entfernt einen Stift; von 32 Stiften aus braucht es also 31 Sprünge bis zum letzten.","Derselbe Stift darf mehrmals hintereinander springen. Zählt man eine solche Kette als einen Zug, lässt sich die Aufgabe „von der Mitte zur Mitte“ auf dem englischen Brett in 18 Zügen lösen. Ernest Bergholt fand diese Lösung 1912, und John Beasley bewies 1964, dass es nicht kürzer geht."],"cap":["Der erste Zug auf dem englischen Brett. Bei freier Mitte springt der obere Stift über den darunter in die Mitte (blau); der übersprungene wird weggenommen (×)"]},{"h":"Ein höfischer Zeitvertreib","p":["Die gesicherte Geschichte des Solitär reicht an den Hof Ludwigs XIV. um 1697 zurück. Im August jenes Jahres beschrieb der Mercure galant Brett, Regeln und einige Aufgaben, und der Kupferstecher Claude-Auguste Berey stellte die Prinzessin von Soubise mit einem Brett an ihrer Seite dar.","Bekannt ist auch die Geschichte eines in der Bastille eingesperrten Adligen, der das Rätsel aus Langeweile erfunden haben soll – eine Legende, die sich nicht belegen lässt. Das in Frankreich gebräuchliche Brett mit 37 Löchern soll ebenfalls aus dem 17. Jahrhundert stammen; das Brett mit 33 Löchern und abgeschnittenen Ecken heißt englisches Brett."],"cap":["Die beiden klassischen Bretter: englisch mit 33 Löchern (links) und europäisch mit 37 (rechts). Das freie Loch ist jeweils der übliche Startplatz"]},{"h":"Was drei Farben verraten","p":["Färbt man die Löcher so in drei Farben, dass die Farben den Diagonalen folgen, haben drei aufeinanderfolgende Löcher in einer Reihe oder Spalte stets drei verschiedene Farben. Ein Sprung nimmt zwei Farben je einen Stift und gibt der dritten einen dazu – die Anzahlen aller drei Farben wechseln also gemeinsam zwischen gerade und ungerade.","Auf dem europäischen Brett mit freier Mitte hat jede Farbe 12 Stifte – alle gerade. Jeder Sprung wechselt nur zwischen „alle gerade“ und „alle ungerade“; die Stellung eines letzten Stifts – eine Farbe mit 1, die anderen mit 0 – ist so nie erreichbar. Auf diesem Brett ist die Aufgabe ab der Mitte unlösbar. Dieselbe Prüfung auf dem englischen Brett lässt, von der Mitte aus, nur fünf Löcher übrig, in denen der letzte Stift enden kann."],"cap":["Das europäische Brett mit 37 Löchern, entlang der Diagonalen in drei Farben eingefärbt. Bei freier Mitte hat jede Farbe 12 Stifte"]},{"h":"Ein Spielzeug für Mathematiker","p":["Leibniz soll 1710 in einer Notiz geschrieben haben, er spiele das Spiel gern rückwärts, indem er die übersprungenen Löcher wieder auffülle. Vom Ende her zurückzurechnen ist bis heute ein Grundweg zur Lösung.","Winning Ways (1982) von Berlekamp, Conway und Guy analysierte das Rätsel gründlich und stellte die „Pagodenfunktionen“ vor: Gibt man jedem Loch einen Wert, sodass kein Sprung die Summe erhöht, kann man beweisen, dass manche Ziele unerreichbar sind. 1999 soll eine Computersuche alle Stellungen durchgerechnet haben."],"cap":[]}],"tl":[["1697","Am Hof Ludwigs XIV. gespielt; der Mercure galant vom August druckt Brett und Regeln"],["1710","Leibniz soll über das Rückwärtsspielen schreiben"],["1912","Bergholt findet eine 18-Züge-Lösung auf dem englischen Brett"],["1964","Beasley beweist, dass es keine Lösung unter 18 Zügen gibt"],["1982","Winning Ways legt seine Analyse vor, samt Pagodenfunktionen"]]},"fanorona":{"title":"Schlagen durch Annähern, schlagen durch Zurückweichen","lead":"Fanorona ist Madagaskars Nationalspiel. Der Legende nach entschied es über einen Thron – und im 21. Jahrhundert zeigten Computer, dass es bei bestem Spiel remis endet.","s":["Fanorona ist ein in Madagaskar weit verbreitetes Spiel für zwei. Gespielt wird auf einem 9 × 5-Brett mit waagerechten, senkrechten und diagonalen Linien, mit 22 Steinen pro Seite.","Das Brett sieht aus wie zwei nebeneinandergelegte Alquerque-Bretter – ein Spiel der arabischen Welt und Europas. Man nimmt an, dass Alquerque auf die Insel kam und dort zu einem eigenen Spiel wurde.","Sein großes Merkmal ist das Schlagen. Wer auf einen gegnerischen Stein zuzieht („Annäherung“) oder von ihm wegzieht („Rückzug“), schlägt die ganze Reihe gegnerischer Steine auf dieser Linie.","Schlagen ist Pflicht, und ein Stein, der geschlagen hat, darf die Richtung wechseln und weiterschlagen. Ein einziger Zug kann das Brett völlig verändern – das ist der Reiz des Fanorona.","Seit Jahrhunderten beliebt, hat es sogar die Legende eines Prinzen, der einen Thron verlor, weil er von einer Partie nicht lassen konnte. 2007 zeigten niederländische Forscher mit Computern, dass das Spiel bei bestem Spiel beider Seiten remis ist."],"quiz":[["Wie groß ist das Fanorona-Brett?","9 × 5","8 × 8","7 × 7","6 × 6"],["Welches sind die zwei Arten zu schlagen im Fanorona?","Annäherung und Rückzug","Springen und Einklemmen","Umzingeln und Stoßen","Würfel und Los"],["Was zeigten Computer für bestes Spiel?","Remis","Sieg des Anziehenden","Sieg des Nachziehenden","Man weiß noch nichts"]],"kf":["Ein Spiel für zwei aus Madagaskar: je 22 Steine auf einem 9 × 5-Brett, zu Beginn ist nur die Mitte frei","Wer auf einen gegnerischen Stein zuzieht (Annäherung) oder von ihm wegzieht (Rückzug), schlägt die ganze Reihe auf dieser Linie","2007 zeigten Computer, dass das Spiel bei bestem Spiel remis ist"],"more":[{"h":"Annäherung und Rückzug","p":["Bei der Annäherung gilt: Steht direkt hinter dem Zielpunkt ein gegnerischer Stein, werden er und alle lückenlos dahinter aufgereihten gegnerischen Steine geschlagen. Der Rückzug ist das Gegenstück: Geschlagen werden der gegnerische Stein direkt hinter dem Startpunkt und die dahinter aufgereihten.","Weil ein einziger Schritt mehrere Steine auf einmal entfernt, schrumpfen die Heere von Anfang an rasch. Erlaubt ein Zug Annäherung und Rückzug zugleich, wählt der Spieler eines davon."],"cap":["Die zwei Schlagarten. Oben: Weiß zieht einen Schritt nach rechts auf einen schwarzen Stein zu und schlägt die drei Schwarzen in der Reihe dahinter (Annäherung). Unten: Weiß zieht nach rechts von einem Schwarzen weg und schlägt die zwei Schwarzen hinter sich (Rückzug)"]},{"h":"Zwei Alquerque-Bretter nebeneinander","p":["Das Brett hat 5 × 9 = 45 Punkte; neben den waagerechten und senkrechten Linien laufen Diagonalen durch jeden zweiten Punkt. Die Steine ziehen einen Schritt entlang einer Linie zu einem Nachbarpunkt. Anfangs ist nur die Mitte frei, deshalb ist der erste Zug immer ein Schlag.","Das Brett besteht aus zwei aneinandergesetzten 5 × 5-Alquerque-Brettern. Alquerque ist ein altes Spiel, das schon in einem arabischen Buch des 10. Jahrhunderts genannt wird, und Fanorona soll daraus entstanden sein. Wann und wie es auf die Insel kam, ist unklar; manche Bücher nennen das 17. Jahrhundert."],"cap":["Die Anfangsstellung: je 22 schwarze und weiße Steine auf den 9 × 5 Punkten, nur der Mittelpunkt ist frei. Die gestrichelten Quadrate markieren zwei 5 × 5-Alquerque-Bretter"]},{"h":"Schlagketten","p":["Ein Stein, der geschlagen hat, darf erneut schlagen. Jeder Schritt muss aber in eine andere Richtung gehen, und ein schon besuchter Punkt darf nicht wieder betreten werden. Ob man weitermacht, ist freigestellt.","Gelingt eine solche Kette, kann ein Zug fast die Hälfte der gegnerischen Steine kosten. Endet sie aber an einer schlechten Stelle, wird der Stein sofort zurückgeschlagen."],"cap":["Eine Schlagkette. Weiß (1) nähert sich nach rechts und schlägt zwei; (2) zieht sich nach oben zurück und schlägt zwei; (3) nähert sich nach links und schlägt zwei. Nach (1) darf er nicht weiter nach rechts (×)"]},{"h":"Ein Thron und die Computer","p":["Der Legende nach stellte sich Ralambo, ein König von Imerina um das 16. Jahrhundert, krank, damit der Sohn den Thron erbe, der zuerst heimkehrte. Der ältere, Andriantompokoindrindra, konnte sich nicht von einer schwierigen Fanorona-Stellung lösen, und der jüngere, Andrianjaka, wurde König. Einer anderen Geschichte zufolge verließ sich die Seite der Königin beim französischen Einmarsch 1895 auf eine rituelle Fanorona-Partie; keine der beiden Erzählungen lässt sich belegen.","2007 berechneten Maarten Schadd und Kollegen von der Universität Maastricht in den Niederlanden alle Stellungen mit sieben oder weniger Steinen und zeigten mit Beweiszahlsuche, dass die Anfangsstellung remis ist (der Aufsatz erschien 2008). Die Rechnung dauerte auf einem einzigen Rechner über eine Woche."],"cap":[]}],"tl":[["um 16. Jh.","Die Legende von König Ralambos Thronfolge und dem Fanorona"],["um 17. Jh.","Eine Ansicht, wann Fanorona aus Alquerque entstand"],["1895","Die Legende einer rituellen Fanorona-Partie beim französischen Einmarsch"],["2007","Schadd und Kollegen zeigen per Computer: remis"],["2008","Der Aufsatz „Best Play in Fanorona Leads to Draw“"]]},"janggi":{"title":"Ein Brett ohne Fluss und eine Kanone, die nur einmal springt","lead":"Janggi, in Korea sehr beliebt, nutzt dasselbe 9 × 10-Brett wie das chinesische Xiangqi – hat aber den Fluss abgeschafft und die Gangarten der Steine stark verändert.","s":["Janggi ist ein Schachspiel für zwei, das in Korea seit Langem gespielt wird. Es soll vom chinesischen Xiangqi abstammen; die Steine stehen auf den Punkten eines Gitters aus 9 × 10 Linien.","Anders als beim Xiangqi hat das Brett keinen „Fluss“ in der Mitte, sodass Elefanten und Soldaten überallhin können. Der General (König) beginnt in der Mitte seines „Palasts“ und darf ihn nie verlassen.","Die Parteien heißen Cho (blau oder grün) und Han (rot). Die Steine sind achteckig, und je stärker ein Stein, desto größer ist er. Cho beginnt.","Vor der Partie wählt jede Seite eine von vier Aufstellungen für Pferde und Elefanten. Han stellt zuerst auf, Cho entscheidet danach – das Taktieren beginnt also vor dem ersten Zug.","Neben dem Matt kann eine Partie auch nach Punkten entschieden werden. Cho, der beginnt, startet mit 72 Punkten; Han erhält einen „Deom“ von 1,5 und startet mit 73,5. Jeder verlorene Stein senkt die Punktzahl."],"quiz":[["Was fehlt dem Janggi-Brett?","Ein Fluss in der Mitte","Paläste","Diagonalen in den Palästen","90 Punkte"],["Was muss die Kanone immer tun, um zu ziehen?","Genau einen Stein überspringen","Neben einem gegnerischen Stein stehen","Im Palast stehen","Nicht im Schach stehen"],["Wie viel „Deom“ erhält Han, der Nachziehende, bei der Punktwertung?","1,5","0,5","3","6,5"]],"kf":["Koreas Schach, entstanden aus Xiangqi: ein 9 × 10-Brett, aber ohne Fluss","Der Elefant zieht einen Schritt gerade und zwei diagonal; die Kanone zieht und schlägt, indem sie genau einen Stein überspringt","Jede Seite wählt eine von vier Aufstellungen; bei der Punktwertung erhält Han einen Deom von 1,5"],"more":[{"h":"Ein Brett ohne Fluss und vier Aufstellungen","p":["Das Janggi-Brett hat dieselben 9 × 10 Punkte wie Xiangqi, aber keinen Fluss. Jeder Palast hat Diagonalen in X-Form, und General und Wächter ziehen darin Schritt für Schritt, auch entlang der Diagonalen. Der General beginnt genau in der Palastmitte.","Es gibt vier Aufstellungen, die durch Vertauschen von Pferden und Elefanten entstehen. Han stellt zuerst auf, Cho wählt, nachdem er sie gesehen hat. Ob die Elefanten innen oder außen stehen, ändert die Angriffswege der Eröffnung."],"cap":["Das Janggi-Brett und die Anfangsstellung. Es gibt keinen Fluss; die Paläste oben und unten haben Diagonalen. Die gestrichelten Ringe zeigen, wo Pferde und Elefanten getauscht werden können; Han (oben) und Cho (unten) haben verschiedene Aufstellungen gewählt"]},{"h":"Pferd, Elefant und gesperrte Punkte","p":["Das Pferd zieht zuerst einen Punkt geradeaus und dann einen diagonal nach außen. Der Elefant geht weiter: einen Punkt gerade, dann zwei diagonal. Bei beiden sperrt ein Stein auf einem Punkt des Weges diese Richtung.","Der Xiangqi-Elefant darf den Fluss nicht überqueren und zieht nur zwei Punkte diagonal; der Janggi-Elefant dagegen hat lange Beine und kann übers ganze Brett. Dafür wird sein Weg leicht versperrt."],"cap":["Das Pferd (links) zieht einen Schritt gerade und einen diagonal, der Elefant (rechts) einen gerade und zwei diagonal. Blaue Punkte zeigen die Ziele. Ein Stein auf einem Punkt des Weges sperrt diese Richtung (×)"]},{"h":"Die Kanone, die nur einmal springt","p":["Die Kanone muss beim Ziehen wie beim Schlagen genau einen Stein dazwischen überspringen. Ist nichts dazwischen, kann sie sich nicht bewegen – in der Anfangsstellung stehen die Kanonen still.","Weder der übersprungene noch der geschlagene Stein darf eine Kanone sein; zwei Kanonen können sich also nur anstarren. Verglichen mit der Xiangqi-Kanone, die ohne Schlag frei zieht, ist sie ein viel eigenwilligerer Stein."],"cap":["Die Kanone. Oben: Sie überspringt genau einen Soldaten und zieht auf einen Punkt dahinter oder schlägt den Wagen (blau). Mitte: Ist der Stein dazwischen eine Kanone, kann sie nicht springen. Unten: Eine Kanone kann keine Kanone schlagen (×)"]},{"h":"Generäle Auge in Auge und Punkte","p":["Stehen sich die beiden Generäle auf einer freien Linie gegenüber, heißt das „Bikjang“. Nach einer Regel endet die Partie remis, wenn die so gestellte Seite das nicht auflöst. Die traditionellen Regeln erlauben außerdem, einen Zug auszusetzen, wenn man nicht im Schach steht.","Die Werte: Wagen 13, Kanone 7, Pferd 5, Elefant 3, Wächter 3, Soldat 2. Cho kommt auf 72 Punkte, Han mit dem Deom auf 73,5. Wegen des halben Punkts gibt es nie Punktgleichheit. Im Janggi dieses Atlas entscheiden diese Punkte, wenn sich eine Stellung dreimal wiederholt oder nach 200 Zügen."],"cap":[]}],"tl":[["Goryeo-Zeit","Nach einer Ansicht wurde es schon gespielt (die Ankunft ist umstritten)"],["18. Jh.","Eine größere Variante, Gwangsanghui, soll überliefert sein"],["1895","Stewart Culins Korean Games zeigt ein Bild von Männern beim Janggi"],["2009","Das erste internationale Turnier soll in Harbin, China, stattgefunden haben"]]},"pic":{"tlvmirror":"TLV-Spiegel (Östliche Han, Cleveland Museum of Art)","kotoboard":"Die vier Künste (Edo-Zeit, um 1620–50, Cleveland Museum of Art)","homerbg":"Winslow Homer, Backgammon (Holzstich, um 1877, Cleveland Museum of Art)","trictrac":"Philips de Koninck, Die Trictrac-Spieler (Zeichnung, um 1660, Cleveland Museum of Art)","gametable":"Spieltisch mit Schach- und Mühlebrett (Mainz, um 1735, Cleveland Museum of Art)","kota":"Der Herrscher von Kota verehrt Krishna; auf den Stufen ein kreuzförmiges Chaupar-Tuch (um 1825, Cleveland Museum of Art)"},"mahjong":{"game":"Mahjong","title":"Das Steinspiel, das nach einem Spatz heißt","lead":"Mahjong entstand im China des 19. Jahrhunderts. Aus einem Kartenspiel wurde ein Steinspiel, das im Amerika der 1920er eine Mode auslöste und in Japan zum Riichi-Mahjong wurde.","s":["Mahjong ist ein Steinspiel für vier. Es hat 136 Steine (144 mit den Blumen), und wer zuerst eine Hand einer bestimmten Form vollendet, gewinnt.","Es entstand im China des 19. Jahrhunderts. Seine Wurzeln sind „Ziehen und Abwerfen“-Spiele mit Karten, die Geldeinheiten zeigten; vermutlich wurden die Papierkarten um die Mitte des Jahrhunderts zu Steinen.","Die ältesten erhaltenen Steine stammen von etwa 1870 und wurden in Ningbo, Shanghai und Fuzhou erworben. Manche Bücher lassen das Spiel in Ningbo entstehen, andere sehen darin einen Zeitvertreib von Fischern aus Fujian und Guangdong.","„Máquè“ heißt Spatz, und eine Theorie leitet den Namen von einem älteren Kartenspiel ab, dem Madiao. Die oft erzählte Geschichte, Konfuzius habe es erfunden, entbehrt jeder Grundlage.","Im 20. Jahrhundert überquerte Mahjong die Meere. Im Amerika der 1920er wurde es zur Mode, und in Japan machte es die später eingeführte „Riichi“-Regel zu einem eigenen Spiel."],"quiz":[["Wie viele Steine hat Mahjong ohne Blumen?","136","144","108","152"],["Was ist die Grundform einer Gewinnhand?","Vier Gruppen und ein Paar","Nur sieben Gruppen","Dreizehn gleiche Steine","Drei Gruppen und zwei Paare"],["In welchem Land wurde Mahjong in den 1920ern zur Mode?","USA","Russland","Brasilien","Ägypten"]],"kf":["Ein Steinspiel für vier, im China des 19. Jahrhunderts aus Kartenspielen entstanden","Zahlensteine in Zeichen, Kreisen und Bambus, dazu Winde und Drachen; man gewinnt mit vier Gruppen und einem Paar","Eine Mode im Amerika der 1920er; im Nachkriegsjapan wuchs das Riichi-Mahjong"],"more":[{"h":"136 Steine","p":["Die Zahlensteine bilden drei Farben — Zeichen, Kreise und Bambus —, jede von 1 bis 9 in vier Exemplaren: 108 Steine. Dazu kommen je vier Ost-, Süd-, West- und Nordwinde sowie weiße, grüne und rote Drachen — zusammen 136.","Viele chinesische Spielweisen nutzen außerdem acht Blumensteine: Pflaume, Orchidee, Chrysantheme und Bambus sowie die vier Jahreszeiten. Sie gehören nicht zur Hand; gezogen, werden sie beiseitegelegt und bringen Punkte. Japanisches Mahjong lässt sie meist weg."],"cap":["Die Arten von Steinen. Zeichen, Kreise und Bambus von 1 bis 9, die Winde (Ost, Süd, West, Nord) und die Drachen (weiß, grün, rot), je vier: 136. Mit den acht Blumen unter der gepunkteten Linie (je eine): 144"]},{"h":"Vier Gruppen und ein Paar","p":["Eine Hand hat 13 Steine; man zieht einen und wirft einen ab, immer wieder. Vollendet ein gezogener Stein, oder einer, den ein anderer abwirft, vier Gruppen und ein Paar, gewinnt die Hand.","Die Gruppen sind der Chow (drei Zahlen in Folge einer Farbe), der Pung (drei gleiche Steine) und der Kong (vier gleiche). Man kann sie auch bilden, indem man den Abwurf eines anderen beansprucht — die Partie ist ein langes Ringen darum, was man nimmt und was man ziehen lässt."],"cap":["Die Grundform einer Gewinnhand: vier Gruppen — Chow (drei in Folge einer Farbe), Pung (drei gleiche) oder Kong (vier gleiche) — und ein Paar"]},{"h":"Mahjong überquert die Meere","p":["1920 veröffentlichte Joseph Park Babcock ein Regelbuch auf Englisch, und ein New Yorker Geschäft begann, Spiele aus China einzuführen. Im Amerika der 1920er wurde Mahjong zur Mode, und die 1937 gegründete National Mah Jongg League pflegt bis heute eine amerikanische Spielweise.","Nach Japan kam es in den 1920ern; 1924 soll Saburo Hirayama in Tokio einen Spielsalon und eine Schule eröffnet haben, und 1929 wurde die Japanische Mahjong-Liga mit dem Schriftsteller Kan Kikuchi an der Spitze gegründet. 1952, nach dem Krieg, soll Daizō Amano in einer Zeitung Regeln mit „Riichi“ veröffentlicht haben – der Beginn des japanischen Riichi-Mahjong."],"cap":["Wie sich Mahjong verbreitete: von China in die USA und nach Japan in den 1920ern; Riichi-Regeln in Japan 1952 und offizielle chinesische Regeln 1998"]},{"h":"Legenden und wirkliche Geschichte","p":["Um die Herkunft des Mahjong ranken sich viele Legenden. Dass Konfuzius es erfand, ist ohne Grundlage. Auch die Erzählung von einem Mann namens Chen Yumen aus Ningbo, der es erfunden habe, ist wohl erfunden, denn die Papiere, aus denen sie stammen soll, wurden nie gefunden.","Sicher ist, dass chinesische Zieh-und-Abwurf-Spiele des 19. Jahrhunderts mit Geldkarten zu einem Steinspiel wurden. Die frühen Sätze hatten weder Blumen noch den grünen Drachen, dafür „König“-Steine und andere. 1998 legte China zudem offizielle nationale Regeln fest."],"cap":[]}],"tl":[["Mitte 19. Jh.","Kartenspiele werden wohl zu einem Steinspiel"],["um 1870","Die ältesten erhaltenen Sätze (Ningbo, Shanghai, Fuzhou)"],["1920","Babcock veröffentlicht ein englisches Regelbuch"],["1929","Gründung der Japanischen Mahjong-Liga"],["1952","Die „Hochi-Regeln“ mit Riichi erscheinen"],["1998","China legt offizielle nationale Regeln fest"]],"figL":{"hand":["Chow","Pung","Kong","Chow","Paar"],"spread":[["um 1870","Ningbo, Shanghai","Älteste erhaltene Steine"],["1920","USA","Babcocks Regeln, eine Mode"],["1920er","Japan","Ankunft; Liga 1929"],["1952","Japan","Riichi-Regeln"],["1998","China","Offizielle Regeln, 81 Muster"]]}},"gomoku":{"title":"Gomoku: als der Anziehende zu stark war","lead":"Gomoku, gespielt mit Go-Brett und Go-Steinen, ist in Japan seit der Edo-Zeit beliebt. Um den Vorteil des Anziehenden zu bremsen, entstanden die Regeln des „Renju“ – und am Ende lieferten Computer die Antwort.","s":["Gomoku ist ein Spiel für zwei mit Go-Brett und Steinen. Schwarz und Weiß setzen abwechselnd, und wer zuerst fünf eigene Steine in eine Reihe bringt – waagerecht, senkrecht oder diagonal –, gewinnt.","Sein Ursprung ist unklar. Manche führen es auf das alte China oder das Japan der Heian-Zeit zurück, doch sichere Belege stammen aus der Edo-Zeit; gespielt worden sein soll es schon um die Mitte des 18. Jahrhunderts.","Je mehr gespielt wurde, desto klarer zeigte sich, dass Schwarz als Anziehender im Vorteil war. Deshalb entstanden in Japan nach und nach Regeln, die nur Schwarz „verbotene Züge“ auferlegen.","1899 gab Ruikō Kuroiwa von der Zeitung Yorozu chōhō dem Spiel den Namen „Renju“ – „aufgereihte Perlen“.","1988 wurde in Stockholm die Internationale Renju-Föderation (RIF) gegründet, und es gibt Weltmeisterschaften. Computer wiederum zeigten, dass Gomoku ohne verbotene Züge ein Sieg für den Anziehenden ist."],"quiz":[["Wie gewinnt man Gomoku?","Fünf eigene Steine in eine Reihe bringen","Steine umzingeln und schlagen","Mehr als die Hälfte des Bretts besetzen","Fünf gegnerische Steine schlagen"],["Wer gab dem Spiel den Namen „Renju“?","Ruikō Kuroiwa","Honinbō Dōsaku","Natsume Sōseki","Fukuzawa Yukichi"],["Welche Züge sind beim Renju nur Schwarz verboten?","Doppeldrei, Doppelvier und Überlänge","Am Brettrand setzen","Neben einen weißen Stein setzen","Gegnerische Steine umzingeln"]],"kf":["Ein Spiel mit Go-Brett und Steinen: fünf in einer Reihe gewinnen; sichere Belege beginnen in der Edo-Zeit","Weil Schwarz als Anziehender im Vorteil ist, verbietet Renju Schwarz Doppeldrei, Doppelvier und Überlänge","1994 wurde bewiesen, dass freies Gomoku auf 15 × 15 ein Sieg für den Anziehenden ist"],"more":[{"h":"Fünf in einer Reihe und die Vier-Drei","p":["Entschieden wird durch eine Doppeldrohung, die der Gegner nicht mit einem Zug abwehren kann. Eine „Vier“ – einen Stein vor fünf – muss sofort blockiert werden, sonst ist die Partie verloren. Eine an beiden Enden offene „Drei“ wird, wenn man sie übersieht, zur offenen Vier und ist nicht mehr zu stoppen.","Ein Zug, der zugleich eine Vier und eine Drei bildet – eine „Vier-Drei“ –, zwingt Weiß, die Vier zu schließen; danach wächst die Drei und gewinnt. Besser werden im Gomoku heißt, diese Form immer früher kommen zu sehen."],"cap":["Links: fünf in einer Diagonale gewinnen. Rechts: Der Stein im roten Ring schafft zugleich eine „Vier“ waagerecht (bei 4 gesetzt ergibt fünf) und eine offene „Drei“ senkrecht (die Punkte 3) – Weiß kann nicht beides abwehren (Vier-Drei)"]},{"h":"Verbotene Züge nur für Schwarz","p":["Im Renju darf Schwarz weder Doppeldrei noch Doppelvier noch Überlänge (sechs oder mehr in einer Reihe) spielen; tut er es, ist das ein Fehler und er verliert. Weiß hat keine verbotenen Züge, und sogar sechs oder mehr in einer Reihe bringen Weiß den Sieg.","Um zu gewinnen, muss Schwarz Formen wie die Vier-Drei bauen, die nicht verboten sind. Weiß kann Schwarz sogar absichtlich in einen verbotenen Zug treiben – ein Kräftemessen, das dem Renju seine Tiefe gibt."],"cap":["Für Schwarz verbotene Züge im Renju (×). Von links: die „Doppeldrei“ (zwei Dreier auf einmal), die „Doppelvier“ (zwei Vierer auf einmal) und die „Überlänge“ (sechs oder mehr)"]},{"h":"Gomoku gelöst","p":["1994 bewies der Niederländer Victor Allis per Computer, dass beim freien Gomoku auf einem 15 × 15-Brett der Anziehende, Schwarz, immer gewinnen kann. 2001 zeigten Wágner und Virág, dass auch Renju ohne Eröffnungsregeln ein Sieg für den Anziehenden ist.","Gespielt wird trotzdem, weil die Gewinnwege viel zu komplex sind, um sie auswendig zu lernen. Turniere nutzen „Eröffnungsregeln“, die festlegen, wie die ersten Züge gespielt werden – etwa Yamaguchi oder Soosõrv-8 –, damit der Wettkampf fair bleibt."],"cap":["Die Geschichte von Gomoku und Renju: vom Gomoku der Edo-Zeit über den Namen Renju und die internationale Föderation bis zu den Computerbeweisen"]},{"h":"Fünf in einer Reihe weltweit","p":["Im 19. Jahrhundert kam das Spiel als „Go Bang“ nach Großbritannien. Heute werden ähnliche Spiele überall gespielt: Koreas Omok, Vietnams Caro und Pente, bei dem man Steine paarweise schlägt.","Das Gomoku dieses Atlas wird auf einem 15 × 15-Brett gespielt, mit drei Regeln zur Wahl: Renju, Standard und frei. Vergleichen Sie sie und sehen Sie, wie stark die verbotenen Züge des Renju den Anziehenden bremsen."],"cap":[]}],"tl":[["Mitte 18. Jh.","Im Japan der Edo-Zeit soll Gomoku gespielt werden"],["1856","Das älteste erhaltene Gomoku-Buch, das Gomoku Jōseki"],["1899","Ruikō Kuroiwa nennt das Spiel Renju"],["1988","Gründung der Internationalen Renju-Föderation in Stockholm"],["1994","Allis beweist: freies Gomoku gewinnt der Anziehende"],["2001","Wágner und Virág zeigen: Renju ohne Eröffnungsregeln gewinnt der Anziehende"]],"figL":{"time":[["1700er","Japan (Edo)","Gomoku wird gespielt"],["1899","Japan","Name „Renju“"],["1988","Stockholm","Die RIF entsteht"],["1994","Niederlande","Gomoku: Anziehender siegt"],["2001","Ungarn","Renju: Schwarz siegt"]]}},"carrom":{"title":"Carrom: ein Fingerschnipp bis ins Loch","lead":"In Indien und Südasien treffen sich Familien und Nachbarn zum Carrom. Mit dem Finger geschnippte Steine landen in den Taschen an den vier Ecken des Bretts – ein Spiel ähnlich wie Billard.","s":["Carrom wird auf einem glatten Brett von etwa 74 Zentimetern Seitenlänge gespielt. In jeder Ecke ist eine Tasche; zwei spielen einander gegenüber, vier in Zweierteams.","Es gibt 19 Steine: 9 weiße, 9 schwarze und eine rote „Königin“. Wer am Zug ist, legt den größeren, schwereren „Striker“ auf die Linie vor sich – die Grundlinie – und schnippt ihn mit dem Finger gegen die Steine.","Wer alle Steine seiner Farbe einlocht, gewinnt. Die rote Königin gehört einem aber nur, wenn man nach ihr gleich einen eigenen Stein einlocht und sie so „deckt“.","Carrom soll aus Indien stammen; in einem Palast in Patiala in Nordindien ist noch ein Brett mit Glasoberfläche ausgestellt. Anfang des 20. Jahrhunderts gab es in Indien bereits Turniere auf Bundesstaatsebene.","1988 wurde im indischen Chennai die Internationale Carrom-Föderation gegründet, und seit 1991 gibt es Weltmeisterschaften. Ähnliche Schnippspiele gibt es überall, vom kanadischen Crokinole bis zum lettischen Novuss."],"quiz":[["Wie viele Steine hat Carrom ohne den Striker?","19","16","24","32"],["Wie gehört einem die rote Königin?","Indem man gleich danach einen eigenen Stein einlocht (decken)","Indem man sie zuletzt einlocht","Indem man sie beim ersten Stoß einlocht","Indem man sie zweimal hintereinander trifft"],["In welcher Stadt wurde 1988 die Internationale Carrom-Föderation gegründet?","Chennai","London","Colombo","Mumbai"]],"kf":["Ein Brett mit Taschen in den Ecken: Mit dem Finger geschnippt, locht der Striker die Steine ein","9 weiße, 9 schwarze und eine rote Königin; die Königin muss mit einem eigenen Stein „gedeckt“ werden","Soll aus Indien stammen; Internationale Föderation 1988, Weltmeisterschaften seit 1991"],"more":[{"h":"Das Brett und seine 19 Steine","p":["Jede Ecke des Bretts hat eine Tasche mit Netz, und an jeder Seite verläuft eine doppelte Grundlinie. Der Striker wird so gelegt, dass er beide Linien berührt, und von dort geschnippt.","Zu Beginn liegt die Königin in der Brettmitte, die weißen und schwarzen Steine bilden um sie eine Blüte. Der erste Stoß, der die Blüte sprengt, ist der „Break“, mit dem die Partie beginnt."],"cap":["Das Carrom-Brett und die Anfangsstellung. Die rote Königin in der Mitte, die weißen und schwarzen Steine wie eine Blüte darum. Taschen in den Ecken, eine doppelte Grundlinie an jeder Seite; der Striker (blauer Ring) liegt auf der nahen Grundlinie"]},{"h":"Schnippen und abprallen","p":["Den Striker schnippt man meist mit dem Fingernagel; manche nehmen den Mittelfinger, den Zeigefinger oder den Daumen. Wer einen eigenen Stein einlocht, darf weiterspielen; sonst ist der Gegner dran.","Die Banden federn gut, darum nutzt man Abpraller wie beim Billard. Den Striker selbst einzulochen ist ein Foul und wird bestraft."],"cap":["Der Striker wird geschnippt (blau), prallt an der rechten Bande ab und trifft einen weißen Stein, der in die Tasche oben rechts läuft (rot). Einen Stein, den man nicht direkt anvisieren kann, erreicht man über die Bande"]},{"h":"Eine Familie der Schnippspiele","p":["Schnippspiele wie Carrom gibt es auf der ganzen Welt. Das kanadische Crokinole zielt auf ein Loch in der Mitte eines runden Bretts, und auch Pichenotte wird in Kanada seit Langem gespielt. Carrom selbst soll im späten 19. Jahrhundert mit aus Asien heimkehrenden Missionaren nach Nordamerika gekommen sein.","Novuss aus Lettland und Estland soll in den 1920ern entstanden sein; gespielt wird mit einem kleinen Queue statt mit dem Finger. Es wurde zu einer der beliebtesten Sportarten Lettlands, und seit 1993 gibt es internationale Meisterschaften."],"cap":["Verwandte des Carrom, gespielt mit dem Finger oder einem Queue: Crokinole und Pichenotte aus Kanada, Novuss aus Lettland und Estland, Couronne aus Skandinavien"]},{"h":"Punkte und Weltmeisterschaften","p":["Nach den internationalen Regeln bringt das Decken der Königin 3 Punkte, und wer zuerst 25 Punkte hat, gewinnt. In Familien gibt es viele örtliche Varianten, etwa eine Königin, die 5 Punkte zählt.","Ernsthafte Turniere soll es in Sri Lanka ab etwa 1935 gegeben haben, und 1958 hatten Indien und Sri Lanka offizielle Verbände. Die Internationale Carrom-Föderation (ICF) wurde 1988 in Chennai gegründet, und Weltmeisterschaften finden seit 1991 statt."],"cap":[]}],"tl":[["frühes 20. Jh.","Bundesstaatsturniere in Indien"],["um 1935","In Sri Lanka sollen ernsthafte Turniere beginnen"],["1958","Indien und Sri Lanka haben offizielle Verbände"],["1988","Gründung der Internationalen Carrom-Föderation in Chennai"],["1991","Erste Carrom-Weltmeisterschaft"]],"figL":{"family":[["Carrom","Indien · Südasien"],["Crokinole","Kanada"],["Pichenotte","Kanada"],["Novuss","Lettland · Estland"],["Couronne","Schweden · Dänemark"]]}},"crokinole":{"title":"Ziel: das Loch in der Mitte","lead":"Crokinole ist im ländlichen Kanada sehr beliebt. Mit dem Finger schnippt man Scheiben über ein rundes Holzbrett und zielt auf das kleine Loch in der Mitte. Das älteste bekannte Brett stammt von 1876.","s":["Crokinole wird auf einem runden Holzbrett von etwa 66 Zentimetern Durchmesser gespielt. Zwei sitzen sich gegenüber, oder vier spielen in Paaren und schnippen ihre Scheiben zur Mitte.","Auf dem Brett sind Kreise markiert: von außen Ringe für 5, 10 und 15 Punkte, in der Mitte ein kleines Loch für 20. Acht Holzpflöcke umgeben den 15er-Ring und versperren den geraden Weg.","Einfach auf die Mitte zielen genügt nicht. Liegt eine gegnerische Scheibe auf dem Brett, muss der eigene Schuss eine treffen; sonst wird die eigene Scheibe entfernt.","Das älteste bekannte Brett fertigte 1876 der Handwerker Eckhardt Wettlaufer in Ontario, Kanada – angeblich als Geschenk zum fünften Geburtstag seines Sohnes. Heute steht es in einem Museum in Kitchener.","Der Name kommt vermutlich vom französischen „croquignole“, einem Fingerschnipp. Seit 1999 findet jeden Juni in Tavistock, wo Wettlaufer lebte, eine Weltmeisterschaft statt."],"quiz":[["Wie viele Punkte zählt das Loch in der Mitte des Crokinole-Bretts?","20","15","10","50"],["Liegt eine gegnerische Scheibe auf dem Brett – was muss der eigene Schuss tun?","Eine gegnerische Scheibe treffen","Ins Loch in der Mitte gehen","Das Brett verlassen","Einen Pflock treffen"],["Wann und wo entstand das älteste bekannte Crokinole-Brett?","Kanada, 1876","Frankreich, 1776","USA, 1926","England, 1676"]],"kf":["Ein rundes Holzbrett: Scheiben werden auf die 5er-, 10er- und 15er-Ringe und das 20er-Loch in der Mitte geschnippt","Liegt eine gegnerische Scheibe auf dem Brett, muss man sie treffen; sonst wird die eigene Scheibe entfernt","Das älteste Brett: Ontario (Kanada), 1876; Weltmeisterschaft seit 1999"],"more":[{"h":"Ringe, Pflöcke und Graben","p":["Geschossen wird vom äußersten 5er-Ring aus, im eigenen Viertel. Außerhalb des Rands verläuft ein Graben, in dem herabgefallene oder entfernte Scheiben landen.","Eine Scheibe, die ins 20er-Loch fällt, wird sofort herausgenommen und zählt 20. Am Ende zählen die liegen gebliebenen Scheiben je nach Ring 5, 10 oder 15, und meist wird nur der Unterschied zwischen beiden Seiten gewertet."],"cap":["Das Crokinole-Brett: von außen Ringe für 5, 10 und 15 und das 20er-Loch in der Mitte. Acht Pflöcke bewachen den 15er-Ring, ein Graben ringsum fängt entfernte Scheiben auf"]},{"h":"Treffen – oder entfernt werden","p":["Liegt auch nur eine gegnerische Scheibe auf dem Brett, muss der eigene Schuss eine gegnerische Scheibe treffen, direkt oder über eine andere. Sonst werden die geschossene Scheibe und alle dabei bewegten eigenen Scheiben entfernt.","Liegt keine gegnerische Scheibe auf dem Brett, verlangen viele Regelwerke, dass die geschossene Scheibe im 15er-Ring oder auf seiner Linie liegen bleibt. So kann sich niemand einfach verstecken, und das Spiel wird zum Duell aus Angriff und Abwehr."],"cap":["Die Schussregel. Links: Liegt eine gegnerische (schwarze) Scheibe auf dem Brett, genügt es, sie mit der eigenen (roten) zu treffen (✓). Rechts: Verfehlt man sie, wird die eigene Scheibe entfernt (×)"]},{"h":"Von einem Brett in Ontario zur Weltmeisterschaft","p":["Die erste kanadische Erwähnung soll auf 1867 zurückgehen, und in den USA patentierte Joshua K. Ingalls 1880 ein ähnliches Spiel. Auch Verbindungen zu Schnippspielen aus Großbritannien und Südasien wie Carrom wurden vermutet.","Manchmal heißt es, es sei ein Spiel der Mennoniten oder Amischen; das gilt jedoch als unbelegter Irrtum. Russlandmennoniten sollen es allerdings lange unter dem Namen „Knipsbrat“ gespielt haben."],"cap":["Crokinole im Lauf der Zeit: von der ersten kanadischen Erwähnung über Wettlaufers Brett und ein US-Patent bis zur Weltmeisterschaft in Tavistock"]},{"h":"Meisterschaften und Spiel","p":["Die Weltmeisterschaft findet seit 1999 jeweils am ersten Samstag im Juni in Tavistock statt. 2009 wurde ein internationaler Verband gegründet, und es gibt Klubs in ganz Nordamerika und Europa.","Das Crokinole dieses Atlas gibt es nur in 3D, mit mehreren Brettoptiken zur Wahl. Probieren Sie den Fingerschnipp wie beim Carrom und das Zielen auf Ringe wie beim Darts."],"cap":[]}],"tl":[["1867","Die erste kanadische Erwähnung soll aus diesem Jahr stammen"],["1876","Wettlaufer baut ein Brett für seinen Sohn"],["1880","In den USA patentiert Ingalls ein ähnliches Spiel"],["1999","Die Weltmeisterschaft in Tavistock beginnt"],["2009","Ein internationaler Verband wird gegründet"]],"figL":{"time":[["1867","Kanada","Erste Erwähnung"],["1876","Ontario","Das älteste Brett"],["1880","USA","Ingalls’ Patent"],["1999","Tavistock","Beginn der WM"],["2009","International","Internationaler Verband"]]}},"ugolki":{"title":"Springen, springen, bis in die Ecke gegenüber","lead":"Das russische Ugolki, das amerikanische Halma und „Chinese Checkers“ auf dem Sternbrett sind eine Familie: Es wird nichts geschlagen, man springt über Steine, bis beide Heere die Ecken getauscht haben.","s":["Ugolki heißt auf Russisch „Ecken“. Weiß und Schwarz stellen ihre Steine als Block in gegenüberliegende Ecken eines 8×8-Bretts, und wer zuerst alle Steine in die Ecke des anderen bringt, gewinnt.","Ein Zug ist entweder ein Schritt auf ein leeres Nachbarfeld oder ein Sprung über einen benachbarten Stein auf das leere Feld direkt dahinter. Man darf eigene wie fremde Steine überspringen und weiterspringen, solange es geht. Geschlagen wird nichts: Übersprungene Steine bleiben auf dem Brett.","Das bekannteste Spiel dieser Art ist das amerikanische Halma. Es soll um 1883–84 von dem Chirurgen George Howard Monks erdacht worden sein, nach einigen Ideen aus einem englischen Spiel namens Hoppity. Der Name kommt vom griechischen Wort für „Sprung“.","1892 erschien in Deutschland eine Fassung auf einem Sternbrett, das „Stern-Halma“. 1928 verkaufte die amerikanische Firma Pressman es als „Chinese Checkers“ („chinesische Dame“), und es wurde ein Riesenerfolg – doch mit China hat das Spiel nichts zu tun.","Wann Ugolki entstand, weiß niemand genau. Einer Darstellung zufolge wurde es Ende des 18. Jahrhunderts in Europa erfunden, doch ein sicherer Beleg fehlt. Heute spielen es Kinder und Erwachsene in Russland und den Ländern der früheren Sowjetunion."],"quiz":[["Was geschieht beim Ugolki mit einem übersprungenen Stein?","Er bleibt auf dem Brett","Er wird entfernt","Er wechselt die Farbe","Er kehrt in seine Ecke zurück"],["Wann wurde das Spiel zuerst als „Chinese Checkers“ verkauft?","1928 in den USA","1892 in China","im 18. Jahrhundert im China der Qing","in den 1950er-Jahren in Japan"],["Wer soll Halma erfunden haben?","Monks, ein amerikanischer Chirurg","eine deutsche Spielzeugfirma","ein russischer Mathematiker","ein chinesischer Kaiser"]],"kf":["Von Ecke zu Ecke auf einem 8×8-Brett: Wer zuerst alle Steine hinüberbringt, gewinnt. Geschlagen wird nichts","Ein Schritt oder ein Sprung über einen Nachbarstein – eigenen oder fremden –, und man darf weiterspringen","Halma (USA, um 1883–84) → Stern-Halma (Deutschland, 1892) → „Chinese Checkers“ (1928). Gar nicht chinesisch"],"more":[{"h":"Springend voran","p":["Beim Springen ist es gleich, wem der Stein gehört. Stellen Sie Ihre Steine als „Leiter“ auf, nutzen Sie auch die des Gegners als Trittsteine, und ein einziger Zug kann das halbe Brett überqueren.","Springen ist nie Pflicht, und man darf mittendrin aufhören. Schritt und Sprung lassen sich aber nicht in einem Zug verbinden."],"cap":["Eine Sprungkette: Der weiße Stein springt nacheinander über einen schwarzen, einen weißen, einen schwarzen und einen weißen Stein, vier Sprünge in einem Zug (1–4). Jeder übersprungene Stein bleibt auf dem Brett"]},{"h":"Brett und Lager beim Ugolki","p":["Die Lager gibt es in mehreren Größen: 3×3 (9 Steine), 3×4 (12) und 4×4 (16). Nach den klassischen Regeln ziehen die Steine nur gerade, entlang Reihen und Spalten; eine Variante erlaubt auch die Diagonale.","Wer einfach im eigenen Lager sitzen bleibt, verhindert, dass der Gegner es füllen kann. Daher sagt eine in Russland verbreitete Regel: Wer nach dem 40. Zug noch einen Stein im eigenen Lager hat, verliert. Ist nach 80 Zügen nichts entschieden, zählt die Zahl der Steine im gegnerischen Lager."],"cap":["Das Ugolki-Brett: Weiß beginnt im 3×4-Lager unten links (a1–d3), Schwarz oben rechts (e6–h8), und jede Seite zieht zur Ecke der anderen (Pfeile). Die Lager können auch 3×3 oder 4×4 groß sein"]},{"h":"Die Halma-Familie","p":["Halma wird auf einem 16×16-Brett gespielt, zu zweit mit je 19 Steinen, zu viert mit je 13, die in acht Richtungen ziehen. Monks erhielt 1888 ein amerikanisches Patent. Der Mathematiker Thomas Hill, später Präsident von Harvard, soll ihm den Namen gegeben haben.","Das Sternbrett hat 121 Löcher; meist hat jeder 10 Steine, und es spielen zwei, drei, vier oder sechs. In China heißt es tiaoqi, „Springschach“, und in Japan kennt man ein ähnliches Spiel als „Diamantenspiel“. Auch hier kann ein Gegner, der in der Ecke bleibt, die man ansteuert, das Füllen verhindern."],"cap":["Die Familie der Spiele, in denen man springend die Ecken tauscht: Halma auf 16×16, Stern-Halma und „Chinese Checkers“ auf dem Stern, Ugolki auf 8×8"]},{"h":"Probieren Sie es","p":["Die Ugolki-Regeln lernt man in einer Minute. Doch lange Leitern auch aus den gegnerischen Steinen zu bauen, ohne dem Gegner Trittsteine zu lassen, ergibt einen tiefen Kampf ums Vorausberechnen.","In diesem Atlas können Sie Ugolki mit Lagern von 3×3, 3×4 oder 4×4 oder mit Diagonalzügen spielen. Das 3D-Brett ist aus weißem und kobaltblauem Porzellan, wie die russische Gschel-Keramik."],"cap":[]}],"tl":[["1883","Halma entsteht (um 1883–84, USA)"],["1888","Monks erhält ein US-Patent auf Halma"],["1892","Stern-Halma auf dem Sternbrett, in Deutschland"],["1928","In den USA als „Chinese Checkers“ verkauft"],["1941","Milton Bradley erwirbt die Rechte am Namen"]],"figL":{"fam":[["um 1883–84","Halma","USA · 16×16-Brett"],["1892","Stern-Halma","Deutschland · Sternbrett"],["1928","Chinese Checkers","ein neuer Name in den USA"],["Zeit unbekannt","Ugolki","Russland · 8×8-Brett"]]}},"agon":{"title":"Die Königin auf den Thron, die Garde rings um sie","lead":"Agon wurde im viktorianischen England auf einem Brett aus Sechseckfeldern gespielt. Setzen Sie Ihre Königin auf den Thron in der Mitte und umringen Sie sie mit Ihren sechs Gardisten – dann haben Sie gewonnen.","s":["Agon ist ein Spiel für zwei, auch „Queen’s Guards“ (Die Garde der Königin) genannt. Der Name ist das griechische Wort für „Wettkampf“. Das Brett besteht aus 91 Sechseckfeldern, und das Feld in der Mitte ist der Thron.","Fünf Ringe umgeben den Thron, jeder in einer anderen Farbe als der nächste. Jeder hat eine Königin und sechs Gardisten; es gewinnt, wer seine Königin auf den Thron setzt und die sechs Felder um ihn mit seinen Gardisten besetzt.","Ein Stein zieht jeweils ein Feld weit, entlang desselben Rings oder in den nächstinneren Ring. Nach außen darf er nie: Ist er einmal hineingegangen, gibt es kein Zurück. Nur eine Königin darf den Thron betreten.","Der älteste bekannte Beleg ist ein 1842 in London veröffentlichtes Regelwerk. Das Spiel wird Anthony Peacock aus London zugeschrieben und war in viktorianischen Haushalten beliebt.","Oft wird es das älteste bekannte Brettspiel auf Sechseckfeldern genannt. Einer Darstellung zufolge entstand es im Frankreich des 18. Jahrhunderts, doch die dafür angeführten alten Bretter gelten als spätere Zutaten – sicher ist das nicht."],"quiz":[["Wie gewinnt man beim Agon?","Königin auf dem Thron, umringt von den eigenen sechs Gardisten","Die gegnerische Königin schlagen","Alle Steine am Rand aufreihen","Den leeren Thron umstellen"],["Wohin darf ein Agon-Stein nie ziehen?","In einen äußeren Ring","Entlang desselben Rings","In den nächstinneren Ring","Auf den Thron (als Königin)"],["Wann und wo wurden die Agon-Regeln zuerst veröffentlicht?","London, 1842","Paris, 1742","Berlin, 1892","New York, 1942"]],"kf":["91 Sechseckfelder: der Thron in der Mitte, fünf Ringe darum","Ein Schritt entlang desselben Rings oder nach innen, nie nach außen. Nur die Königin besteigt den Thron","1842 in London veröffentlicht; oft das älteste Sechseck-Brettspiel genannt"],"more":[{"h":"Ein Brett aus Thron und Ringen","p":["Beim Standardbeginn stehen Königinnen und Gardisten beider Spieler abwechselnd auf dem äußersten Ring. Nach den Regeln von 1842 begannen die Königinnen in gegenüberliegenden Ecken, und die Gardisten wurden abwechselnd einzeln eingesetzt.","Das Brett sieht aus wie eine Zielscheibe, farbige Ringe um den Thron. Man sieht auf einen Blick, auf welchem Ring ein Stein steht, und kann leicht zählen, wie viele Schritte ihm bis zum Thron fehlen."],"cap":["Das Agon-Brett und die Anfangsstellung. Das grüne Feld in der Mitte ist der Thron, umgeben von fünf abwechselnd roten und elfenbeinfarbenen Ringen. Königin (Krone) und sechs Gardisten jeder Seite wechseln sich am Rand ab"]},{"h":"Nach innen, immer nach innen","p":["In jedem Zug zieht man einen Stein einen Schritt auf ein leeres Nachbarfeld, rund um denselben Ring oder nach innen.","Ein Feld zwischen zwei gegnerischen Steinen darf man nicht betreten. Eine Mauer feindlicher Steine ist darum ein echtes Hindernis auf dem Weg nach innen."],"cap":["Die Züge. Der weiße Gardist darf entlang seines Rings oder in den inneren Ring ziehen (grün), aber nicht zurück nach außen (rotes ×)"]},{"h":"Eingeklemmt und hinausgeschickt","p":["Klemmen Sie einen gegnerischen Stein in gerader Linie zwischen zwei eigenen ein, ist er gefangen. Sein Besitzer muss den nächsten Zug dafür verwenden, den gefangenen Gardisten auf ein leeres Feld des äußeren Rings zu setzen.","Eine gefangene Königin kommt auf ein beliebiges leeres Feld außer dem Thron, und sie wird zuerst versetzt. Alle mühsam gewonnenen Schritte sind dahin – die Verteidigung ist deshalb sehr wichtig. Die Einzelheiten der Regeln weichen von Buch zu Buch etwas ab."],"cap":["Das Schlagen. (1) Der weiße Gardist rückt vor und klemmt den schwarzen Gardisten in einer Linie zwischen zwei weißen Steinen ein. (2) Im nächsten Zug seines Besitzers kommt der gefangene schwarze Gardist auf ein leeres Randfeld"]},{"h":"Probieren Sie es","p":["Umringen Ihre sechs Gardisten den Thron, während er leer ist, verlieren Sie auf der Stelle. Erst die Königin hineinschicken oder mit den Gardisten einen Weg bahnen? Die Reihenfolge der Züge entscheidet die Partie.","In diesem Atlas können Sie Agon mit dem Standardbeginn am Rand spielen oder mit dem Beginn von 1842, bei dem die Gardisten einzeln eingesetzt werden. Das 3D-Brett ist viktorianisches Mahagoni mit Goldlinien, mit Steinen aus Knochen und Ebenholz."],"cap":[]}],"tl":[["spätes 18. Jh.","Eine Darstellung nennt einen französischen Ursprung (ohne sicheren Beleg)"],["1842","Regeln von „Agon, or the Queen’s Guards“ in London veröffentlicht"],["19. Jh.","Beliebt im viktorianischen England; Bretter u. a. von Jaques verkauft"],["1999","Beschrieben in Parletts Oxford History of Board Games"],["heute","In Ludii aufgenommen, einem System zur Erforschung von Spielen"]]},"dots":{"title":"Punkte, Striche und fallende Scheiben – gelöste Spiele","lead":"Käsekästchen mit Bleistift und Papier und „Vier gewinnt“ mit fallenden Scheiben: zwei Spiele, die jedes Kind spielen kann – und die Mathematiker und Computer ernsthaft zu lösen begannen.","s":["Käsekästchen (Dots and Boxes) spielt man auf Papier mit einem Punkteraster. Abwechselnd verbindet jeder zwei benachbarte Punkte mit einem Strich; wer die vierte Seite eines Quadrats zieht, bekommt dieses Kästchen und zieht noch einen Strich. Wer die meisten Kästchen hat, gewinnt.","Vorgestellt hat das Spiel als „La Pipopipette“ der französische Mathematiker Édouard Lucas, meist wird 1889 genannt. Nach seinem Tod erschien es auch in seinem Buch L’Arithmétique amusante (1895).","„Vier gewinnt“ (Connect Four) spielt man, indem man Scheiben in einen senkrechten Rahmen aus 7 Spalten und 6 Reihen fallen lässt. Die Scheibe fällt ins unterste freie Loch, und vier der eigenen Farbe in einer Linie – waagerecht, senkrecht oder diagonal – gewinnen. Die amerikanische Firma Milton Bradley brachte es 1974 heraus.","Im Oktober 1988 wurde „Vier gewinnt“ „gelöst“. Am 1. James Dow Allen und am 16. Victor Allis zeigten unabhängig voneinander, dass der Anziehende immer gewinnen kann, wenn er in der mittleren Spalte beginnt.","Auch für Käsekästchen bauten der Mathematiker Elwyn Berlekamp und andere eine Theorie der „langen Ketten“ auf, im Jahr 2000 in einem Buch zusammengefasst. Hinter einem Spiel, das jeder spielen kann, steckte tiefe Mathematik."],"quiz":[["Was tut beim Käsekästchen, wer die vierte Seite eines Kästchens zieht?","Er bekommt das Kästchen und zieht noch einmal","Der andere ist am Zug","Er verschenkt das Kästchen","Das Spiel endet"],["Welcher erste Zug gewinnt bei „Vier gewinnt“ für den Anziehenden?","Die mittlere Spalte","Die linke Spalte","Die rechte Spalte","Jede Spalte"],["Wer löste „Vier gewinnt“ 1988 unabhängig voneinander?","Allen und Allis","Lucas und Berlekamp","Wexler und Strongin","Conway und Guy"]],"kf":["Käsekästchen: Kästchen schließen, nehmen, noch einmal ziehen. Wer die erste lange Kette öffnet, verliert meist","„Vier gewinnt“: 7 Spalten × 6 Reihen, die Scheiben fallen nach unten. Im Handel seit 1974","1988 von Allen und Allis getrennt gelöst: Der Anziehende gewinnt aus der Mitte"],"more":[{"h":"Lange Ketten und das Doppelkreuz","p":["Wer eine „Kette“ verbundener Kästchen öffnet, lässt den Gegner alle nehmen. Das Endspiel wird so zum Kampf darum, wer die langen Ketten zuerst öffnen muss. Wer die erste lange Kette öffnet, verliert meistens.","Wer eine Kette einsammelt, kann die letzten zwei Kästchen absichtlich dem Gegner lassen (das Doppelkreuz). Zwei Kästchen verloren – aber der Gegner muss die nächste Kette öffnen, und die großen Ketten, die übrig sind, gehören Ihnen."],"cap":["Der Kampf um die lange Kette. (1) B öffnet eine Kette aus fünf Kästchen. A nimmt drei, zieht dann statt der letzten zwei den Endstrich (2) und gibt sie ab. (3) B nimmt beide mit einem Strich, muss aber noch einmal ziehen – und die nächste Kette öffnen"]},{"h":"Fallende Scheiben, gerade und ungerade Reihen","p":["Man kann eine Scheibe nicht hinlegen, wo man will: Die Spalten füllen sich von unten. Ein Gewinnloch nützt also nichts, solange das Loch darunter leer ist – und wer dieses Loch zuerst füllt, schenkt dem anderen den Sieg.","Wenn sich der Rahmen füllt, entscheidet die Zahl solcher „Löcher, die niemand füllen will“ die Partie. Nach Allis’ Analyse sollen Drohungen in ungeraden Reihen für den Anziehenden stark sein, in geraden für den Nachziehenden."],"cap":["Der Rahmen von „Vier gewinnt“. Eine oben eingeworfene Scheibe fällt ins unterste freie Loch. Rot droht in der dritten Reihe, einer ungeraden (rote Striche). Wer das Loch darunter (×) füllt, schenkt Rot den Sieg"]},{"h":"Eine Zeitleiste gelöster Spiele","p":["„Vier gewinnt“ wird den Amerikanern Howard Wexler und Ned Strongin zugeschrieben. Ein ähnliches Spiel heißt auch „Die Geliebte des Kapitäns“, nach einer Geschichte, dass Kapitän Cook es stundenlang in seiner Kajüte spielte – doch ein sicherer Beleg dafür fehlt.","Nach den Analysen von Allen und Allis gewinnt der Anziehende, der in der Mitte beginnt, spätestens im 41. Zug; ein Beginn in einer Nachbarspalte führt zum Remis, einer in den vier äußeren Spalten lässt den Nachziehenden gewinnen. Die Theorie des Käsekästchens wurde ausführlich in Winning Ways (1982) dargelegt."],"cap":["Schritte zu gelösten Spielen: Lucas’ Pipopipette, der Verkaufsstart von „Vier gewinnt“, das Jahr seiner Lösung und Berlekamps Buch"]},{"h":"Probieren Sie es","p":["Die Antwort zu kennen ist eines; gegen einen Menschen zu spielen etwas ganz anderes. Ketten zählen, gerade und ungerade Reihen zählen, dem Gegner einen Schritt voraus sein – der Spaß bleibt derselbe.","Dieser Atlas hat Käsekästchen und „Vier gewinnt“. Ziehen Sie Striche auf einem Heft oder einer Schiefertafel, lassen Sie Scheiben in einen Rahmen aus Leder oder Eis fallen, und erhaschen Sie einen Blick auf das, was die Mathematiker sahen."],"cap":[]}],"tl":[["1889","Lucas stellt „La Pipopipette“ vor (nach den meisten Quellen)"],["1974","Milton Bradley bringt „Vier gewinnt“ heraus"],["1982","Winning Ways analysiert Käsekästchen"],["1988","Allen und Allis lösen „Vier gewinnt“ getrennt"],["2000","Berlekamps The Dots and Boxes Game"]],"figL":{"time":[["1889","La Pipopipette","Lucas · Frankreich"],["1974","Vier gewinnt","Milton Bradley"],["1988","Vier gewinnt gelöst","Allen und Allis · Anzug gewinnt"],["2000","Das Käsekästchen-Buch","Berlekamp"]]}},"hitblow":{"title":"Die vier Versteckten finden – die Familie von Hit & Blow","lead":"Vier versteckte Farben oder Ziffern erraten, mit nichts als „Treffern“ und „Halbtreffern“ als Hinweisen. Das Spiel wuchs vom Papier-und-Bleistift-Zeitvertreib zu den Farbstiften von Mastermind – und weiter in die Informatik.","s":["Bei Hit & Blow legt ein Spieler heimlich vier Farben oder Ziffern aus. Auf jeden Tipp des anderen erfährt man nur, wie viele in Farbe und Platz stimmen (Hits, Treffer) und wie viele die richtige Farbe am falschen Platz haben (Blows, Halbtreffer).","Es stammt von einem Zahlenspiel mit Papier und Bleistift ab, „Bulls and Cows“ (Stiere und Kühe): Treffer sind Stiere, Halbtreffer Kühe. Manchmal heißt es, das Spiel sei hundert Jahre alt, doch sein wirklicher Ursprung ist unbekannt.","1970 machte Mordecai Meirowitz, ein israelischer Postmeister und Fernmeldetechniker, daraus ein Brettspiel mit farbigen Steckern. Invicta Plastics bei Leicester in England kaufte die Rechte und brachte es 1971–72 als Mastermind heraus – es ging um die ganze Welt.","Zur selben Zeit spielten auch Computer das Zahlenraten. Vor 1970 entstand für den Titan-Rechner der Universität Cambridge eine Fassung namens MOO, die 1972 auf Multics am MIT in den USA übertragen wurde.","1976–77 zeigte der Informatiker Donald Knuth, dass man bei Mastermind mit 6 Farben und 4 Löchern (insgesamt 1296 Codes) mit den richtigen Tipps den Code immer in höchstens fünf Versuchen findet."],"quiz":[["Wie heißt es, wenn eine geratene Farbe am selben Platz steht wie im Code?","Treffer (Hit)","Halbtreffer (Blow)","Fehlschlag","Paar"],["Wer erfand Mastermind mit seinen farbigen Steckern?","Meirowitz in Israel","Knuth in den USA","die britische Post","Studenten in Cambridge"],["Wie viele Versuche reichen nach Knuth bei Mastermind mit 6 Farben und 4 Löchern immer?","Höchstens fünf","Höchstens drei","Höchstens acht","Höchstens zehn"]],"kf":["Treffer: richtige Farbe, richtiger Platz; Halbtreffer: richtige Farbe, falscher Platz. Welche, wird nie verraten","Bulls and Cows auf Papier → Meirowitz’ Farbstecker 1970 → Mastermind 1971–72","Knuth (1976–77): Alle 1296 Codes aus 6 Farben × 4 Löchern sind in höchstens fünf Versuchen zu finden"],"more":[{"h":"Treffer und Halbtreffer","p":["Die Stifte verraten nie, welche Plätze Treffer waren – nur, dass es „ein Treffer und zwei Halbtreffer“ waren. Darum kombiniert man die Antworten von Tipp zu Tipp und grenzt den Code ein.","Einen Tipp zu wiederholen, bringt nichts. Meist wählt man eine Anordnung, die zu allen bisherigen Antworten passt; doch manchmal liefert ein Tipp, der gar nicht der Code sein kann, mehr Information und ist der kürzere Weg."],"cap":["Ein Tipp und seine Antwort. Oben der versteckte Code, unten der Tipp. Der linke stimmt in Farbe und Platz: ein Treffer (rosa Stift). Der zweite und vierte sind Farben aus dem Code am falschen Platz: Halbtreffer (weiße Stifte). Der dritte kommt nicht vor (×)"]},{"h":"Jede Antwort verkleinert das Feld","p":["Knuths Methode wählt jedes Mal den Tipp, der selbst bei der schlechtesten Antwort die wenigsten Codes übrig lässt. Ihr erster Zug verwendet zwei Farben je zweimal.","Spätere Arbeiten fanden auch die Methode mit dem kleinsten Durchschnitt: 1993 zeigten Koyama und Lai im Mittel etwa 4,34 Tipps (im schlechtesten Fall sechs). Das Zahlenspiel Bulls and Cows mit vier verschiedenen Ziffern ist immer in sieben Tipps zu lösen."],"cap":["Ein Code, mit Knuths Methode gefunden. Die 1296 Codes aus 6 Farben × 4 Löchern sinken nach dem ersten Tipp auf 256, nach dem zweiten auf 41, nach dem dritten auf 6 und nach dem vierten auf 1; der fünfte Tipp trifft (Balken logarithmisch)"]},{"h":"Von Zahlen zu Farben","p":["Mastermind bekam viele Verwandte, darunter Super Mastermind mit 8 Farben und 5 Löchern (1972) und Word Mastermind, bei dem man Buchstaben errät.","In Japan heißt das Zahlenratespiel „Hit & Blow“; es tauchte im Fernsehen und in Spielesammlungen für Konsolen auf."],"cap":["Die Familie in der Zeit: Bulls and Cows auf Papier, MOO auf dem Cambridge-Rechner, Meirowitz’ Mastermind und Knuths „fünf“"]},{"h":"Probieren Sie es","p":["Der schönste Moment ist, wenn man beim Vergleichen der Hinweiszeilen merkt: „Diese Farbe kann nur hierhin.“ Wenn jeder Tipp das Feld mindestens halbiert, spielen Sie wie ein Meister.","Hit & Blow in diesem Atlas hat fünf Varianten – 4 aus 6 Farben ohne Wiederholung (360 Codes), mit Wiederholung (Knuths 1296), 3 oder 4 Ziffern und ein Expertenspiel mit 5 aus 8 Farben – dazu ein Rätsel des Tages."],"cap":[]}],"tl":[["1970","MOO auf dem Cambridge-Rechner; Meirowitz erdenkt das Stecker-Brett"],["1971","Invicta Plastics kauft die Rechte und bringt Mastermind heraus"],["1972","MOO kommt auf Multics am MIT; Super Mastermind"],["1977","Knuth: „höchstens fünf“ (Aufsatz von 1976–77)"],["1993","Koyama und Lai: eine Methode mit etwa 4,34 im Mittel"]],"figL":{"time":[["?","Bulls and Cows","Zahlen auf Papier"],["1970","MOO","der Cambridge-Rechner"],["1971","Mastermind","Meirowitz · Invicta"],["1977","Immer in fünf","Knuths Beweis"]]}},"botao":{"title":"Fußball mit den Knöpfen vom Mantel","lead":"Das brasilianische Futebol de botão ist Tischfußball, bei dem man Knöpfe anschnippt, um einen winzigen Ball ins Tor zu bringen. Aus einem Hosentaschenspiel von Kindern wurde ein staatlich anerkannter Sport.","s":["Futebol de botão heißt „Knopffußball“. Auf einem etwa 167 cm langen Feld stellt jede Mannschaft zehn runde Knöpfe und einen rechteckigen Block als Torwart auf und schnippt die Knöpfe, um einen 1 cm großen Filzball ins gegnerische Tor zu bringen.","Angefangen haben soll es Anfang des 20. Jahrhunderts, als Kinder in Brasilien und Ungarn die Knöpfe von Mänteln und Hemden abtrennten, um zu spielen. In Ungarn heißt es bis heute gombfoci, „Knopffußball“.","In Brasilien brachte Geraldo Décourt, ein Künstler aus Rio de Janeiro, Ordnung ins Spiel. 1930 (nach manchen Quellen 1929) veröffentlichte er das erste Regelbuch und nannte das Spiel nach dem Belag der Spielplatte „Foot-Ball Celotex“.","1962 entstand ein Verband im Bundesstaat São Paulo, und 1988 erkannte Brasiliens Nationaler Sportrat „futebol de mesa“ (Tischfußball) als offizielle Sportart an. Décourts Geburtstag, der 14. Februar, ist im Bundesstaat São Paulo der Tag der Knopfspieler.","Auch andere Länder kennen Schnippfußball. In Großbritannien entstand 1929 in Liverpool ein Spiel derselben Art, und 1947 erschien ein Tischfußball, bei dem man kleine Figuren mit dem Finger schnippt; der Tischkicker mit Figuren auf Stangen wurde schon in den 1920er-Jahren patentiert."],"quiz":[["Woraus besteht eine Mannschaft beim Futebol de botão?","Zehn Knöpfe und ein Torwart","Elf Knöpfe","Fünf Knöpfe und ein Torwart","Elf Figuren"],["Wann wurde es in Brasilien als offizielle Sportart anerkannt?","1988","1930","1962","2001"],["Was schnippt man bei dem 1947 in Großbritannien entstandenen Tischfußball mit dem Finger?","Beschwerte Spielerfiguren","Mantelknöpfe","Kronkorken","Münzen"]],"kf":["Tischfußball mit zehn Knöpfen und einem Torwartblock, die einen Filzball vorwärtsschnippen","Kinderspiel Anfang der 1900er → Décourts Regelbuch 1930 → offizielle Sportart in Brasilien 1988","Verwandte: Ungarns gombfoci, britischer Schnippfußball (1929 und 1947) und der Stangen-Tischkicker"],"more":[{"h":"Schnippen, ansagen, schießen","p":["Man kann einen Knopf mit dem Finger schnippen, doch viele Spieler drücken mit einem flachen Werkzeug, der palheta, auf seinen Rand, sodass er losgleitet. Der Knopf selbst muss den Ball treffen.","Nach der 12-Berührungen-Regel muss man den Schuss laut ansagen und warten, bis der Gegner seinen Torwart aufgestellt hat. Ein Tor ohne Ansage zählt nicht."],"cap":["So wird ein Knopf gespielt. (1) Man drückt mit einem flachen Werkzeug auf den Rand des Knopfes; er gleitet und trifft den Ball. (2) Der Ball läuft am Torwart (dem blauen Block) vorbei ins Tor"]},{"h":"Regeln, die sich mit den Berührungen ändern","p":["Brasilien kennt überlieferte Regeln aus verschiedenen Gegenden: den Stil von Bahia mit einer Berührung und einer Scheibe, den von Rio mit drei Berührungen und Ball und den von São Paulo mit zwölf Berührungen und Ball.","Bei zwölf Berührungen darf man pro Ballbesitz bis zu zwölfmal schnippen, denselben Knopf bis zu dreimal hintereinander. Je weniger Berührungen, desto weniger Tore; das Spiel mit einer Berührung, bei dem nach jedem Schnipser gewechselt wird, gilt als Spiel für Kenner."],"cap":["Eine Mannschaft: zehn Knöpfe und ein rechteckiger Torwart. Brasiliens drei klassische Regelwerke unterscheiden sich darin, wie viele Schnipser (Berührungen) ein Ballbesitz erlaubt"]},{"h":"Die Familie des Schnippfußballs","p":["Der britische Tischfußball von 1947, bei dem man Figuren mit dem Finger schnippt, soll ein Spiel derselben Art zum Vorbild gehabt haben, das 1929 in Liverpool entstand. Man schnippt kleine beschwerte Spielerfiguren, um den Ball zu bewegen.","Der Tischkicker, bei dem man Reihen von Figuren an Stangen dreht, um den Ball zu schießen, wurde 1921 in Großbritannien patentiert, und in Spanien ließ Alejandro Finisterre 1937 seinen futbolín patentieren."],"cap":["Die Familie des Schnipp-Tischfußballs: Ungarns gombfoci, zwei britische Schnippspiele und der Tischkicker mit Figuren auf Stangen"]},{"h":"Probieren Sie es","p":["Den Ball mit Pässen nach vorn bringen, den Schuss ansagen, auf die Lücke neben dem Torwart zielen: Kraft und Winkel eines einzigen Drucks entscheiden das Spiel.","Futebol de botão in diesem Atlas ist ein reines 3D-Spiel nach der 12-Berührungen-Regel. Wählbar sind Spiele nach Zügen, nach Toren oder ein Elfmeterschießen sowie Felder aus Rasen, Holz und mehr."],"cap":[]}],"tl":[["Anfang 20. Jh.","Kinder in Ungarn und Brasilien spielen mit Knöpfen"],["1930","Décourts erstes Regelbuch (nach manchen Quellen 1929)"],["1947","In Großbritannien entsteht ein Tischfußball mit Schnippfiguren"],["1962","Ein Verband im Bundesstaat São Paulo wird gegründet"],["1988","In Brasilien als offizielle Sportart anerkannt"]],"figL":{"rules":[["1","Bahia\nScheibe"],["3","Rio\nBall"],["12","São Paulo\nBall"]],"family":[["Futebol de botão","Brasilien · Regelbuch von 1930"],["Gombfoci","Ungarn · Mantelknöpfe"],["Ein Spiel aus Liverpool","Großbritannien · 1929 · gleiche Art"],["Figuren-Tischfußball","Großbritannien · 1947 · geschnippt"],["Tischkicker","Figuren an Stangen · Patent 1921"]]}},"hockey":{"title":"Vom Küchenbrett zur Luftbahn","lead":"Tischhockey gibt es in zwei Arten: Stangenhockey, bei dem Stangen die Spieler bewegen, und Airhockey, bei dem ein auf Luft schwebender Puck hin und her geschlagen wird. Dies ist die Geschichte eines selbst gebauten kanadischen Bretts und einiger amerikanischer Ingenieure.","s":["Tischhockey ist Hockey auf einer kleinen Bahn auf dem Tisch. Grob gibt es zwei Arten: Stangenhockey, bei dem Stangen unter dem Brett kleine Spielerfiguren bewegen, und Airhockey, bei dem der Puck auf einem Luftkissen schwebt und mit Schlägern gespielt wird.","Das erste Tischhockey soll 1932 Donald Munro in Toronto, Kanada, gebaut haben. In der Weltwirtschaftskrise fehlte das Geld für Weihnachten, und so baute er seinen Kindern ein Brett aus Holzresten, Draht und Uhrfedern. In einem Kaufhaus in Toronto verkauft, wurde es ein Erfolg.","Beim Stangenhockey stehen die Figuren in Schlitzen im Brett und sind mit Stangen darunter verbunden. Schiebt oder zieht man die Stange, gleitet der Spieler den Schlitz entlang; dreht man sie, schwingt er den Schläger. Später wurde das Spiel in den nordischen Ländern und anderswo beliebt, mit internationalem Verband und Weltmeisterschaften.","1969 begannen Ingenieure der amerikanischen Firma Brunswick an einem Spiel auf einer reibungsarmen Fläche zu arbeiten. Bob Lemieux belebte das ins Stocken geratene Projekt neu, und „Airhockey“ mit flacher Scheibe, zwei Schlägern und Schlitztoren entstand; Anfang der 1970er-Jahre kam es in den Handel.","Dinge auf einem Lufttisch schweben zu lassen, war eine ältere Idee, genutzt zum Bewegen schwerer Lasten und für Physikgeräte in Schulen. Airhockey wurde ein Erfolg: Mitte der 1970er-Jahre gab es in den USA Turniere, und 1978 begann eine Weltmeisterschaft."],"quiz":[["Wo soll das erste Tischhockey gebaut worden sein?","Toronto, 1932","Chicago, 1972","Stockholm, 1900","Tokio, 1950"],["Warum gleitet der Airhockey-Puck immer weiter?","Er schwebt auf Luft aus winzigen Löchern im Tisch","Er ist aus Eis","Der Tisch ist geneigt","Er hat Räder"],["Wie bewegt man beim Stangenhockey einen Spieler?","Eine Stange unter dem Brett schieben, ziehen und drehen","Mit dem Finger schnippen","Mit einem Magneten","An einer Schnur"]],"kf":["Stangenhockey: Stangen unter dem Brett schieben, ziehen und drehen, um die Spieler in ihren Schlitzen zu bewegen","Airhockey: Luft aus den Löchern lässt den Puck schweben, der mit Schlägern gespielt wird","Ein selbst gebautes Brett in Toronto 1932 → Forschung ab 1969 → Airhockey Anfang der 1970er"],"more":[{"h":"Spieler in Schlitzen","p":["Da jeder mehrere Spieler führt, ist schnelles Umgreifen von Stange zu Stange alles. Der Grundplan: passen und auf die Seite zielen, die der Torwart nicht deckt.","Munros erstes Brett soll in der Mitte höher gewesen und zu den Enden abgefallen sein, mit einem Hebel für den Torwart und Schnippern für die anderen. Die heutigen Drehstangen verbreiteten sich später."],"cap":["Ein Stangenhockey-Brett. Jeder Spieler steht in einem Schlitz und wird von einer Stange unter dem Brett bewegt: (1) Schieben oder Ziehen lässt ihn den Schlitz entlanggleiten; (2) Drehen lässt ihn den Schläger schwingen (die Strichlinie ist die Stange unter dem Brett)"]},{"h":"Ein Puck, der auf Luft schwebt","p":["Fast ohne Reibung prallt der Puck wieder und wieder von den Banden ab. Der Bandenschuss, der den Winkel an einer Bande ändert, gehört zum Grundhandwerk; Verteidiger springen in die Torecken und bilden ein Dreieck.","Turniertische sind 8 Fuß (etwa 2,4 m) lang. Der Schläger heißt auch Pusher oder Paddel, und der Puck ist aus hartem Kunststoff."],"cap":["Ein Airhockey-Tisch. Luft strömt durch unzählige winzige Löcher (Pfeile links), der Puck schwebt kaum merklich und gleitet immer weiter. Vom roten Schläger getroffen, prallt er von der rechten Bande ab und läuft am blauen Schläger vorbei, der die Tormitte deckt (Striche)"]},{"h":"Tischhockey in der Zeit","p":["In den 1980er-Jahren wurden Stangenhockey-Tische unter einer durchsichtigen Kuppel in Spielhallen beliebt. Der Tischkicker mit Figuren auf Stangen, die einen Ball schießen, gehört zur selben „stangengetriebenen“ Familie.","Auch in Japan wurde Airhockey etwa ab den 1980er-Jahren ein Spielhallen-Klassiker, und es gibt kleine Tische für zu Hause."],"cap":["Tischhockey in der Zeit: Stangenhockey in Toronto 1932, Forschung an Lufttischen ab 1969, Airhockey Anfang der 1970er und eine Weltmeisterschaft ab 1978"]},{"h":"Probieren Sie es","p":["Verteidigen, die Banden nutzen, durch die Lücke neben dem gegnerischen Schläger schlüpfen: Augen, die einen schnellen Puck lesen, und flinke Hände entscheiden das Spiel.","Tischhockey in diesem Atlas ist ein reines 3D-Spiel mit sechs Tischen, darunter eine kleine Filzbahn und ein Lufttisch. Nutzen Sie den Kantenschuss – einen streifenden Treffer mit dem Rand des Schlägers –, um das gegnerische Tor zu bezwingen."],"cap":[]}],"tl":[["1932","Munro baut in Toronto ein Tischhockey"],["1969","In den USA beginnt die Forschung an einem Spiel auf dem Lufttisch"],["1972","Airhockey kommt in den Handel (Anfang der 1970er)"],["1975","In den USA wird ein Airhockey-Verband gegründet"],["1978","Eine Airhockey-Weltmeisterschaft beginnt"]],"figL":{"time":[["1932","Stangenhockey","Toronto · selbst gebaut"],["1969","Lufttisch-Forschung","amerikanische Ingenieure"],["1972","Airhockey","herausgebracht von Brunswick"],["1978","Weltmeisterschaft","Airhockey-Turniere"]]}},"solitaire":{"title":"Patience: Karten für einen allein","lead":"Solitär, das Kartenspiel für eine Person, heißt in Großbritannien „Patience“ – und im Deutschen ebenfalls Patience. Von einem deutschen Buch des 18. Jahrhunderts bis zum Computerbildschirm: die Geschichte der Karten, die man allein legt.","s":["Patiencen (Solitär) sind Kartenspiele für eine Person. Man legt die Karten nach einem festen Bild aus, bewegt sie nach den Regeln und gewinnt, wenn jede Farbe vom Ass bis zum König aufgebaut ist. In Großbritannien heißen sie „patience“; in Nordamerika setzte sich im 20. Jahrhundert „solitaire“ durch.","Die älteste bekannte Beschreibung steht in der Ausgabe von 1783 eines deutschen Spielebuchs, unter dem Namen „Patience“. Wahrscheinlich entstanden die Spiele in Deutschland oder Skandinavien; vermutet wird eine Verbindung zu den Kartenlegungen der Wahrsagerei, die sich kurz zuvor verbreiteten. Auf Dänisch und Norwegisch heißen sie kabal.","Anfang des 19. Jahrhunderts wurden Patiencen in Frankreich Mode und erreichten in der zweiten Jahrhunderthälfte Großbritannien und Amerika. 1826 erschien in Russland ein Buch nur über Patiencen. Auf Englisch ist Lady Adelaide Cadogans Illustrated Games of Patience von etwa 1870 bekannt.","Die berühmteste, Klondike, wird mit sieben Stapeln gespielt. Der älteste Beleg ihrer Regeln steht in einem Buch von 1907. Manche leiten den Namen vom kanadischen Goldrausch ab, doch einen sicheren Beleg gibt es nicht.","1990 kam Klondike als mitgeliefertes Spiel auf die PCs, und Menschen in aller Welt begannen zu spielen. FreeCell, bei dem alle Karten offen liegen, schuf 1978 der Medizinstudent Paul Alfille auf einem Universitätsrechner."],"quiz":[["Wie heißt Solitär in Großbritannien?","Patience","Kabal","Klondike","FreeCell"],["Wo steht der älteste Beleg für Patiencen?","In einem deutschen Buch, Ausgabe 1783","In einem französischen Buch um 1650","In einem amerikanischen Buch von 1907","Auf einem Computer von 1990"],["Wie viele der Spiele 1 bis 32.000 des mit Computern gelieferten FreeCell sind unlösbar?","Nur eines, Nr. 11982","Genau die Hälfte","Jedes hundertste","Keines"]],"kf":["Allein Karten ordnen und jede Farbe vom Ass bis zum König aufbauen. In Großbritannien „patience“","Ältester Beleg: ein deutsches Buch, Ausgabe 1783. Wohl in Deutschland oder Skandinavien entstanden","Klondikes älteste Regeln in einem Buch von 1907; ab 1990 verbreiteten Computer es weltweit"],"more":[{"h":"Das Klondike-Bild","p":["28 Karten kommen auf die sieben Stapel, die übrigen 24 bilden den Talon. Auf den Stapeln legt man absteigend ab, abwechselnd Rot und Schwarz. Auf einen leeren Stapel darf nur ein König.","Wie oft man Klondike bei gutem Spiel gewinnen kann, weiß man bis heute nicht. Selbst wenn man alle verdeckten Karten kennte, sind nach Berechnungen höchstens gut acht von zehn Spielen zu gewinnen."],"cap":["Das Klondike-Bild. Links oben Talon und aufgedeckte Karten, rechts oben die vier Ablagen nach Farben. Unten sieben Stapel mit einer bis sieben Karten, nur die oberste offen"]},{"h":"FreeCell – fast immer lösbar","p":["Bei FreeCell ordnet man offen liegende Karten mithilfe von vier freien Zellen, die je eine Karte aufnehmen. Es ist ein Spiel des Vorausdenkens, nicht des Glücks, und fast jedes Spiel ist lösbar.","Von den Spielen 1 bis 32.000 des mit Computern gelieferten Spiels ließ sich nur Nr. 11982 nicht lösen. Eine Studie von 2018 über 8,6 Milliarden Spiele fand etwa ein unlösbares auf 84.000."],"cap":["Das FreeCell-Bild. Links oben vier freie Zellen, rechts oben vier Ablagen, unten acht offene Reihen. Der Streifen darunter steht für die Spiele 1 bis 32.000 des mit Computern gelieferten Spiels: Nur Nr. 11982 ist unlösbar"]},{"h":"Patience in der Zeit","p":["FreeCell geht auf „Baker’s Game“ zurück, das Martin Gardner 1968 in einer Zeitschrift beschrieb. Ende des 19. Jahrhunderts sammelte die Engländerin Mary Whitmore Jones rund 250 Patiencen in ihren Büchern.","Anderswo kann „Solitär“ auch Brettspiele für eine Person meinen, etwa das Steckspiel Solitär. Der Spielehistoriker David Parlett bevorzugt „Patience“, das nur die Kartenspiele bezeichnet."],"cap":["Patience in der Zeit: ein deutsches Buch von 1783, ein englisches Buch um 1870, die Klondike-Regeln 1907, FreeCell 1978 und die Computer 1990"]},{"h":"Probieren Sie es","p":["Patience ist ein Spiel für stille Momente, das den Kopf ordnet. Welchen Stapel zuerst auflösen, welche Karte zurückhalten? Je weiter man vorausdenkt, desto öfter gewinnt man.","Solitär in diesem Atlas bietet Klondike, Spider und FreeCell sowie ein Spiel des Tages. Ganz im Sinn des Namens Patience: in Ruhe legen."],"cap":[]}],"tl":[["1783","„Patience“ in einem deutschen Buch (ältester Beleg)"],["1826","In Russland erscheint ein Buch nur über Patiencen"],["um 1870","Lady Adelaide Cadogans Illustrated Games of Patience"],["1907","Die Klondike-Regeln erscheinen in einem Buch"],["1990","Weltweite Verbreitung durch ein mit Computern geliefertes Spiel"]],"figL":{"time":[["1783","Patience","ältester Beleg, deutsches Buch"],["um 1870","Ein englisches Buch","Lady Adelaide Cadogan"],["1907","Klondike","älteste Regeln"],["1978","FreeCell","auf einem Universitätsrechner"],["1990","Auf dem Computer","mitgeliefertes Spiel"]]}},"sudoku":{"title":"Die Ziffern müssen allein sein","lead":"Sudoku: die Ziffern 1 bis 9 in ein 9×9-Gitter setzen. Geboren in einem amerikanischen Heft, benannt in Japan, von britischen Zeitungen in die Welt getragen – es braucht kein Rechnen, nur Logik.","s":["Sudoku hat nur eine Regel: Das 9×9-Gitter so füllen, dass jede Zeile, jede Spalte und jedes fett umrandete 3×3-Kästchen jede Ziffer von 1 bis 9 genau einmal enthält. Addieren oder Subtrahieren ist nicht nötig. Ein gutes Rätsel hat genau eine Lösung.","Ein fertiges Sudoku ist eine Art dessen, was Mathematiker ein lateinisches Quadrat nennen. Der Mathematiker Leonhard Euler aus dem 18. Jahrhundert ist für ihre Erforschung bekannt, doch mit dem Rätsel selbst gibt es keine direkte Verbindung. 1892 und 1895 druckten französische Zeitungen Zahlen-Zauberquadrate zum Ausfüllen, die aber Rechnen verlangten oder keine Kästchen hatten – noch nicht das heutige Sudoku.","Das moderne Rätsel erschien zuerst 1979 in einem amerikanischen Rätselheft, unter dem Namen „Number Place“. Als Urheber gilt Howard Garns, ein Architekt im Ruhestand.","1984 stellte es ein japanisches Rätselheft (Nikoli) unter dem Titel „Die Ziffern müssen ledig sein“ vor, und 1986 kürzte der Firmenchef Maki Kaji den Namen zu „Sudoku“. In Japan ist der Name eine eingetragene Marke dieser Firma; andere Verlage sagen „Nanpure“ und Ähnliches.","Wayne Gould, der 1997 in Tokio auf ein Sudoku-Buch stieß, schrieb jahrelang an einem Programm, das Rätsel erzeugt, und im November 2004 erschien Sudoku in der britischen Zeitung The Times. 2005 war es ein Zeitungsfieber in aller Welt, und seit 2006 gibt es eine Weltmeisterschaft."],"quiz":[["Was muss beim Sudoku jede Ziffer von 1 bis 9 genau einmal enthalten?","Jede Zeile, jede Spalte und jedes 3×3-Kästchen","Nur die Spalten","Nur die Diagonalen","Nur der Rand"],["Wie viele Vorgaben braucht ein eindeutig lösbares Sudoku mindestens?","17","9","25","30"],["Wo und wann erschien das moderne Sudoku zuerst in einem Heft?","USA, 1979","Japan, 1984","Frankreich, 1892","Großbritannien, 2004"]],"kf":["Jede Zeile, Spalte und jedes 3×3-Kästchen enthält 1–9 genau einmal. Kein Rechnen","Mindestens 17 Vorgaben: Eine vollständige Suche zeigte 2012, dass kein Sudoku mit 16 eindeutig lösbar ist","„Number Place“ in den USA 1979 → in Japan benannt 1984 → von Großbritannien aus in die Welt 2004"],"more":[{"h":"Zeilen, Spalten und Kästchen","p":["Der einfachste Gedanke beim Lösen ist: „Diese Ziffer kann nur hierhin.“ Steht eine Ziffer, darf kein anderes Feld derselben Zeile, Spalte oder desselben Kästchens sie noch einmal enthalten.","Wie im Bild sperren 5en anderswo die Zeilen und Spalten des Kästchens oben links, bis für dessen 5 nur ein Feld bleibt. Ein gutes Rätsel lässt sich allein mit solchen kleinen Schritten bis zum Ende lösen, ohne Raten."],"cap":["Die Bedingungen. Gesucht ist die 5 für das Kästchen oben links (grüner Rahmen). Die vier anderen 5en sperren seine Zeilen und Spalten (rote Streifen), sodass nur das grüne Feld für seine 5 bleibt"]},{"h":"Ab siebzehn Vorgaben","p":["Nimmt man Vorgaben eine nach der anderen weg, ist die Lösung irgendwann nicht mehr eindeutig. 2012 zeigten der Ire Gary McGuire und Kollegen mit einer langen vollständigen Computersuche, dass kein Sudoku mit 16 Vorgaben eindeutig lösbar ist: Das Minimum ist 17.","2005 wurde außerdem berechnet, dass es etwa 6,67 × 10²¹ fertige Sudoku-Gitter gibt. Mehr Vorgaben bedeuten nicht immer ein leichteres Rätsel: Die Schwierigkeit hängt davon ab, wo sie stehen."],"cap":["Ein Sudoku mit nur 17 Vorgaben; es hat trotzdem genau eine Lösung. Ein eindeutig lösbares Sudoku mit 16 Vorgaben gibt es nicht"]},{"h":"Sudoku in der Zeit","p":["Der Name „Sudoku“ kürzt „Die Ziffern müssen ledig sein“ ab – eine Ziffer pro Feld. Auch auf Deutsch heißt es einfach Sudoku.","Es gibt viele Verwandte mit leicht geänderten Regeln: „Killer“, bei dem die Summe in jedem Käfig der Hinweis ist; „Jigsaw“ mit unregelmäßigen Gebieten; und riesige Rätsel aus fünf sich überlappenden Gittern."],"cap":["Sudoku in der Zeit: Eulers lateinische Quadrate, Rätsel in französischen Zeitungen, das amerikanische „Number Place“, die Namensgebung in Japan und das weltweite Fieber, das in Großbritannien begann"]},{"h":"Probieren Sie es","p":["Mit Bleistift, Papier und etwas Eingebung kann man überall spielen. Wenn es hakt, wählen Sie eine Ziffer und suchen Sie das ganze Gitter danach ab.","Dieser Atlas bietet Sudoku mit täglich neuen Rätseln in drei Stufen und Speed-Sudoku, ein Wettlauf auf einem kleinen 4×4-Gitter."],"cap":[]}],"tl":[["1782","Euler erforscht lateinische Quadrate (die mathematische Wurzel)"],["1892","Ein Zahlenrätsel in einer französischen Zeitung"],["1979","„Number Place“ in einem amerikanischen Heft"],["1984","In Japan vorgestellt; 1986 „Sudoku“ genannt"],["2004","Von britischen Zeitungen aus ein weltweites Fieber"]],"figL":{"time":[["1782","Lateinische Quadrate","Eulers Forschung · Mathematik"],["1892","Französische Zeitungen","Zahlen-Ausfüllrätsel"],["1979","Number Place","ein amerikanisches Heft"],["1984","„Sudoku“","Name aus einem japanischen Heft"],["2004","Weltweites Fieber","von britischen Zeitungen"]]}},"shanghai":{"title":"Gestapelte Steine, immer zwei","lead":"Mahjong-Solitär, in Japan „Shanghai“ genannt: Man nimmt gleiche Paare von einem Haufen Mahjong-Steine. Die Steine stammen aus dem China des 19. Jahrhunderts, diese Spielweise aber entstand 1981 auf einem amerikanischen Universitätsrechner.","s":["Mahjong-Solitär ist ein Spiel für eine Person: 144 Mahjong-Steine werden in mehreren Lagen gestapelt, und man nimmt Steine mit gleichem Bild paarweise weg. Nehmen darf man nur einen Stein, auf dem nichts liegt und dessen linke oder rechte Seite frei ist. Wer alle 72 Paare abräumt, gewinnt.","Die Steine sind die des Mahjong, das im China des 19. Jahrhunderts entstand. Sie aufzustapeln und allein abzuräumen, begann aber 1981 mit „Mah-Jongg“, das der Amerikaner Brodie Lockard auf PLATO schrieb, einem an Universitäten genutzten Lernrechnersystem.","1986 kam das Spiel unter dem Namen „Shanghai“ für Heimcomputer heraus und wurde ein Erfolg. In Japan wurde dieser Name zur Bezeichnung der Spielweise selbst.","Beim Erscheinen warb man damit, es gehe auf „die Schildkröte“ zurück, ein seit Jahrhunderten in China gespieltes Spiel. Doch Lockard selbst hat das nie behauptet, und es gibt keinen sicheren Beleg – am besten nimmt man es als Legende.","Um 1989 kam mit Shisen-sho ein Verwandter in die Spielhallen, bei dem man Paare durch eine Linie verbindet. Ab 1990 wurde das Spiel auch als mitgeliefertes Spiel auf PCs viel gespielt."],"quiz":[["Welche Steine darf man beim Mahjong-Solitär nehmen?","Steine ohne Auflage, links oder rechts frei","Steine der untersten Lage","Ringsum eingeschlossene Steine","Nur Steine in der Mitte"],["Wo entstand diese Spielweise zuerst?","1981 auf einem amerikanischen Universitätsrechner","Im China des 19. Jahrhunderts","In Shanghai in den 1920ern","In Japan 1990"],["Was ist mit der Geschichte vom alten chinesischen Spiel „die Schildkröte“?","Werbung, ohne sicheren Beleg","Der Erfinder schrieb sie auf","Sie steht in einem alten chinesischen Buch","Sie kommt von einem Panzermuster"]],"kf":["Gleiche Paare von einem Haufen aus 144 Steinen nehmen; frei sind nur Steine ohne Auflage und mit einer freien Seite","Es begann 1981 mit Lockards „Mah-Jongg“ auf PLATO","Als „Shanghai“ 1986 verbreitet; die Schildkröten-Legende war Werbung, ohne Beleg"],"more":[{"h":"Freie und gesperrte Steine","p":["Zwei Bedingungen entscheiden, ob ein Stein frei ist: Nichts liegt darauf, und links oder rechts liegt kein Stein. Blumen (Pflaume, Orchidee, Chrysantheme, Bambus) und Jahreszeiten (Frühling, Sommer, Herbst, Winter) bilden innerhalb ihrer Gruppe Paare, auch wenn die Bilder verschieden sind.","Die Reihenfolge ist sehr wichtig. Nimmt man das erste Paar, das man sieht, kann ein gleicher Stein unter einem anderen eingeschlossen bleiben – und am Ende geht nichts mehr."],"cap":["Steine, die man nehmen darf (✓), und solche, die nicht (×). Oben: die beiden Endsteine und das obenauf liegende 發 sind frei; Steine mit Auflage oder beidseitig gesperrte nicht. Unten: das 東 in der Mitte ist auf beiden Seiten gesperrt"]},{"h":"Die berühmte Schildkröte","p":["Die Schildkröte ist ein länglicher Haufen, aus dem an beiden Enden Steine wie Kopf und Schwanz herausragen. Eine Untersuchung von zehn Millionen Spielen dieser Aufstellung ergab, dass etwa 3 % sich nicht abräumen lassen, wie man auch spielt.","Viele weitere Aufstellungen wurden erfunden – Pyramiden, Drachen, Burgen und mehr. Jede Form verändert, wo Steine leicht freikommen und wo es klemmt."],"cap":["Die berühmteste Aufstellung, die Schildkröte, von oben: 87 Steine in der untersten Lage, dann 36, 16, 4 und einer obenauf – fünf Lagen, 144 Steine (je dunkler, desto höher)"]},{"h":"Mahjong-Solitär in der Zeit","p":["Bei Shisen-sho darf man zwei gleiche Steine nehmen, wenn sie sich durch eine Linie mit höchstens zwei Knicken verbinden lassen, die keinen anderen Stein berührt. Die Steine liegen flach, nicht gestapelt.","PLATO war ein Lernrechnersystem der Universität von Illinois, bekannt auch für die vielen Spiele, die schon früh darauf entstanden."],"cap":["Mahjong-Solitär in der Zeit: die Schildkröten-Legende, „Mah-Jongg“ auf PLATO 1981, „Shanghai“ 1986, Shisen-sho um 1989 und PCs ab 1990"]},{"h":"Probieren Sie es","p":["Suchen Sie zuerst alle nehmbaren Paare und entscheiden Sie dann, welches zuerst dran ist. Wenn drei oder vier gleiche Steine sichtbar sind, zeigt sich das Können.","Mahjong-Solitär in diesem Atlas ist ein reines 3D-Spiel mit der Schildkröte und vielen weiteren Aufstellungen. Jedes Spiel ist so angelegt, dass es sich vollständig abräumen lässt."],"cap":[]}],"tl":[["1981","Lockard schreibt „Mah-Jongg“ auf PLATO"],["1986","Als „Shanghai“ für Heimcomputer verkauft"],["1986","Beworben als Abkömmling der chinesischen „Schildkröte“ (ohne Beleg)"],["1989","Shisen-sho, das Steine per Linie verbindet, kommt in die Spielhallen"],["1990","Auch als mitgeliefertes PC-Spiel verbreitet"]],"figL":{"time":[["?","Die Schildkröten-Legende","altes chinesisches Spiel? (Werbung)"],["1981","Mah-Jongg","auf dem PLATO-System"],["1986","„Shanghai“","auf Heimcomputern"],["1989","Shisen-sho","Verwandter mit Linien"],["1990","Auf dem PC","mitgeliefertes Spiel"]]}},"samegame":{"title":"Gleiche Farbe, alles auf einmal","lead":"Bei SameGame entfernt man benachbarte Steine gleicher Farbe als Gruppe. 1985 auf einem japanischen Personal Computer entstanden, verbreitete es sich unter neuen Namen in aller Welt – als Urahn der Rätsel, bei denen man „das Brett leer räumt“.","s":["SameGame ist ein Rätsel für eine Person auf einem Brett voller farbiger Steine. Berühren sich zwei oder mehr Steine gleicher Farbe waagerecht oder senkrecht, kann man die ganze Gruppe auf einmal entfernen. Die Steine darüber fallen in die Lücke, und eine leere Spalte rückt nach links zusammen. Das Spiel endet, wenn keine Gruppe mehr übrig ist.","Es begann 1985 mit „Chain Shot!“, das Kuniaki Moribe für die damaligen japanischen Personal Computer schrieb. Es wurde über eine Computerzeitschrift verbreitet; das Brett maß 20×10, mit vier Farben.","1992 übertrug Eiji Fukumoto es als „SameGame“ auf Unix-Rechner und erhöhte die Farben auf fünf. Von da an verbreitete sich der Name. „Same“ ist das englische Wort für „gleich“.","Es folgten viele Umsetzungen und Neuauflagen auf Computern, Taschengeräten und Konsolen. Manche, wie „Clickomania!“ 1998, lassen Brettgröße und Farbanzahl frei einstellen.","Es sieht einfach aus, ist aber ein tiefes Rätsel. Eine Studie von 2001 zeigte, dass die Frage, ob sich ein Brett ganz leer räumen lässt, ein „NP-vollständiges“ Problem sein kann, wie Informatiker sagen – ein schweres."],"quiz":[["Was darf man bei SameGame entfernen?","Eine Gruppe aus zwei oder mehr benachbarten Steinen gleicher Farbe","Einen einzelnen Stein","Diagonal verbundene Steine","Nur die oberste Reihe"],["Wie viel ist eine Gruppe aus 10 Steinen bei der üblichen Wertung (n−2)² wert?","64","10","20","100"],["Was bedeutet „same“ in SameGame?","Das englische Wort für „gleich“","Eine Fischart","„Kalt“ auf Japanisch","Den Namen des Erfinders"]],"kf":["Zwei oder mehr benachbarte Steine gleicher Farbe dürfen weg. Darüberliegende fallen; leere Spalten rücken nach links","Es begann 1985 mit „Chain Shot!“; der Name verbreitete sich 1992 mit „SameGame“","In vielen Versionen bringt eine Gruppe (n−2)²: große Gruppen wachsen lassen und auf einmal entfernen"],"more":[{"h":"Entfernen, fallen, zusammenrücken","p":["Jede entfernte Gruppe verändert die ganze Form des Bretts. Herabfallende Steine können neue Gruppen bilden – oder eine Farbe zerteilen, die man aufsparen wollte.","Ein einzelner Stein lässt sich nicht entfernen. Wie wenige Steine bleiben am Ende übrig – schaffen Sie es, alles abzuräumen? Da zeigt sich das Können."],"cap":["Auf dem linken Brett wird die weiß markierte Gruppe aus fünf blauen Steinen entfernt (rechtes Brett): Die Steine darüber fallen (roter Pfeil), und die leere Spalte verschwindet, weil die Spalten rechts davon nach links rücken"]},{"h":"Je größer, desto besser","p":["In vielen Versionen bringt eine Gruppe aus n Steinen (n−2)² Punkte. Paare zählen nichts, fünf bringen 9, zehn bringen 64: Je größer die Gruppe, desto schneller wachsen die Punkte.","Der Grundplan lautet also: erst störende kleine Gruppen entfernen, eine Farbe zusammenführen und sie dann auf einmal abräumen. Viele Versionen geben außerdem einen großen Bonus fürs leere Brett."],"cap":["Gruppengröße n und Punkte (n−2)²: zwei Steine bringen 0, fünf bringen 9, zehn bringen 64. Zehn auf einmal sind viel mehr wert als zwei Gruppen zu fünf"]},{"h":"SameGame in der Zeit","p":["1994 entstand eine Macintosh-Version, und darauf aufbauende Versionen kamen später in freie Desktop-Umgebungen, gespielt in aller Welt.","Auch der ursprüngliche Erfinder Kuniaki Moribe schuf später eine eigene Neuauflage. Rätsel zum Leerräumen entstehen bis heute immer wieder neu."],"cap":["SameGame in der Zeit: „Chain Shot!“ 1985, „SameGame“ 1992, „Clickomania!“ 1998, der Schwierigkeitsbeweis 2001 und das „SameGame POP!“ dieses Atlas"]},{"h":"Probieren Sie es","p":["Versuchen Sie, die häufigste Farbe bis zuletzt aufzuheben und die anderen zuerst zu entfernen. Zu spüren, wie eine große Gruppe wächst, ist der Reiz von SameGame.","„SameGame POP!“ in diesem Atlas ist ein eigenes Spiel auf Grundlage dieser Regeln. Spielen Sie Stufen mit Spezialsteinen wie Eis und Prismen oder die Rätsel des Tages."],"cap":[]}],"tl":[["1985","Kuniaki Moribe schreibt „Chain Shot!“ (20×10, vier Farben)"],["1992","Eiji Fukumotos „SameGame“ für Unix: fünf Farben, der Name verbreitet sich"],["1994","Eine Macintosh-Version, Grundlage vieler späterer"],["1998","„Clickomania!“ mit einstellbarem Brett und Farben"],["2001","Bewiesen: Die Frage nach dem Leerräumen ist NP-vollständig"]],"figL":{"time":[["1985","Chain Shot!","Moribe · japanische PCs"],["1992","SameGame","Fukumoto · Unix · 5 Farben"],["1998","Clickomania!","Brett und Farben frei"],["2001","Schwierigkeitsbeweis","Leerräumen ist NP-vollständig"],["heute","SameGame POP!","Original dieses Atlas"]]}}};
